'use client'

import React, { useMemo } from 'react';
import { Group } from '@visx/group';
import { LinePath } from '@visx/shape';
import { curveMonotoneX, curveLinear } from '@visx/curve';
import type { LineDatum, LineInnerProps } from './Line.types';
import { LINE_DEFAULTS } from './Line.constants';
import { buildLineClasses, toDate, formatTick } from './Line.utils';
import { useLineAccessors, useLineScales, useLineColor, useLineInteraction, useInnerDims } from './Line.hooks';
import { adaptScale, plotLeft, plotTop, xAxisLayout, yAxisLayout } from '../_base/axisLayout';   // 0026 X7
import { ChartAxis } from '../primitives/ChartAxis';
import { ChartPointShape } from '../primitives/ChartPointShape';   // 0026 X8
import { ChartPointLabels, dateTickFormat, formatLabel, labelIndices, lineDash, dotShown, HalfDot } from '../primitives/ChartLineMarks';   // 0022 B53.1 / VX4
import { ChartGrid } from '../primitives/ChartGrid';
import { ChartReferenceLines, overlayPoints } from '../primitives/ChartReferenceLines';
import { ChartSecondaryAxes } from '../primitives/ChartSecondaryAxes';   // VX9
import { ChartErrorBars, ChartErrorBand, scaleForErrors } from '../primitives/ChartErrorBars';   // VX8, VX9
import { ChartTooltip } from '../primitives/ChartTooltip';
import { BASE_CHART_CLASSES } from '../_base/constants';
import { ChartHeader } from '../_base/ChartHeader';
import { pickCurve } from '../primitives/ChartLineMarks';   // VX4

export const LineInner: React.FC<LineInnerProps> = (props) => {
    const {
        data, width, height, margin, className,
        unstyled = LINE_DEFAULTS.unstyled, bindId, ariaLabel, description, colorScheme, title, subtitle,
        getDate: gD, getValue: gV,
        curved = LINE_DEFAULTS.curved, showDots = LINE_DEFAULTS.showDots,
        strokeWidth = LINE_DEFAULTS.strokeWidth,
        showXAxis = LINE_DEFAULTS.showXAxis, showYAxis = LINE_DEFAULTS.showYAxis,
        showGrid = LINE_DEFAULTS.showGrid, showTooltip = LINE_DEFAULTS.showTooltip,
        yDomain, formatY, onHover, onSelect,
        highlightIndex = null,
        lineStyle, dotRadius = 3, valueLabels = 'none', valueLabelSize = 11, xDateFormat,   // 0022 B53.1
    } = props;

    const { getDate, getValue } = useLineAccessors(gD, gV);
    const dims = useInnerDims(width, height, margin, props);
    const { xScale: xScaleRaw, yScale: yScaleRaw } = useLineScales(data, dims.innerWidth, dims.innerHeight, getDate, getValue, yDomain);
    const xScale = adaptScale(xScaleRaw, props, 'x');   // VX1: mínimo / máximo, log, al revés…
    const yScale = scaleForErrors(adaptScale(yScaleRaw, props, 'y'), data, getValue, props, 'y');   // VX1, VX8
    const color = useLineColor(colorScheme);
    const { hoveredIndex, handleEnter, handleLeave, handleClick } = useLineInteraction(onHover, onSelect);
    const classes = useMemo(() => buildLineClasses(className, unstyled), [className, unstyled]);
    const yTickFormat = formatY ?? formatTick;
    const curve = pickCurve(curved, props.lineStep, curveMonotoneX);   // VX4: escalonada

    if (data.length === 0) {
        return (<div className={classes}><svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Empty line chart'} /></div>);
    }

    return (
        <div className={classes} data-bind-id={bindId}>
            <ChartHeader title={title} subtitle={subtitle} />
            <div className={BASE_CHART_CLASSES.container} style={{ position: 'relative' }}>
                <svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Line chart'}>
                    {description && <desc>{description}</desc>}
                    <Group top={plotTop(dims, props)} left={plotLeft(dims, props)}>
                        {showGrid && <ChartGrid yScale={yScale} width={dims.innerWidth} height={dims.innerHeight} axis="rows" />}
                        <ChartErrorBand {...props} color={color} curve={curve} valueScale={(v: number) => yScale(v)}
                            items={data.map((d) => ({ at: xScale(toDate(getDate(d))) ?? 0, row: d, value: getValue(d) }))} />

                        {/* VX4 (gapcolor): debajo de la línea a rayas, la línea entera del color del hueco */}
                        {props.lineMode !== 'stem' && props.lineGapColor && lineStyle && lineStyle !== 'solid' && (
                            <LinePath data={[...data]} x={(d) => xScale(toDate(getDate(d))) ?? 0}
                                y={(d) => yScale(getValue(d)) ?? 0} stroke={props.lineGapColor} strokeWidth={strokeWidth}
                                curve={curve} className="w3f-chart-line-gap" />
                        )}
                        {props.lineMode !== 'stem' && (
                        <LinePath
                            data={[...data]}
                            x={(d) => xScale(toDate(getDate(d))) ?? 0}
                            y={(d) => yScale(getValue(d)) ?? 0}
                            stroke={color}
                            strokeWidth={strokeWidth}
                            {...lineDash(lineStyle, strokeWidth)}
                            curve={curve}
                        />
                        )}
                        {/* VX4 (stem): paletas — un palito desde la base hasta cada punto, y la línea de base */}
                        {props.lineMode === 'stem' && (() => {
                            const horizontal = props.stemOrientation === 'horizontal';
                            const yr = yScale.range() as number[];
                            const y0 = Math.min(Math.max(yScale(0) ?? yr[0], Math.min(...yr)), Math.max(...yr));
                            const base = props.stemBaseline ?? 'solid';
                            return (
                                <g className="w3f-chart-stems">
                                    {base !== 'none' && (horizontal
                                        ? <line x1={0} x2={0} y1={0} y2={dims.innerHeight} stroke="var(--w3f-chart-axis-stroke)" strokeWidth={1} {...lineDash(base === 'solid' ? undefined : base, 1)} />
                                        : <line x1={0} x2={dims.innerWidth} y1={y0} y2={y0} stroke="var(--w3f-chart-axis-stroke)" strokeWidth={1} {...lineDash(base === 'solid' ? undefined : base, 1)} />)}
                                    {data.map((d, i) => {
                                        const cx = xScale(toDate(getDate(d))) ?? 0;
                                        const cy = yScale(getValue(d)) ?? 0;
                                        return horizontal
                                            ? <line key={i} x1={0} x2={cx} y1={cy} y2={cy} stroke={color} strokeWidth={strokeWidth} {...lineDash(props.stemLineStyle, strokeWidth)} />
                                            : <line key={i} x1={cx} x2={cx} y1={y0} y2={cy} stroke={color} strokeWidth={strokeWidth} {...lineDash(props.stemLineStyle, strokeWidth)} />;
                                    })}
                                </g>
                            );
                        })()}

                        {(showDots || props.lineMode === 'stem') && data.map((d, i) => {
                            if (!dotShown(i, props.dotEvery)) return null;   // VX4: un punto cada N
                            const cx = xScale(toDate(getDate(d))) ?? 0;
                            const cy = yScale(getValue(d)) ?? 0;
                            if (props.dotFill && props.dotFill !== 'full') {   // VX4: medio lleno / hueco
                                return <HalfDot key={i} cx={cx} cy={cy} r={dotRadius} color={color} fill={props.dotFill}
                                    opacity={hoveredIndex != null && hoveredIndex !== i ? 0.4 : 1} />;
                            }
                            return (
                                <ChartPointShape
                                    key={i}
                                    shape={props.pointShape ?? 'circle'}
                                    cx={cx} cy={cy} r={hoveredIndex === i ? dotRadius + 2 : dotRadius}
                                    fill={color} stroke="var(--w3f-chart-mark-outline, #fff)" strokeWidth={1.5}
                                    opacity={hoveredIndex != null && hoveredIndex !== i ? 0.4 : 1}
                                    onMouseEnter={() => handleEnter(d, i)}
                                    onMouseLeave={handleLeave}
                                    onClick={onSelect ? () => handleClick(d, i) : undefined}
                                    style={{ cursor: onSelect ? 'pointer' : undefined, transition: 'r 120ms, opacity 120ms' }}
                                />
                            );
                        })}

                        {/* Invisible hover targets when dots are hidden */}
                        {!showDots && props.lineMode !== 'stem' && data.map((d, i) => {
                            const cx = xScale(toDate(getDate(d))) ?? 0;
                            const cy = yScale(getValue(d)) ?? 0;
                            return (
                                <circle
                                    key={i}
                                    cx={cx} cy={cy} r={8}
                                    fill="transparent"
                                    onMouseEnter={() => handleEnter(d, i)}
                                    onMouseLeave={handleLeave}
                                    onClick={onSelect ? () => handleClick(d, i) : undefined}
                                    style={{ cursor: onSelect ? 'pointer' : undefined }}
                                />
                            );
                        })}

                        {/* Hovered dot indicator */}
                        {hoveredIndex != null && (
                            <circle
                                cx={xScale(toDate(getDate(data[hoveredIndex]))) ?? 0}
                                cy={yScale(getValue(data[hoveredIndex])) ?? 0}
                                r={5} fill={color} stroke="var(--w3f-chart-mark-outline, #fff)" strokeWidth={2}
                                pointerEvents="none"
                            />
                        )}

                        {/* External highlight */}
                        {highlightIndex != null && highlightIndex < data.length && (() => {
                            const d = data[highlightIndex];
                            const cx = xScale(toDate(getDate(d))) ?? 0;
                            const cy = yScale(getValue(d)) ?? 0;
                            return (
                                <g pointerEvents="none">
                                    <line x1={cx} y1={0} x2={cx} y2={dims.innerHeight} stroke={color} strokeWidth={1} strokeDasharray="4 3" opacity={0.6} />
                                    <circle cx={cx} cy={cy} r={12} fill={color} opacity={0.2} />
                                    <circle cx={cx} cy={cy} r={6} fill={color} stroke="var(--w3f-chart-mark-outline, #fff)" strokeWidth={2.5} />
                                </g>
                            );
                        })()}

                        <ChartPointLabels size={valueLabelSize} labels={labelIndices(valueLabels, data.map(getValue)).map((i) => ({
                            x: xScale(toDate(getDate(data[i]))) ?? 0, y: yScale(getValue(data[i])) ?? 0,
                            text: formatLabel(getValue(data[i]), formatY) }))} />
                        {showXAxis && <ChartAxis scale={xScale} {...xAxisLayout(dims, props)} tickFormat={dateTickFormat(xDateFormat)} />}
                        {showYAxis && <ChartAxis scale={yScale} {...yAxisLayout(dims, props)} tickFormat={yTickFormat} />}
                        <ChartErrorBars {...props} valueScale={(v: number) => yScale(v)}
                            items={data.map((d) => ({ at: xScale(toDate(getDate(d))) ?? 0, row: d, value: getValue(d) }))} />
                        <ChartSecondaryAxes {...props} xScale={xScale} yScale={yScale} width={dims.innerWidth} height={dims.innerHeight} />
                        <ChartReferenceLines lines={props.referenceLines} bands={props.referenceBands} annotation={props.annotation}
                            points={overlayPoints(data)} xScale={xScale}
                            yScale={(v: number) => yScale(v)} width={dims.innerWidth} height={dims.innerHeight} />
                    </Group>
                </svg>

                {showTooltip && hoveredIndex != null && (() => {
                    const d = data[hoveredIndex];
                    const date = toDate(getDate(d));
                    return (
                        <ChartTooltip
                            left={(xScale(date) ?? 0) + plotLeft(dims, props)}
                            top={(yScale(getValue(d)) ?? 0) + plotTop(dims, props)}
                            visible offsetY={-12}
                        >
                            {`${date.toLocaleDateString()}: ${getValue(d).toLocaleString()}`}
                        </ChartTooltip>
                    );
                })()}
            </div>
        </div>
    );
};

LineInner.displayName = 'LineInner';
export default LineInner;
