import { useState, useMemo, useCallback, useRef, useEffect } from 'react';
import type { SortState, SortDirection, TableColumn, DropEdge, DragState, RowDropEdge, TableQuery } from './Table.types';
import { MIN_COLUMN_WIDTH, DRAG_DEAD_ZONE, FILTER_DEBOUNCE_MS } from './Table.constants';

// ─── useTableSort ───

export const useTableSort = () => {
    const [sortState, setSortState] = useState<SortState>({ key: null, direction: null });

    const handleSort = useCallback((columnKey: string) => {
        setSortState(prev => {
            if (prev.key !== columnKey) return { key: columnKey, direction: 'asc' as SortDirection };
            if (prev.direction === 'asc') return { key: columnKey, direction: 'desc' as SortDirection };
            return { key: null, direction: null };
        });
    }, []);

    return { sortState, handleSort };
};

// ─── useTableFilter ───

export const useTableFilter = <T extends Record<string, unknown>>(
    data: T[],
    columns: TableColumn<T>[]
) => {
    const [globalFilter, setGlobalFilter] = useState('');

    const handleFilterChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
        setGlobalFilter(e.target.value);
    }, []);

    const filteredData = useMemo(() => {
        if (!globalFilter.trim()) return data;
        const search = globalFilter.toLowerCase().trim();
        return data.filter(row =>
            columns.some(col => {
                if (col.cell) return false;
                const value = row[col.accessorKey];
                if (value == null) return false;
                return String(value).toLowerCase().includes(search);
            })
        );
    }, [data, columns, globalFilter]);

    return { globalFilter, handleFilterChange, filteredData };
};

// ─── useTablePagination ───

export const useTablePagination = (totalItems: number, initialPageSize: number) => {
    const [currentPage, setCurrentPage] = useState(1);
    const [pageSize, setPageSize] = useState(initialPageSize);

    const totalPages = useMemo(
        () => Math.max(1, Math.ceil(totalItems / pageSize)),
        [totalItems, pageSize]
    );

    const handlePageSizeChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => {
        setPageSize(Number(e.target.value));
        setCurrentPage(1);
    }, []);

    const resetPage = useCallback(() => setCurrentPage(1), []);

    return { currentPage, setCurrentPage, pageSize, totalPages, handlePageSizeChange, resetPage };
};

// ─── useManualQuery ───

/**
 * Modo manual: avisa con `onQueryChange` cada cambio de página, filas por página, orden o búsqueda.
 * - Al montar pide su página una vez: si la tabla se remonta (recarga en caliente, ventana que se vuelve
 *   a montar) su estado vuelve a página 1 / sin búsqueda y el servidor tiene que mandar esa página.
 * - La búsqueda espera FILTER_DEBOUNCE_MS después de la última tecla.
 * - Si cambian el orden o la búsqueda estando en otra página, vuelve a la 1 y avisa una sola vez.
 * - Nunca repite la última consulta enviada (React.StrictMode corre los efectos dos veces en desarrollo).
 */
export const useManualQuery = (
    manual: boolean,
    currentPage: number,
    pageSize: number,
    sortState: SortState,
    globalFilter: string,
    setCurrentPage: (page: number) => void,
    onQueryChange?: (query: TableQuery) => void,
) => {
    const [filter, setFilter] = useState(globalFilter.trim());
    useEffect(() => {
        if (!manual) return;
        const id = setTimeout(() => setFilter(globalFilter.trim()), FILTER_DEBOUNCE_MS);
        return () => clearTimeout(id);
    }, [manual, globalFilter]);

    const callbackRef = useRef(onQueryChange);
    callbackRef.current = onQueryChange;
    const keyRef = useRef<string | null>(null);      // orden + búsqueda de la última vez
    const sentRef = useRef<string | null>(null);     // última consulta enviada (o la del montaje)
    const resettingRef = useRef(false);              // esperando volver a la página 1

    useEffect(() => {
        if (!manual) return;
        const query: TableQuery = {
            page: currentPage, pageSize,
            sortKey: sortState.key, sortDirection: sortState.direction, filter,
        };
        const key = JSON.stringify([query.sortKey, query.sortDirection, filter]);
        const sig = JSON.stringify(query);
        if (keyRef.current === null) keyRef.current = key;   // montaje: se avisa abajo
        if (key !== keyRef.current) {
            keyRef.current = key;
            if (currentPage !== 1) {
                resettingRef.current = true;
                setCurrentPage(1);                   // el próximo render avisa con la página 1
                return;
            }
        }
        if (resettingRef.current) {
            if (currentPage !== 1) return;
            resettingRef.current = false;
        }
        if (sig === sentRef.current) return;
        sentRef.current = sig;
        callbackRef.current?.(query);
    }, [manual, currentPage, pageSize, sortState, filter, setCurrentPage]);
};

// ─── useColumnResize ───

export const useColumnResize = (
    initial?: Record<string, number>,
    onChange?: (widths: Record<string, number>) => void,
    fit = false,
) => {
    const [columnWidths, setColumnWidths] = useState<Record<string, number>>(() => ({ ...(initial ?? {}) }));
    const resizeRef = useRef<{ columnKey: string; startX: number; startWidth: number } | null>(null);
    const widthsInitializedRef = useRef(false);
    // 0026 X17: los anchos vigentes y el aviso, legibles desde el mouseup (que no se vuelve a crear)
    const widthsRef = useRef(columnWidths);
    widthsRef.current = columnWidths;
    const changeRef = useRef(onChange);
    changeRef.current = onChange;
    const initialRef = useRef(initial);
    initialRef.current = initial;

    const initWidths = useCallback((headerRow: HTMLTableRowElement | null) => {
        if (widthsInitializedRef.current || !headerRow) return;
        const cells = headerRow.querySelectorAll('th');
        if (cells.length === 0) return;

        const widths: Record<string, number> = {};
        cells.forEach((cell) => {
            const key = cell.getAttribute('data-column-key');
            if (key) widths[key] = cell.offsetWidth;
        });

        if (Object.keys(widths).length > 0) {
            setColumnWidths({ ...widths, ...(initialRef.current ?? {}) });   // los anchos guardados mandan
            widthsInitializedRef.current = true;
        }
    }, []);

    // 0026 X17: otro objeto de anchos iniciales (p. ej. al abrir un proyecto) se aplica encima de lo medido
    const initialKey = JSON.stringify(initial ?? {});
    useEffect(() => {
        if (initial && Object.keys(initial).length) setColumnWidths(prev => ({ ...prev, ...initial }));
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [initialKey]);

    const handleResizeMouseDown = useCallback((e: React.MouseEvent, columnKey: string) => {
        e.stopPropagation();
        e.preventDefault();

        const startX = e.clientX;
        let startWidth = columnWidths[columnKey] || 100;
        // 0022 B44 (fitWidth): los anchos son proporciones de la caja. Se parte de lo que se ve (medido en la fila de
        // encabezados), el mouse se pasa a px de la tabla (con el zoom del tablero) y las otras columnas se reparten lo
        // que queda: el total no cambia y el borde sigue al mouse
        let fitStart: Record<string, number> | null = null;
        let scale = 1;
        if (fit) {
            const row = (e.currentTarget as HTMLElement | null)?.closest('tr');
            const cells = row ? [...row.querySelectorAll<HTMLElement>('th[data-column-key]')] : [];
            if (cells.length) {
                fitStart = {};
                for (const c of cells) fitStart[c.dataset.columnKey as string] = c.offsetWidth;
                const th = cells.find((c) => c.dataset.columnKey === columnKey);
                const shown = th ? th.getBoundingClientRect().width : 0;
                scale = th && th.offsetWidth && shown ? shown / th.offsetWidth : 1;
                startWidth = fitStart[columnKey] || startWidth;
            }
        }
        resizeRef.current = { columnKey, startX, startWidth };
        document.body.classList.add('w3f-table-resizing');

        const onMouseMove = (moveEvent: MouseEvent) => {
            const delta = (moveEvent.clientX - startX) / (scale || 1);
            if (fitStart) {
                const start = fitStart;
                const total = Object.values(start).reduce((a, b) => a + b, 0);
                const others = total - start[columnKey];
                const minOthers = MIN_COLUMN_WIDTH * (Object.keys(start).length - 1);
                const mine = Math.min(Math.max(MIN_COLUMN_WIDTH, startWidth + delta), total - minOthers);
                const k = others > 0 ? (total - mine) / others : 1;
                const next: Record<string, number> = {};
                for (const [key, w] of Object.entries(start)) {
                    next[key] = key === columnKey ? Math.round(mine) : Math.max(MIN_COLUMN_WIDTH, Math.round(w * k));
                }
                setColumnWidths(prev => ({ ...prev, ...next }));
                return;
            }
            const newWidth = Math.max(MIN_COLUMN_WIDTH, startWidth + delta);
            setColumnWidths(prev => ({ ...prev, [columnKey]: newWidth }));
        };

        const onMouseUp = () => {
            document.removeEventListener('mousemove', onMouseMove);
            document.removeEventListener('mouseup', onMouseUp);
            document.body.classList.remove('w3f-table-resizing');
            resizeRef.current = null;
            changeRef.current?.({ ...widthsRef.current });   // 0026 X17: la app guarda los anchos
        };

        document.addEventListener('mousemove', onMouseMove);
        document.addEventListener('mouseup', onMouseUp);
    }, [columnWidths, fit]);

    return { columnWidths, initWidths, handleResizeMouseDown, widthsInitializedRef };
};

// ─── useColumnReorder ───

export const useColumnReorder = <T extends Record<string, unknown>>(
    columns: TableColumn<T>[],
    onColumnOrderChange?: (order: string[]) => void,
) => {
    const [columnOrder, setColumnOrder] = useState<string[]>(() => columns.map(c => c.accessorKey));
    // 0022 C-M: el orden vigente y el aviso a la app, legibles desde el handler (que no se vuelve a crear)
    const orderRef = useRef<string[]>(columnOrder);
    orderRef.current = columnOrder;
    const changeRef = useRef(onColumnOrderChange);
    changeRef.current = onColumnOrderChange;
    const dragRef = useRef<DragState | null>(null);
    const ghostRef = useRef<HTMLDivElement | null>(null);
    const indicatorRef = useRef<HTMLDivElement | null>(null);

    // Sync columnOrder when columns change. If the prop's keys or their order actually changed (e.g. the server
    // moved, split or inserted a column), the prop order wins; the user's drag order survives only re-renders
    // that pass the same columns again.
    const propKeysRef = useRef<string>(columns.map(c => c.accessorKey).join('\u0000'));
    useEffect(() => {
        const currentKeys = columns.map(c => c.accessorKey);
        const joined = currentKeys.join('\u0000');
        if (joined === propKeysRef.current) return;
        propKeysRef.current = joined;
        setColumnOrder(currentKeys);
    }, [columns]);

    const orderedColumns = useMemo(() => {
        const columnMap: Record<string, TableColumn<T>> = {};
        columns.forEach(c => { columnMap[c.accessorKey] = c; });
        return columnOrder.map(key => columnMap[key]).filter(Boolean);
    }, [columns, columnOrder]);

    const handleDragMouseDown = useCallback((
        e: React.MouseEvent<HTMLTableCellElement>,
        columnKey: string,
        headerRowRef: React.RefObject<HTMLTableRowElement | null>
    ) => {
        if ((e.target as HTMLElement).closest('.w3f-table-resize-handle')) return;
        if (e.button !== 0) return;
        e.stopPropagation();   // la Window de arriba no empieza a moverse con este mousedown (0022 C-M)

        const startX = e.clientX;
        const startY = e.clientY;
        const th = e.currentTarget;
        let isDragging = false;

        const onMouseMove = (moveEvent: MouseEvent) => {
            const dx = moveEvent.clientX - startX;
            const dy = moveEvent.clientY - startY;

            if (!isDragging && Math.sqrt(dx * dx + dy * dy) < DRAG_DEAD_ZONE) return;

            if (!isDragging) {
                isDragging = true;
                dragRef.current = { columnKey, sourceEl: th };
                document.body.classList.add('w3f-table-dragging-body');
                th.classList.add('w3f-table-th-dragging');

                const ghost = document.createElement('div');
                ghost.className = 'w3f-table-drag-ghost';
                ghost.textContent = th.textContent;
                document.body.appendChild(ghost);
                ghostRef.current = ghost;

                const indicator = document.createElement('div');
                indicator.className = 'w3f-table-drop-indicator';
                indicator.style.display = 'none';
                document.body.appendChild(indicator);
                indicatorRef.current = indicator;
            }

            if (ghostRef.current) {
                ghostRef.current.style.left = `${moveEvent.clientX + 12}px`;
                ghostRef.current.style.top = `${moveEvent.clientY - 16}px`;
            }

            if (headerRowRef.current && indicatorRef.current) {
                const headerCells = Array.from(headerRowRef.current.querySelectorAll('th'));
                let closestEdge: DropEdge | null = null;
                let closestDist = Infinity;

                for (const cell of headerCells) {
                    const cellKey = cell.getAttribute('data-column-key');
                    if (cellKey === columnKey) continue;

                    const rect = cell.getBoundingClientRect();
                    const leftDist = Math.abs(moveEvent.clientX - rect.left);
                    const rightDist = Math.abs(moveEvent.clientX - rect.right);

                    if (leftDist < closestDist) {
                        closestDist = leftDist;
                        closestEdge = { x: rect.left, top: rect.top, height: rect.height, beforeKey: cellKey ?? undefined };
                    }
                    if (rightDist < closestDist) {
                        closestDist = rightDist;
                        closestEdge = { x: rect.right, top: rect.top, height: rect.height, afterKey: cellKey ?? undefined };
                    }
                }

                if (closestEdge && closestDist < 40) {
                    indicatorRef.current.style.display = 'block';
                    indicatorRef.current.style.left = `${closestEdge.x - 1}px`;
                    indicatorRef.current.style.top = `${closestEdge.top}px`;
                    indicatorRef.current.style.height = `${closestEdge.height}px`;
                    dragRef.current!.dropEdge = closestEdge;
                } else {
                    indicatorRef.current.style.display = 'none';
                    if (dragRef.current) dragRef.current.dropEdge = null;
                }
            }
        };

        const onMouseUp = () => {
            document.removeEventListener('mousemove', onMouseMove);
            document.removeEventListener('mouseup', onMouseUp);

            if (isDragging && dragRef.current) {
                const { columnKey: dragKey, dropEdge, sourceEl } = dragRef.current;

                sourceEl.classList.remove('w3f-table-th-dragging');
                document.body.classList.remove('w3f-table-dragging-body');
                if (ghostRef.current) { ghostRef.current.remove(); ghostRef.current = null; }
                if (indicatorRef.current) { indicatorRef.current.remove(); indicatorRef.current = null; }

                if (dropEdge) {
                    const prev = orderRef.current;
                    const newOrder = prev.filter(k => k !== dragKey);
                    const targetKey = dropEdge.beforeKey || dropEdge.afterKey;
                    let insertIdx = targetKey ? newOrder.indexOf(targetKey) : -1;
                    if (targetKey && insertIdx !== -1) {
                        if (dropEdge.afterKey) insertIdx += 1;
                        newOrder.splice(insertIdx, 0, dragKey);
                        setColumnOrder(newOrder);
                        changeRef.current?.(newOrder);   // 0022 C-M: la app se entera del orden nuevo
                    }
                }

                dragRef.current = null;
            }
        };

        document.addEventListener('mousemove', onMouseMove);
        document.addEventListener('mouseup', onMouseUp);
    }, []);

    return { columnOrder, orderedColumns, handleDragMouseDown };
};

// ─── useRowReorder (0022 C-M) ───
// Arrastrar una fila por su primera celda: fantasma con el texto de la celda, una línea horizontal en el borde de la
// fila más cercana y, al soltar, el aviso (fromIndex, toIndex, position) con los índices de la página visible.

export const useRowReorder = (onDrop?: (fromIndex: number, toIndex: number, position: 'before' | 'after') => void) => {
    const dropRef = useRef(onDrop);
    dropRef.current = onDrop;
    const ghostRef = useRef<HTMLDivElement | null>(null);
    const indicatorRef = useRef<HTMLDivElement | null>(null);

    const handleRowDragMouseDown = useCallback((
        e: React.MouseEvent<HTMLTableCellElement>,
        rowIndex: number,
        tbodyRef: React.RefObject<HTMLTableSectionElement | null>
    ) => {
        if (e.button !== 0) return;
        e.stopPropagation();   // idem: que no arrastre la Window
        const startX = e.clientX;
        const startY = e.clientY;
        const td = e.currentTarget;
        const tr = td.closest('tr') as HTMLTableRowElement | null;
        let isDragging = false;
        let edge: RowDropEdge | null = null;

        const onMouseMove = (moveEvent: MouseEvent) => {
            const dx = moveEvent.clientX - startX;
            const dy = moveEvent.clientY - startY;
            if (!isDragging && Math.sqrt(dx * dx + dy * dy) < DRAG_DEAD_ZONE) return;
            if (!isDragging) {
                isDragging = true;
                document.body.classList.add('w3f-table-dragging-body');
                tr?.classList.add('w3f-table-tr-dragging');
                const ghost = document.createElement('div');
                ghost.className = 'w3f-table-drag-ghost';
                ghost.textContent = td.textContent;
                document.body.appendChild(ghost);
                ghostRef.current = ghost;
                const indicator = document.createElement('div');
                indicator.className = 'w3f-table-drop-indicator w3f-table-drop-indicator--row';
                indicator.style.display = 'none';
                document.body.appendChild(indicator);
                indicatorRef.current = indicator;
            }
            if (ghostRef.current) {
                ghostRef.current.style.left = `${moveEvent.clientX + 12}px`;
                ghostRef.current.style.top = `${moveEvent.clientY - 16}px`;
            }
            if (tbodyRef.current && indicatorRef.current) {
                const rows = Array.from(tbodyRef.current.querySelectorAll('tr'));
                let closest: RowDropEdge | null = null;
                let closestDist = Infinity;
                rows.forEach((row) => {
                    const idx = Number(row.getAttribute('data-row-index'));
                    if (!Number.isFinite(idx) || idx === rowIndex) return;
                    const rect = row.getBoundingClientRect();
                    const topDist = Math.abs(moveEvent.clientY - rect.top);
                    const bottomDist = Math.abs(moveEvent.clientY - rect.bottom);
                    if (topDist < closestDist) {
                        closestDist = topDist;
                        closest = { y: rect.top, left: rect.left, width: rect.width, index: idx, position: 'before' };
                    }
                    if (bottomDist < closestDist) {
                        closestDist = bottomDist;
                        closest = { y: rect.bottom, left: rect.left, width: rect.width, index: idx, position: 'after' };
                    }
                });
                if (closest && closestDist < 40) {
                    const c = closest as RowDropEdge;
                    indicatorRef.current.style.display = 'block';
                    indicatorRef.current.style.left = `${c.left}px`;
                    indicatorRef.current.style.top = `${c.y - 1}px`;
                    indicatorRef.current.style.width = `${c.width}px`;
                    edge = c;
                } else {
                    indicatorRef.current.style.display = 'none';
                    edge = null;
                }
            }
        };

        const onMouseUp = () => {
            document.removeEventListener('mousemove', onMouseMove);
            document.removeEventListener('mouseup', onMouseUp);
            if (!isDragging) return;
            tr?.classList.remove('w3f-table-tr-dragging');
            document.body.classList.remove('w3f-table-dragging-body');
            if (ghostRef.current) { ghostRef.current.remove(); ghostRef.current = null; }
            if (indicatorRef.current) { indicatorRef.current.remove(); indicatorRef.current = null; }
            if (edge) dropRef.current?.(rowIndex, edge.index, edge.position);
        };

        document.addEventListener('mousemove', onMouseMove);
        document.addEventListener('mouseup', onMouseUp);
    }, []);

    return { handleRowDragMouseDown };
};
