'use client'

import React, { useMemo } from 'react';
import { Group } from '@visx/group';
import { Pie as VisxPie } from '@visx/shape';
import type { PieInnerProps } from './Pie.types';
import { PIE_DEFAULTS } from './Pie.constants';
import { buildPieClasses, buildTooltipContent, centroidAngle, labelFits } from './Pie.utils';
import { usePieAccessors, usePieColors, usePieInteraction } from './Pie.hooks';
import { ChartTooltip } from '../primitives/ChartTooltip';
import { ChartLegend } from '../primitives/ChartLegend';
import { BASE_CHART_CLASSES } from '../_base/constants';
import { ChartHeader } from '../_base/ChartHeader';
import { ChartMarkDecorLayer } from '../primitives/ChartMarkDecor';   // VX3

/** 0022 B53.2: el texto del rótulo de una porción. */
export const sliceText = (mode: string, name: string, value: number, total: number): string => {
    const pct = total ? `${((value / total) * 100).toLocaleString('es-AR', { maximumFractionDigits: 1 })} %` : '';
    const val = value.toLocaleString('es-AR', { maximumFractionDigits: 2 });
    switch (mode) {
        case 'value': return val;
        case 'percent': return pct;
        case 'name_percent': return `${name} ${pct}`;
        case 'name_value': return `${name} ${val}`;
        default: return name;
    }
};

export const PieInner: React.FC<PieInnerProps> = (props) => {
    const {
        data, width, height, className,
        unstyled = PIE_DEFAULTS.unstyled, bindId, ariaLabel, description, colorScheme, title, subtitle,
        getValue: gvp, getLabel: glp,
        innerRadius: innerRadioProp = PIE_DEFAULTS.innerRadius,
        padAngle = PIE_DEFAULTS.padAngle,
        cornerRadius = PIE_DEFAULTS.cornerRadius,
        showLabels = PIE_DEFAULTS.showLabels,
        showTooltip = PIE_DEFAULTS.showTooltip,
        showLegend = PIE_DEFAULTS.showLegend,
        onHover, onSelect,
        highlightIndex = null,
        sliceLabel = 'name', labelPosition = 'inside', sliceLabelSize = 11, startAngle = 0, sliceOrder = 'auto',   // B53.2
        explode = 'none', explodeOffset = 10, counterClockwise = false, rotateLabels = false,   // VX3
    } = props;

    const { getValue, getLabel } = usePieAccessors(gvp, glp);
    const colors = usePieColors(data, colorScheme);
    const { hoveredIndex, handleEnter, handleLeave, handleClick } = usePieInteraction(onHover, onSelect);

    const classes = useMemo(() => buildPieClasses(className, unstyled), [className, unstyled]);

    const legendHeight = showLegend ? 36 : 0;
    const svgHeight = height - legendHeight;
    const outside = labelPosition === 'outside';
    const radius = Math.min(width, svgHeight) / 2 * (outside ? 0.68 : 0.85);   // afuera hace falta lugar para el rótulo
    const total = useMemo(() => data.reduce((s, d) => s + (Number(getValue(d)) || 0), 0), [data, getValue]);
    const maxValue = useMemo(() => Math.max(0, ...data.map((d) => Number(getValue(d)) || 0)), [data, getValue]);   // VX3
    const start = (startAngle * Math.PI) / 180;
    const sortProps = sliceOrder === 'data' ? { pieSort: null, pieSortValues: null }
        : sliceOrder === 'asc' ? { pieSortValues: (a: number, b: number) => a - b } : {};
    const innerR = radius * innerRadioProp;
    const cx = width / 2;
    const cy = svgHeight / 2;

    const legendItems = useMemo(
        () => data.map((d, i) => ({ id: d.id, label: d.label, color: colors[i] })),
        [data, colors],
    );

    if (data.length === 0) {
        return (
            <div className={classes}>
                <svg width={width} height={svgHeight} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Empty pie chart'} />
            </div>
        );
    }

    return (
        <div className={classes} data-bind-id={bindId}>
            <ChartHeader title={title} subtitle={subtitle} />
            <div className={BASE_CHART_CLASSES.container} style={{ position: 'relative' }}>
                <svg width={width} height={svgHeight} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Pie chart'}>
                    {description && <desc>{description}</desc>}
                    <Group top={cy} left={cx}>
                        <VisxPie
                            data={[...data]}
                            pieValue={getValue}
                            outerRadius={radius}
                            innerRadius={innerR}
                            padAngle={padAngle}
                            cornerRadius={cornerRadius}
                            startAngle={start}
                            endAngle={counterClockwise ? start - 2 * Math.PI : start + 2 * Math.PI}   /* VX3: counterclock */
                            {...sortProps}
                        >
                            {(pie) =>
                                pie.arcs.map((arc, i) => {
                                    const d = arc.data;
                                    const isHighlighted = highlightIndex != null && highlightIndex === i;
                                    const opacity = highlightIndex != null
                                        ? (isHighlighted ? 1 : 0.3)
                                        : (hoveredIndex != null && hoveredIndex !== i ? 0.5 : 1);
                                    const path = pie.path(arc) ?? '';

                                    // Centroid for label
                                    const [lx, ly] = pie.path.centroid(arc);
                                    // VX3 (explode): la porción separada del centro, hacia afuera por su ángulo del medio
                                    const mid = (arc.startAngle + arc.endAngle) / 2;
                                    const out = explode === 'all' || (explode === 'first' && i === 0)
                                        || (explode === 'largest' && Number(getValue(d)) === maxValue);
                                    const shift = out ? `translate(${Math.sin(mid) * explodeOffset}, ${-Math.cos(mid) * explodeOffset})` : undefined;
                                    // VX3 (rotatelabels): el rótulo girado según su porción, siempre legible
                                    let deg = (mid * 180) / Math.PI - 90;
                                    if (deg > 90) deg -= 180;
                                    if (deg < -90) deg += 180;

                                    return (
                                        <g
                                            key={d.id}
                                            opacity={opacity}
                                            transform={shift}
                                            style={{ transition: 'opacity 120ms ease-out', cursor: onSelect ? 'pointer' : undefined }}
                                            onMouseEnter={() => handleEnter(d, i)}
                                            onMouseLeave={handleLeave}
                                            onClick={onSelect ? () => handleClick(d, i) : undefined}
                                        >
                                            <path
                                                d={path}
                                                fill={colors[i]}
                                                className="w3f-chart-slice"
                                                data-hl={isHighlighted ? '1' : undefined}
                                                stroke={isHighlighted ? 'var(--w3f-chart-mark-outline, #fff)' : undefined}
                                                strokeWidth={isHighlighted ? 2 : undefined}
                                            />
                                            {showLabels && !outside && labelFits(arc.startAngle, arc.endAngle) && (
                                                <text
                                                    x={lx}
                                                    y={ly}
                                                    transform={rotateLabels ? `rotate(${deg}, ${lx}, ${ly})` : undefined}
                                                    fill="var(--w3f-chart-inner-label-color, #fff)"
                                                    fontSize={sliceLabelSize}
                                                    fontWeight={600}
                                                    textAnchor="middle"
                                                    dominantBaseline="central"
                                                    pointerEvents="none"
                                                    className="w3f-chart-slice-label"
                                                >
                                                    {sliceText(sliceLabel, getLabel(d), Number(getValue(d)) || 0, total)}
                                                </text>
                                            )}
                                            {showLabels && outside && arc.endAngle - arc.startAngle > 0.04 && (() => {
                                                const a = (arc.startAngle + arc.endAngle) / 2;
                                                const sx = Math.sin(a), sy = -Math.cos(a);
                                                const right = sx >= 0;
                                                const ex = (radius + 14) * sx, ey = (radius + 14) * sy;
                                                return (
                                                    <g pointerEvents="none">
                                                        <polyline points={`${radius * sx},${radius * sy} ${ex},${ey} ${ex + (right ? 8 : -8)},${ey}`}
                                                            fill="none" stroke={colors[i]} strokeWidth={1} />
                                                        <text x={ex + (right ? 11 : -11)} y={ey} fontSize={sliceLabelSize}
                                                            textAnchor={right ? 'start' : 'end'} dominantBaseline="central"
                                                            className="w3f-chart-slice-label"
                                                            style={{ fill: 'var(--w3f-chart-value-label-color, #888899)',
                                                                     fontFamily: 'var(--w3f-chart-label-font, inherit)' }}>
                                                            {sliceText(sliceLabel, getLabel(d), Number(getValue(d)) || 0, total)}
                                                        </text>
                                                    </g>
                                                );
                                            })()}
                                        </g>
                                    );
                                })
                            }
                        </VisxPie>
                    </Group>
                    <ChartMarkDecorLayer {...props} />   {/* VX3: trama, hueco, borde de dos colores */}
                </svg>

                {showTooltip && hoveredIndex != null && (() => {
                    const d = data[hoveredIndex];
                    return (
                        <ChartTooltip left={cx} top={cy} visible offsetY={-radius - 12}>
                            {buildTooltipContent(d, getValue)}
                        </ChartTooltip>
                    );
                })()}
            </div>

            {showLegend && (
                <ChartLegend items={legendItems} direction="horizontal" />
            )}
        </div>
    );
};

PieInner.displayName = 'PieInner';
export default PieInner;
