/**
 * VX9 (matplotlib hexbin): points grouped in a grid of pointy hexagons (the d3-hexbin algorithm), in pixels.
 */
export type HexBin = { x: number; y: number; n: number };

export function hexBins(points: readonly [number, number][], size: number): HexBin[] {
    const r = Math.max(2, size);
    const dx = r * Math.sqrt(3);
    const dy = r * 1.5;
    const bins = new Map<string, HexBin>();
    for (const [x, y] of points) {
        if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
        let py = y / dy;
        let pj = Math.round(py);
        let px = x / dx - (pj & 1) / 2;
        let pi = Math.round(px);
        const py1 = py - pj;
        if (Math.abs(py1) * 3 > 1) {
            const px1 = px - pi;
            const pi2 = pi + (px < pi ? -1 : 1) / 2;
            const pj2 = pj + (py < pj ? -1 : 1);
            const px2 = px - pi2;
            const py2 = py - pj2;
            if (px1 * px1 + py1 * py1 > px2 * px2 + py2 * py2) {
                pi = pi2 + ((pj & 1) ? 1 : -1) / 2;
                pj = pj2;
            }
        }
        const key = `${pi},${pj}`;
        const b = bins.get(key);
        if (b) b.n += 1;
        else bins.set(key, { x: (pi + (pj & 1) / 2) * dx, y: pj * dy, n: 1 });
    }
    return [...bins.values()];
}

/** The path of a pointy hexagon of radius `size` centered at (x, y). */
export function hexPath(x: number, y: number, size: number): string {
    const pts = [0, 1, 2, 3, 4, 5].map((k) => {
        const a = (Math.PI / 3) * k;
        return `${(x + Math.sin(a) * size).toFixed(2)},${(y - Math.cos(a) * size).toFixed(2)}`;
    });
    return `M${pts.join('L')}Z`;
}
