/**
 * 0026 X7 (w3f-data-analysis): dónde van los ejes de los gráficos con ejes.
 *
 * - `xLabels`: los rótulos del eje X abajo (como siempre), arriba o sin rótulos.
 * - `xLabelRotate`: girados (grados; -45 / -90 cuando son muchos y se pisan).
 * - `yAxisSide`: el eje Y a la izquierda (como siempre) o a la derecha.
 *
 * El dibujo se corre para que los rótulos entren: con el eje Y a la derecha, el margen izquierdo (el de los números)
 * pasa a la derecha (`plotLeft`); con los rótulos del eje X arriba, el de abajo pasa arriba (`plotTop`).
 */
import { scaleLog } from '@visx/scale';
import type { InnerDims } from './types';

export type ChartXLabels = 'bottom' | 'top' | 'none';
export type ChartYAxisSide = 'left' | 'right';

export interface ChartAxisLayoutProps {
    /** 0026 X7: rótulos del eje X abajo, arriba o ninguno. Default 'bottom'. */
    xLabels?: ChartXLabels;
    /** 0026 X7: giro de los rótulos del eje X (grados). */
    xLabelRotate?: number;
    /** 0026 X7: el eje Y a la izquierda o a la derecha. Default 'left'. */
    yAxisSide?: ChartYAxisSide;
    /** VX1 (matplotlib xlim / ylim): mínimo y máximo de un eje de números (sin valor = el de los datos). */
    xMin?: number;
    xMax?: number;
    yMin?: number;
    yMax?: number;
    /** VX1 (xscale / yscale): escala lineal o logarítmica de un eje de números. */
    xScaleType?: 'linear' | 'log';
    yScaleType?: 'linear' | 'log';
    /** VX1 (invert_xaxis / invert_yaxis): el eje al revés. */
    xInvert?: boolean;
    yInvert?: boolean;
    /** VX1 (xmargin / ymargin): margen antes del primer y después del último dato (fracción del rango, 0.1 = 10 %). */
    xMargin?: number;
    yMargin?: number;
    /** VX1 (xticks / yticks): cuántas marcas (aproximado; la grilla sigue a las mismas). */
    xTickCount?: number;
    yTickCount?: number;
    /** VX1 (tick_params): las rayitas de los ejes: se ven, también del otro lado, hacia afuera / adentro, largo, grosor
     *  y espacio hasta el rótulo (px). */
    showTicks?: boolean;
    ticksBothSides?: boolean;
    tickDirection?: 'out' | 'in';
    tickLength?: number;
    tickWidth?: number;
    tickPad?: number;
    /** VX1 (frame_on): un marco alrededor del área del dibujo. */
    plotFrame?: boolean;
    /** VX1 (aspect / box_aspect): alto / ancho del área del dibujo (1 = cuadrada; sin valor = la que deja la tarjeta). */
    plotAspect?: number;
    /** VX5 (Text.wrap): los rótulos largos del eje X en varios renglones (en vez de girarlos). */
    labelWrap?: boolean;
}

/** VX5: las palabras de `text` repartidas en renglones de hasta `maxWidth` px (letra de `fontSize`, ancho aproximado). */
export function wrapWords(text: string, maxWidth: number, fontSize: number): string[] {
    const perChar = fontSize * 0.56;
    const max = Math.max(1, Math.floor(maxWidth / perChar));
    const lines: string[] = [];
    let cur = '';
    for (const w of String(text).split(/\s+/).filter(Boolean)) {
        if (!cur) cur = w;
        else if ((cur + ' ' + w).length <= max) cur += ' ' + w;
        else { lines.push(cur); cur = w; }
    }
    if (cur) lines.push(cur);
    return lines.length ? lines : [String(text)];
}

type Dims = Pick<InnerDims, 'margin' | 'innerWidth' | 'innerHeight'>;

/** Dónde empieza el dibujo a lo ancho (en lugar de `dims.margin.left`). */
export const plotLeft = (dims: Dims, p: ChartAxisLayoutProps): number =>
    p.yAxisSide === 'right' ? dims.margin.right : dims.margin.left;

/** Dónde empieza el dibujo a lo alto (en lugar de `dims.margin.top`). */
export const plotTop = (dims: Dims, p: ChartAxisLayoutProps): number =>
    p.xLabels === 'top' ? dims.margin.bottom : dims.margin.top;

/** Las props de ChartAxis para el eje X. `rotate`: el giro propio del gráfico (si no se eligió otro). */
export const xAxisLayout = (dims: Dims, p: ChartAxisLayoutProps, rotate?: number) => ({
    orientation: (p.xLabels === 'top' ? 'top' : 'bottom') as 'top' | 'bottom',
    top: p.xLabels === 'top' ? 0 : dims.innerHeight,
    hideTickLabels: p.xLabels === 'none' ? true : undefined,
    tickRotate: p.xLabelRotate ?? rotate ?? 0,
    ...tickLayout(p, p.xTickCount),
    ...(p.labelWrap ? { wrapLabels: true } : {}),   // VX5
    // VX1: las rayitas del otro lado (arriba si el eje va abajo, y al revés)
    mirrorOffset: p.ticksBothSides ? (p.xLabels === 'top' ? dims.innerHeight : -dims.innerHeight) : undefined,
});

/** VX1: lo de las rayitas para ChartAxis (sin valor = lo de siempre). */
const tickLayout = (p: ChartAxisLayoutProps, count?: number) => ({
    ...(count ? { numTicks: count } : {}),
    ...(p.showTicks === false ? { hideTicks: true } : {}),
    ...(p.tickDirection ? { tickDirection: p.tickDirection } : {}),
    ...(p.tickLength != null ? { tickLength: p.tickLength } : {}),
    ...(p.tickWidth != null ? { tickWidth: p.tickWidth } : {}),
    ...(p.tickPad != null ? { tickPad: p.tickPad } : {}),
});

/** Las props de ChartAxis para el eje Y. */
export const yAxisLayout = (dims: Dims, p: ChartAxisLayoutProps) => ({
    ...(p.yAxisSide === 'right'
        ? { orientation: 'right' as const, left: dims.innerWidth }
        : { orientation: 'left' as const }),
    ...tickLayout(p, p.yTickCount),
    mirrorOffset: p.ticksBothSides ? (p.yAxisSide === 'right' ? -dims.innerWidth : dims.innerWidth) : undefined,
    // VX1: el marco del área del dibujo lo dibuja el eje Y (está en todos los gráficos con ejes)
    frame: p.plotFrame ? { width: dims.innerWidth, height: dims.innerHeight } : undefined,
});

/**
 * VX1: la escala de un eje con lo elegido en el Estilo: mínimo / máximo, logarítmica, al revés, margen y cantidad de
 * marcas. Una escala de categorías (band) solo se invierte. Sin nada elegido, la misma escala.
 */
export function adaptScale<S>(scale: S, p: ChartAxisLayoutProps, axis: 'x' | 'y'): S {
    const s = scale as unknown as {
        copy?: () => any; domain: () => unknown[]; range: () => number[]; bandwidth?: () => number;
    };
    if (!s || typeof s.copy !== 'function') return scale;
    const x = axis === 'x';
    const min = x ? p.xMin : p.yMin;
    const max = x ? p.xMax : p.yMax;
    const type = x ? p.xScaleType : p.yScaleType;
    const invert = x ? p.xInvert : p.yInvert;
    const margin = x ? p.xMargin : p.yMargin;
    const count = x ? p.xTickCount : p.yTickCount;
    if (min == null && max == null && type !== 'log' && !invert && !margin && !count) return scale;
    let out = s.copy();
    if (typeof s.bandwidth !== 'function') {
        const d = out.domain();
        if (typeof d[0] === 'number' && typeof d[d.length - 1] === 'number') {
            let lo = d[0] as number;
            let hi = d[d.length - 1] as number;
            if (margin) {
                const span = hi - lo || Math.abs(hi) || 1;
                lo -= span * margin;
                hi += span * margin;
            }
            if (min != null && Number.isFinite(min)) lo = min;
            if (max != null && Number.isFinite(max)) hi = max;
            if (type === 'log') {   // la logarítmica no tiene el 0: empieza en el menor positivo
                if (!(hi > 0)) hi = 1;
                if (!(lo > 0)) lo = Math.min(1, hi / 1000);
                out = scaleLog<number>({ domain: [lo, hi], range: out.range(), clamp: true, nice: true });
            } else {
                out.domain([lo, hi]);
            }
        }
    }
    if (invert) out.range([...out.range()].reverse());
    if (count && typeof out.ticks === 'function') {   // la grilla y el eje piden las mismas marcas
        const ticks = out.ticks.bind(out);
        out.ticks = () => ticks(count);
    }
    return out as S;
}
