/**
 * Copia del tablero como HTML autocontenido (0022 M5.5): el dibujo tal como se ve (SVG de los gráficos incluido) con
 * solo las reglas CSS que lo tocan (respetando las capas @layer) y las variables CSS heredadas de afuera.
 */

const PSEUDO_ELEMENTS = /::?(before|after|placeholder|selection|marker|backdrop|first-line|first-letter|-webkit-[\w-]+|-moz-[\w-]+)/g;
const ALWAYS = /(^|[\s,>+~(])(:root|html|body|\*)(?=$|[\s,.:#[>+~)])/;

function selectorUsed(sel: string, root: Element): boolean {
    if (ALWAYS.test(sel)) return true;
    const plain = sel.replace(PSEUDO_ELEMENTS, '').replace(/:(hover|focus|focus-visible|focus-within|active|visited)/g, '');
    if (!plain.trim()) return true;
    try {
        return root.matches(plain) || root.querySelector(plain) !== null;
    } catch {
        return true;   // selector que el navegador no entiende al probarlo: se deja
    }
}

/** Las reglas de `rules` que tocan algo de `root` (recorre @layer, @media, @supports). */
function usedRules(rules: CSSRuleList, root: Element): string[] {
    const out: string[] = [];
    for (const rule of Array.from(rules)) {
        const r = rule as CSSRule & { selectorText?: string; cssRules?: CSSRuleList; name?: string; nameList?: string[];
            conditionText?: string; media?: MediaList };
        const imp = rule as CSSRule & { styleSheet?: CSSStyleSheet | null; layerName?: string | null };
        if (imp.styleSheet !== undefined) {   // @import url(…) layer(x)
            let inner: string[] = [];
            try { inner = imp.styleSheet ? usedRules(imp.styleSheet.cssRules, root) : []; } catch { inner = []; }
            if (inner.length) {
                out.push(imp.layerName != null ? `@layer ${imp.layerName} {\n${inner.join('\n')}\n}` : inner.join('\n'));
            }
            continue;
        }
        if (r.selectorText !== undefined) {
            if (selectorUsed(r.selectorText, root)) out.push(r.cssText);
        } else if (r.cssRules && r.constructor?.name === 'CSSLayerBlockRule') {
            const inner = usedRules(r.cssRules, root);
            if (inner.length) out.push(`@layer ${r.name ?? ''} {\n${inner.join('\n')}\n}`);
        } else if (r.cssRules && r.media) {
            const inner = usedRules(r.cssRules, root);
            if (inner.length) out.push(`@media ${r.media.mediaText} {\n${inner.join('\n')}\n}`);
        } else if (r.cssRules && r.conditionText !== undefined) {
            const inner = usedRules(r.cssRules, root);
            if (inner.length) out.push(`@supports ${r.conditionText} {\n${inner.join('\n')}\n}`);
        } else {
            out.push(r.cssText);   // @layer a, b; @font-face, @keyframes, @property…
        }
    }
    return out;
}

/** Variables CSS (y letra / color) que `el` hereda de sus antepasados: van en línea en la copia. */
function inheritedVars(el: Element): string {
    if (typeof getComputedStyle === 'undefined') return '';
    const cs = getComputedStyle(el);
    const parts: string[] = [];
    for (let i = 0; i < cs.length; i++) {
        const name = cs[i];
        if (name.startsWith('--')) parts.push(`${name}: ${cs.getPropertyValue(name).trim()}`);
    }
    for (const p of ['color', 'font-family', 'font-size']) {
        const v = cs.getPropertyValue(p);
        if (v) parts.push(`${p}: ${v}`);
    }
    // line-height sin unidad: el valor calculado viene en px (24px) y los textos más chicos (celdas de una tabla,
    // 12px) lo heredarían fijo, más altos que en la pantalla (0026 X12: las filas de la tabla del PDF no coincidían)
    const lh = parseFloat(cs.getPropertyValue('line-height'));
    const fs = parseFloat(cs.getPropertyValue('font-size'));
    if (lh > 0 && fs > 0) parts.push(`line-height: ${Math.round((lh / fs) * 1000) / 1000}`);
    else if (cs.getPropertyValue('line-height')) parts.push(`line-height: ${cs.getPropertyValue('line-height')}`);
    return parts.join('; ');
}

const escapeHtml = (s: string) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]!));

export interface SnapshotOptions {
    title?: string;
    background?: string;
    /** CSS de página para imprimir (p. ej. "@page { size: A4 landscape; margin: 10mm }") */
    pageCss?: string;
}

/** Lo que solo sirve para editar y no va en la copia: controles de la tarjeta, cortes de página, flechas de
 *  ordenar de las tablas y todo lo marcado con `w3f-dashboard-noprint` (avisos de edición). */
export const SNAPSHOT_REMOVE = '.w3f-dashboard-tile-remove, .w3f-dashboard-tile-resize, .w3f-dashboard-page-break, '
    + '.w3f-dashboard-tile-head--bare, .w3f-table-sort-icon, .w3f-dashboard-noprint';

/** Documento HTML con la copia de `root`, sin los controles de edición (✕, esquina de tamaño). */
export function snapshotHtml(root: HTMLElement, opts: SnapshotOptions = {}): string {
    const clone = root.cloneNode(true) as HTMLElement;
    clone.querySelectorAll(SNAPSHOT_REMOVE).forEach((n) => n.remove());
    clone.querySelectorAll('.w3f-dashboard-tile-head').forEach((n) => (n as HTMLElement).style.removeProperty('cursor'));
    clone.querySelectorAll('.w3f-dashboard-tile--selected').forEach((n) => n.classList.remove('w3f-dashboard-tile--selected'));   // 0022 B45.1
    const vars = inheritedVars(root);
    clone.setAttribute('style', `${vars}; ${clone.getAttribute('style') ?? ''}`);
    const css: string[] = [];
    if (typeof document !== 'undefined') {
        for (const sheet of Array.from(document.styleSheets)) {
            let rules: CSSRuleList | null = null;
            try { rules = sheet.cssRules; } catch { rules = null; }   // hoja de otro origen: no se puede leer
            if (rules) css.push(...usedRules(rules, root));
        }
    }
    const bg = opts.background ?? '#0f172a';
    return [
        '<!doctype html>',
        '<html lang="es"><head><meta charset="utf-8">',
        '<meta name="viewport" content="width=device-width, initial-scale=1">',
        `<title>${escapeHtml(opts.title ?? 'Tablero')}</title>`,
        `<style>\n${css.join('\n')}\n</style>`,
        `<style>body { margin: 0; padding: 16px; background: ${bg}; }`
        + ' .w3f-dashboard-tile { break-inside: avoid; }'
        + (opts.pageCss ? `\n${opts.pageCss}` : '') + '</style>',
        '</head><body>',
        clone.outerHTML,
        '</body></html>',
    ].join('\n');
}
