import { useState, useRef, useEffect, useCallback } from 'react';
import type { WindowDimensions, WindowLayout, WindowPosition } from './Window.types';
import { WINDOW_CLASSES, WINDOW_MIN_HEIGHT, WINDOW_MIN_WIDTH } from './Window.constants';
import { relPos } from '../Desktop/Desktop.links';
import type { LinkRect } from '../Desktop/Desktop.links';
import { avoidCanvas, freeSpot, overlaps, windowRects, GAP, GREW_EVENT, SETTLE_EVENT, WINDOW_LAYOUT_ATTR }
    from '../Desktop/Desktop.overlap';

/** Espera a que la ventana recién abierta tenga su tamaño (contenido montado) antes de buscarle lugar. */
const SETTLE_DELAY = 150;

// Global z-index counter — shared across all Window instances
let windowZIndexCounter = 100;

// ── Ventanas hijas: al arrastrar una ventana se mueven con ella las que salen de ella ──
// Cada ventana con windowId se anota en el registro de su WindowGroup (o del documento si no hay grupo), con su
// windowSource (la ventana de la que salió). Arrastrar una ventana mueve a sus hijas, nietas, etc.
export interface ChildWindowEntry {
    source?: string;
    getPosition: () => WindowPosition;
    moveTo: (pos: WindowPosition, final: boolean) => void;
}
const windowRegistries = new WeakMap<Element, Map<string, ChildWindowEntry>>();

function registryFor(el: Element): Map<string, ChildWindowEntry> {
    const scope = el.parentElement?.closest('.w3f-window-group') ?? el.ownerDocument.body;
    let reg = windowRegistries.get(scope);
    if (!reg) {
        reg = new Map();
        windowRegistries.set(scope, reg);
    }
    return reg;
}

/** Todas las ventanas que salen de `windowId`, a cualquier profundidad (sin repetir, aunque haya ciclos). */
export function descendantWindows(reg: Map<string, ChildWindowEntry>, windowId: string): ChildWindowEntry[] {
    const seen = new Set([windowId]);
    const out: ChildWindowEntry[] = [];
    for (let frontier = [windowId]; frontier.length;) {
        const next: string[] = [];
        reg.forEach((entry, id) => {
            if (!seen.has(id) && entry.source && frontier.includes(entry.source)) {
                seen.add(id);
                out.push(entry);
                next.push(id);
            }
        });
        frontier = next;
    }
    return out;
}

interface ResizeStart {
    x: number;
    y: number;
    width: number;
    height: number;
    startX: number;
    startY: number;
    scale: number;
}

export interface UseWindowStateReturn {
    isOpen: boolean;
    isMinimized: boolean;
    isMaximized: boolean;
    isFocused: boolean;
    isDragging: boolean;
    isResizing: boolean;
    zIndex: number;
    position: WindowPosition;
    dimensions: WindowDimensions | null;
    windowRef: React.RefObject<HTMLDivElement>;
    handleDragStart: (e: React.MouseEvent) => void;
    handleResizeStart: (e: React.MouseEvent, direction: string) => void;
    handleClose: () => void;
    handleMinimize: () => void;
    handleMaximize: () => void;
    isFitWidth: boolean;
    handleFitWidth: () => void;
    handleWindowClick: () => void;
    /** autoHeight="content" sigue activo (el usuario no cambió el tamaño a mano). */
    autoContent: boolean;
    /** Tope del alto con autoHeight="content": el alto visible del Desktop desde la ventana hasta abajo (px). */
    maxContentHeight: number | null;
}

const AUTO_HEIGHT_MARGIN = 8;

/** Alto visible que queda desde el borde de arriba de la ventana hasta el borde de abajo del Desktop (o de la
 *  pantalla), en unidades del lienzo (sin zoom). */
export function visibleHeightBelow(el: HTMLElement | null, scale: number): number {
    if (!el || typeof window === 'undefined') return 0;
    const rect = el.getBoundingClientRect();
    const viewport = el.closest<HTMLElement>('.w3f-desktop-viewport');
    const bottom = viewport ? viewport.getBoundingClientRect().bottom : window.innerHeight;
    const s = scale || 1;
    return Math.max(WINDOW_MIN_HEIGHT, Math.floor((bottom - rect.top) / s - AUTO_HEIGHT_MARGIN));
}

/** Evento al WindowGroup: «correte dx, dy» (teclado sobre una ventana fija del grupo). */
export const GROUP_MOVE_EVENT = 'w3f-group-move';

/** Flecha → [dx, dy] (handleKeyMove). */
export const KEY_DELTAS: Record<string, [number, number]> = {
    ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1],
};

/** Ctrl + Alt + → / ←: el foco a la barra de título de la ventana siguiente / anterior del mismo escritorio (en el
 *  orden de la página) y el escritorio se corre hasta mostrarla. Devuelve si encontró una. */
export function focusSiblingWindow(from: Element, dir: 1 | -1): boolean {
    const root = from.closest('.w3f-desktop') ?? document.body;
    const bars = Array.from(root.querySelectorAll<HTMLElement>(`.${WINDOW_CLASSES.titlebar}[tabindex]`))
        .filter((b) => b.offsetParent !== null);
    if (!bars.length) return false;
    const mine = from.closest('.w3f-window')?.querySelector<HTMLElement>(`.${WINDOW_CLASSES.titlebar}`);
    const i = mine ? bars.indexOf(mine) : -1;
    const next = bars[(i + dir + bars.length) % bars.length];
    next.focus({ preventScroll: true });
    const win = next.closest('.w3f-window');
    if (win) root.dispatchEvent(new CustomEvent('w3f-desktop-focus', { detail: { el: win } }));   // = FOCUS_EVENT
    return true;
}

export function useWindowState(
    open: boolean,
    draggable: boolean,
    resizable: boolean,
    onClose?: () => void,
    onMinimize?: (minimized: boolean) => void,
    onMaximize?: (maximized: boolean) => void,
    onFocus?: () => void,
    initialPosition: WindowPosition | null = null,
    initialSize: WindowDimensions | null = null,
    scale = 1,
    onLayoutChange?: (layout: WindowLayout) => void,
    initialMaximized = false,
    initialMinimized = false,
    windowId?: string,
    windowSource?: string,
    autoHeight: 'content' | 'fill' | null = null,
): UseWindowStateReturn {
    const [isOpen, setIsOpen] = useState(open);
    // 0022 B29: el alto lo da el contenido ('content') o el alto visible ('fill'); al tocar el tamaño a mano se apaga
    const [autoMode, setAutoMode] = useState<'content' | 'fill' | null>(autoHeight ?? null);
    const [maxContentHeight, setMaxContentHeight] = useState<number | null>(null);
    const [isMinimized, setIsMinimized] = useState(initialMinimized);
    const [isMaximized, setIsMaximized] = useState(initialMaximized);
    const [isFocused, setIsFocused] = useState(false);
    const [isDragging, setIsDragging] = useState(false);
    const [isResizing, setIsResizing] = useState(false);
    const [zIndex, setZIndex] = useState(() => ++windowZIndexCounter);
    const [position, setPosition] = useState<WindowPosition>(initialPosition ?? { x: 100, y: 100 });
    const [dimensions, setDimensions] = useState<WindowDimensions | null>(initialSize ?? null);

    const windowRef = useRef<HTMLDivElement>(null);

    // Refs that always hold current state values (avoid stale closures in effects)
    const positionRef = useRef(position);
    useEffect(() => { positionRef.current = position; }, [position]);
    const dimensionsRef = useRef(dimensions);
    useEffect(() => { dimensionsRef.current = dimensions; }, [dimensions]);

    // Drag: store mouse start + canvas-space position start + scale at drag start
    const dragStartRef = useRef({ mouseX: 0, mouseY: 0, posX: 0, posY: 0, scale: 1 });
    // Ventanas que salen de esta (hijas, nietas…) y su posición al empezar el arrastre
    const dragChildrenRef = useRef<{ entry: ChildWindowEntry; x: number; y: number }[]>([]);

    // Resize: store mouse start + canvas-space size and position start
    const resizeStartRef = useRef<ResizeStart>({ x: 0, y: 0, width: 0, height: 0, startX: 0, startY: 0, scale: 1 });
    const resizeDirection = useRef<string | null>(null);
    const previousState = useRef<{ position: WindowPosition | null; dimensions: WindowDimensions | null }>({
        position: null,
        dimensions: null,
    });

    useEffect(() => { setIsOpen(open); }, [open]);

    // onLayoutChange: cuando termina un arrastre / cambio de tamaño o cambia maximizada / minimizada.
    // No se avisa al montar (la ventana está donde la pusieron) ni en cada cuadro del arrastre.
    const onLayoutChangeRef = useRef(onLayoutChange);
    useEffect(() => { onLayoutChangeRef.current = onLayoutChange; }, [onLayoutChange]);
    const layoutKey = `${isDragging || isResizing ? 'moving' : 'still'}|${isMaximized}|${isMinimized}`;
    const lastLayoutKey = useRef(layoutKey);
    const autoModeRef = useRef(autoMode);
    useEffect(() => { autoModeRef.current = autoMode; }, [autoMode]);
    const reportLayout = useCallback((pos: WindowPosition, maximized: boolean, minimized: boolean) => {
        if (!onLayoutChangeRef.current) return;
        // Tamaño: el elegido, o el de la ventana en el layout (offsetWidth no cambia con el zoom del Desktop)
        let { width, height } = dimensionsRef.current ?? { width: 0, height: 0 };
        if (!dimensionsRef.current && windowRef.current) {
            width = windowRef.current.offsetWidth;
            height = windowRef.current.offsetHeight;
        }
        if (autoModeRef.current && windowRef.current) height = windowRef.current.offsetHeight;
        onLayoutChangeRef.current({
            x: Math.round(pos.x), y: Math.round(pos.y), width: Math.round(width), height: Math.round(height),
            maximized, minimized,
        });
    }, []);
    // Registro para que la ventana de la que salió (windowSource) la arrastre con ella
    const stateFlagsRef = useRef({ isMaximized, isMinimized });
    useEffect(() => { stateFlagsRef.current = { isMaximized, isMinimized }; }, [isMaximized, isMinimized]);

    // ── Sin taparse (windowLayout="avoid" del Desktop) ──
    // Corre la ventana al lugar libre más cercano si toca a otra. `placed`: las ventanas ya acomodadas (barrido al
    // activar la opción); sin `placed`, todas las del canvas. Devuelve su rectángulo final (null si no participa).
    const draggableRef = useRef(draggable);
    const movingRef = useRef(false);   // FL18: arrastrando o cambiando el tamaño a mano (crecer así no avisa)
    draggableRef.current = draggable;
    movingRef.current = isDragging || isResizing;
    const settle = useCallback((placed?: LinkRect[]): LinkRect | null => {
        const el = windowRef.current;
        const canvas = avoidCanvas(el);
        if (!el || !canvas || !draggableRef.current || stateFlagsRef.current.isMaximized) return null;
        const me = relPos(el, canvas);
        if (!me.width || !me.height) return null;
        const { dx, dy } = freeSpot(me, placed ?? windowRects(canvas, el));
        if (dx || dy) {
            const pos = { x: positionRef.current.x + dx, y: positionRef.current.y + dy };
            positionRef.current = pos;
            setPosition(pos);
            reportLayout(pos, false, stateFlagsRef.current.isMinimized);
        }
        return { ...me, left: me.left + dx, top: me.top + dy };
    }, [reportLayout]);

    useEffect(() => {
        if (layoutKey === lastLayoutKey.current) return;
        const wasMoving = lastLayoutKey.current.startsWith('moving');
        lastLayoutKey.current = layoutKey;
        if (isDragging || isResizing) return;
        const pos = isMaximized && previousState.current.position ? previousState.current.position
            : positionRef.current;
        reportLayout(pos, isMaximized, isMinimized);
        if (wasMoving) settle();                     // se soltó encima de otra: al lugar libre más cercano
    }, [layoutKey, isDragging, isResizing, isMaximized, isMinimized, reportLayout, settle]);

    useEffect(() => {                                // al abrirse
        if (!isOpen) return;
        const id = setTimeout(() => settle(), SETTLE_DELAY);
        return () => clearTimeout(id);
    }, [isOpen, settle]);

    // ── 0022 B29: alto automático ──
    const canvasScaleOf = useCallback((): number => {
        let node: HTMLElement | null = windowRef.current?.offsetParent as HTMLElement | null;
        while (node) {
            const t = window.getComputedStyle(node).transform;
            if (t && t !== 'none') {
                const m = t.match(/matrix\((-?[\d.e]+)/);
                return m ? parseFloat(m[1]) || 1 : 1;
            }
            node = node.offsetParent as HTMLElement | null;
        }
        return 1;
    }, []);
    useEffect(() => {                                // 'fill': todo el alto visible; sigue a la posición («Sin taparse»
        const el = windowRef.current;                //  la corre al abrirse) hasta que el usuario toque el tamaño
        if (autoMode !== 'fill' || !el || !isOpen || isMaximized) return;
        const next = { width: dimensionsRef.current?.width ?? el.offsetWidth,
                       height: visibleHeightBelow(el, canvasScaleOf()) };
        dimensionsRef.current = next;
        setDimensions(next);
    }, [autoMode, isOpen, isMaximized, position, canvasScaleOf]);
    useEffect(() => {                                // 'content': el tope sigue a la posición y al tamaño de la pantalla
        const el = windowRef.current;
        if (autoMode !== 'content' || !el || !isOpen) return;
        const update = () => setMaxContentHeight(visibleHeightBelow(windowRef.current, canvasScaleOf()));
        update();
        window.addEventListener('resize', update);
        return () => window.removeEventListener('resize', update);
    }, [autoMode, isOpen, position, canvasScaleOf]);

    // FL18: la ventana crece sola (alto automático: llegaron los datos) → avisa; las que quedaron tapadas se corren
    useEffect(() => {
        const el = windowRef.current;
        if (!el || !isOpen || typeof ResizeObserver === 'undefined') return undefined;
        let last = el.offsetHeight;
        const ro = new ResizeObserver(() => {
            const h = el.offsetHeight;
            const grew = h > last + 4;
            last = h;
            const canvas = avoidCanvas(el);
            if (!grew || !canvas || stateFlagsRef.current.isMaximized || movingRef.current) return;
            canvas.dispatchEvent(new CustomEvent(GREW_EVENT, { detail: { el, rect: relPos(el, canvas) } }));
        });
        ro.observe(el);
        return () => ro.disconnect();
    }, [isOpen]);
    useEffect(() => {
        const canvas = windowRef.current?.closest(`[${WINDOW_LAYOUT_ATTR}]`);
        if (!canvas || !isOpen) return undefined;
        const onGrew = (e: Event) => {
            const { el: grown, rect } = (e as CustomEvent<{ el: Element; rect: LinkRect }>).detail;
            const el = windowRef.current;
            if (!el || el === grown || !avoidCanvas(el)) return;
            if (overlaps(relPos(el, canvas as HTMLElement), rect, GAP)) settle();
        };
        canvas.addEventListener(GREW_EVENT, onGrew);
        return () => canvas.removeEventListener(GREW_EVENT, onGrew);
    }, [isOpen, settle]);

    // FL18: maximizada dentro de un Desktop ocupa lo que se ve del escritorio (el canvas tiene zoom y desplazamiento:
    // `position: fixed` queda relativo al canvas y 100vw no coincidía con lo visible)
    useEffect(() => {
        const el = windowRef.current;
        const props = ['--w3f-window-max-top', '--w3f-window-max-left', '--w3f-window-max-width', '--w3f-window-max-height'];
        if (!el) return undefined;
        const viewport = el.closest('.w3f-desktop-viewport') as HTMLElement | null;
        const canvas = el.closest('.w3f-desktop-canvas') as HTMLElement | null;
        if (!isMaximized || !viewport || !canvas) {
            props.forEach((p) => el.style.removeProperty(p));
            return undefined;
        }
        const fit = () => {
            // la escala del canvas (zoom): maximizada es position fixed y no tiene offsetParent (canvasScaleOf da 1)
            const scale = canvas.offsetWidth ? canvas.getBoundingClientRect().width / canvas.offsetWidth : 1;
            const vr = viewport.getBoundingClientRect();
            const cr = canvas.getBoundingClientRect();
            el.style.setProperty(props[0], `${(vr.top - cr.top) / scale}px`);
            el.style.setProperty(props[1], `${(vr.left - cr.left) / scale}px`);
            el.style.setProperty(props[2], `${vr.width / scale}px`);
            el.style.setProperty(props[3], `${vr.height / scale}px`);
        };
        fit();
        window.addEventListener('resize', fit);
        return () => window.removeEventListener('resize', fit);
    }, [isMaximized]);

    useEffect(() => {                                // barrido al activar la opción (lo manda el Desktop)
        const canvas = windowRef.current?.closest(`[${WINDOW_LAYOUT_ATTR}]`);
        if (!canvas || !isOpen) return;
        const onSettle = (e: Event) => {
            const placed = (e as CustomEvent<{ placed: LinkRect[] }>).detail.placed;
            const r = settle(placed);
            if (r) placed.push(r);
        };
        canvas.addEventListener(SETTLE_EVENT, onSettle);
        return () => canvas.removeEventListener(SETTLE_EVENT, onSettle);
    }, [isOpen, settle]);
    useEffect(() => {
        const el = windowRef.current;
        if (!windowId || !el || !isOpen) return;
        const reg = registryFor(el);
        const entry: ChildWindowEntry = {
            source: windowSource,
            getPosition: () => positionRef.current,
            moveTo: (pos, final) => {
                if (stateFlagsRef.current.isMaximized) return;   // maximizada: no tiene posición propia
                positionRef.current = pos;
                setPosition(pos);
                if (final) reportLayout(pos, false, stateFlagsRef.current.isMinimized);
            },
        };
        reg.set(windowId, entry);
        return () => { if (reg.get(windowId) === entry) reg.delete(windowId); };
    }, [windowId, windowSource, isOpen, reportLayout]);

    // Drag — delta approach: newPos = posAtDragStart + (mouseDelta / scale)
    // Scale is read from the canvas CSS transform at drag-start time — always accurate.
    useEffect(() => {
        if (!isDragging) return;

        const delta = (e: MouseEvent) => {
            const { mouseX, mouseY, scale: s } = dragStartRef.current;
            return { dx: (e.clientX - mouseX) / s, dy: (e.clientY - mouseY) / s };
        };
        const moveChildren = (dx: number, dy: number, final: boolean) => {
            for (const c of dragChildrenRef.current) c.entry.moveTo({ x: c.x + dx, y: c.y + dy }, final);
        };

        const onMouseMove = (e: MouseEvent) => {
            const { posX, posY } = dragStartRef.current;
            const { dx, dy } = delta(e);
            setPosition({ x: posX + dx, y: posY + dy });
            moveChildren(dx, dy, false);
        };

        const onMouseUp = (e: MouseEvent) => {
            const { dx, dy } = delta(e);
            if (dx || dy) moveChildren(dx, dy, true);   // las hijas avisan su posición nueva (onLayoutChange)
            dragChildrenRef.current = [];
            setIsDragging(false);
        };

        window.addEventListener('mousemove', onMouseMove);
        window.addEventListener('mouseup', onMouseUp);
        return () => {
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', onMouseUp);
        };
    }, [isDragging]);

    const handleDragStart = useCallback((e: React.MouseEvent) => {
        if (!draggable || isMaximized || isMinimized) return;
        if (!windowRef.current) return;

        // Stop propagation so a parent WindowGroup doesn't also start dragging.
        e.stopPropagation();

        // Traverse offsetParent chain to find the Desktop canvas (first element with CSS transform).
        // This handles WindowGroup being inserted between Window and Desktop canvas.
        const getCanvasScale = (): number => {
            let node: HTMLElement | null = windowRef.current!.offsetParent as HTMLElement | null;
            while (node) {
                const t = window.getComputedStyle(node).transform;
                if (t && t !== 'none') {
                    const m = t.match(/matrix\((-?[\d.e]+)/);
                    return m ? parseFloat(m[1]) : 1;
                }
                node = node.offsetParent as HTMLElement | null;
            }
            return 1;
        };

        dragStartRef.current = {
            mouseX: e.clientX,
            mouseY: e.clientY,
            posX: positionRef.current.x,
            posY: positionRef.current.y,
            scale: getCanvasScale(),
        };
        dragChildrenRef.current = windowId
            ? descendantWindows(registryFor(windowRef.current), windowId).map((entry) => ({ entry, ...entry.getPosition() }))
            : [];

        setIsDragging(true);
        setIsFocused(true);
        setZIndex(++windowZIndexCounter);
        if (onFocus) onFocus();
    }, [draggable, isMaximized, isMinimized, onFocus, windowId]);

    // Resize — same delta approach
    useEffect(() => {
        if (!isResizing) return;

        const onMouseMove = (e: MouseEvent) => {
            if (!resizeDirection.current) return;
            const { x, y, width, height, startX, startY, scale: s } = resizeStartRef.current;
            const deltaX = (e.clientX - x) / s;
            const deltaY = (e.clientY - y) / s;
            const dir = resizeDirection.current;

            let newWidth = width;
            let newHeight = height;
            let newX = startX;
            let newY = startY;

            if (dir.includes('e')) newWidth += deltaX;
            if (dir.includes('w')) { newWidth -= deltaX; newX += deltaX; }
            if (dir.includes('s')) newHeight += deltaY;
            if (dir.includes('n')) { newHeight -= deltaY; newY += deltaY; }

            if (newWidth < WINDOW_MIN_WIDTH) {
                if (dir.includes('w')) newX = startX + width - WINDOW_MIN_WIDTH;
                newWidth = WINDOW_MIN_WIDTH;
            }
            if (newHeight < WINDOW_MIN_HEIGHT) {
                if (dir.includes('n')) newY = startY + height - WINDOW_MIN_HEIGHT;
                newHeight = WINDOW_MIN_HEIGHT;
            }

            setDimensions({ width: newWidth, height: newHeight });
            if (dir.includes('w') || dir.includes('n')) setPosition({ x: newX, y: newY });
        };

        const onMouseUp = () => {
            setIsResizing(false);
            resizeDirection.current = null;
        };

        window.addEventListener('mousemove', onMouseMove);
        window.addEventListener('mouseup', onMouseUp);
        return () => {
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', onMouseUp);
        };
    }, [isResizing]);

    const handleResizeStart = useCallback((e: React.MouseEvent, direction: string) => {
        if (!resizable || isMaximized) return;
        e.stopPropagation();
        resizeDirection.current = direction;
        fitPrevRef.current = null;
        setIsFitWidth(false);

        const el = windowRef.current!;
        // Traverse offsetParent chain — handles WindowGroup between Window and Desktop canvas
        let _node: HTMLElement | null = el.offsetParent as HTMLElement | null;
        let s = 1;
        while (_node) {
            const _t = window.getComputedStyle(_node).transform;
            if (_t && _t !== 'none') {
                const _m = _t.match(/matrix\((-?[\d.e]+)/);
                s = _m ? parseFloat(_m[1]) : 1;
                break;
            }
            _node = _node.offsetParent as HTMLElement | null;
        }

        const cur = dimensionsRef.current;
        const rect = el.getBoundingClientRect();
        let start = cur ? { width: cur.width, height: cur.height } : { width: rect.width / s, height: rect.height / s };
        if (autoModeRef.current) {                   // B29: desde acá manda el tamaño que elija el usuario
            start = { width: cur ? cur.width : rect.width / s, height: rect.height / s };
            dimensionsRef.current = start;
            setDimensions(start);
            autoModeRef.current = null;
            setAutoMode(null);
        }

        resizeStartRef.current = {
            x: e.clientX, y: e.clientY,
            width:  start.width,
            height: start.height,
            startX: positionRef.current.x,
            startY: positionRef.current.y,
            scale:  s,
        };
        setIsResizing(true);
    }, [resizable, isMaximized]);

    // Controls
    // El 2.º clic de un doble clic no cierra: la ventana de adelante ya se fue con el 1.º y ese clic caería en el ✕
    // de la que estaba debajo (B16 de w3f-data-analysis: se cerraban dos ventanas).
    const handleClose = useCallback((e?: { detail?: number }) => {
        if (e && typeof e.detail === 'number' && e.detail > 1) return;
        setIsOpen(false);
        if (onClose) onClose();
    }, [onClose]);

    const handleMinimize = useCallback(() => {
        setIsMinimized((prev) => {
            if (onMinimize) onMinimize(!prev);
            return !prev;
        });
    }, [onMinimize]);

    const handleMaximize = useCallback(() => {
        if (!isMaximized) {
            previousState.current = {
                position: { ...position },
                dimensions: dimensions ? { ...dimensions } : null,
            };
        } else {
            if (previousState.current.position) setPosition(previousState.current.position);
            if (previousState.current.dimensions) setDimensions(previousState.current.dimensions);
        }
        setIsMaximized((prev) => {
            if (onMaximize) onMaximize(!prev);
            return !prev;
        });
    }, [isMaximized, position, dimensions, onMaximize]);

    // ↔ Ancho del contenido: suma a la ventana lo que desborda a lo ancho el elemento que más desborda del cuerpo
    // (la tabla); otro clic vuelve al ancho de antes. offsetWidth / scrollWidth no cambian con el zoom del Desktop.
    const [isFitWidth, setIsFitWidth] = useState(false);
    const fitPrevRef = useRef<WindowDimensions | null>(null);
    const handleFitWidth = useCallback(() => {
        const el = windowRef.current;
        if (!el || isMaximized) return;
        const cur = dimensionsRef.current ?? { width: el.offsetWidth, height: el.offsetHeight };
        let next: WindowDimensions;
        if (fitPrevRef.current) {
            next = fitPrevRef.current;
            fitPrevRef.current = null;
            setIsFitWidth(false);
        } else {
            let extra = 0;
            const body = el.querySelector<HTMLElement>(`.${WINDOW_CLASSES.body}`);
            if (body) {
                for (const node of [body, ...Array.from(body.querySelectorAll<HTMLElement>('*'))]) {
                    const over = node.scrollWidth - node.clientWidth;
                    if (over > extra && node.clientWidth > 0) {
                        const ox = window.getComputedStyle(node).overflowX;
                        if (ox === 'auto' || ox === 'scroll') extra = over;
                    }
                }
            }
            if (extra <= 0) return;
            fitPrevRef.current = { ...cur };
            setIsFitWidth(true);
            next = { width: cur.width + extra + 2, height: cur.height };
        }
        dimensionsRef.current = next;
        setDimensions(next);
        reportLayout(positionRef.current, false, isMinimized);
    }, [isMaximized, isMinimized, reportLayout]);

    // Teclado (accesibilidad, w3f-data-analysis PB13): con la barra de título enfocada, flechas = mover 10 px (Alt: de a
    // 1), Mayús + flechas = cambiar el tamaño. Mueve también las ventanas hijas y avisa el lugar nuevo, como el arrastre.
    const handleKeyMove = useCallback((e: React.KeyboardEvent) => {
        const d = KEY_DELTAS[e.key];
        if (!d || e.ctrlKey || e.metaKey || e.target !== e.currentTarget || isMaximized || isMinimized) return;
        const step = e.altKey ? 1 : 10;
        if (e.shiftKey) {
            if (!resizable || !windowRef.current) return;
            const cur = dimensionsRef.current
                ?? { width: windowRef.current.offsetWidth, height: windowRef.current.offsetHeight };
            const next = { width: Math.max(WINDOW_MIN_WIDTH, cur.width + d[0] * step),
                           height: Math.max(WINDOW_MIN_HEIGHT, cur.height + d[1] * step) };
            dimensionsRef.current = next;
            setDimensions(next);
        } else {
            const dx = d[0] * step, dy = d[1] * step;
            if (!draggable) {   // fija dentro de un WindowGroup: se mueve el grupo entero (como al arrastrar su barra)
                const group = windowRef.current?.closest('.w3f-window-group');
                if (!group) return;
                group.dispatchEvent(new CustomEvent(GROUP_MOVE_EVENT, { detail: { dx, dy } }));
                e.preventDefault();
                e.stopPropagation();
                return;
            }
            const pos = { x: positionRef.current.x + dx, y: positionRef.current.y + dy };
            positionRef.current = pos;
            setPosition(pos);
            if (windowId && windowRef.current) {
                for (const c of descendantWindows(registryFor(windowRef.current), windowId)) {
                    const p = c.getPosition();
                    c.moveTo({ x: p.x + dx, y: p.y + dy }, true);
                }
            }
        }
        reportLayout(positionRef.current, false, false);
        e.preventDefault();
        e.stopPropagation();
    }, [draggable, resizable, isMaximized, isMinimized, windowId, reportLayout]);

    const handleWindowClick = useCallback(() => {
        setIsFocused(true);
        setZIndex(++windowZIndexCounter);
        if (onFocus) onFocus();
    }, [onFocus]);

    return {
        isOpen, isMinimized, isMaximized, isFocused, isDragging, isResizing,
        zIndex, position, dimensions, windowRef,
        handleDragStart, handleResizeStart,
        handleClose, handleMinimize, handleMaximize, handleWindowClick, handleKeyMove,
        isFitWidth, handleFitWidth,
        autoContent: autoMode === 'content', maxContentHeight,
    };
}
