'use client'

import React, { useMemo } from 'react';
import { Group } from '@visx/group';
import { LinePath } from '@visx/shape';
import { curveMonotoneX, curveLinear } from '@visx/curve';
import type { LineMultiInnerProps } from './LineMulti.types';
import { LINE_MULTI_DEFAULTS } from './LineMulti.constants';
import { buildLineMultiClasses, toDate, formatTick } from './LineMulti.utils';
import { useLineMultiScales, useLineMultiColors, useLineMultiHover, useInnerDims } from './LineMulti.hooks';
import { adaptScale, plotLeft, plotTop, xAxisLayout, yAxisLayout } from '../_base/axisLayout';   // 0026 X7
import { ChartAxis } from '../primitives/ChartAxis';
import { ChartPointShape } from '../primitives/ChartPointShape';   // 0026 X8
import { ChartPointLabels, dateTickFormat, formatLabel, labelIndices, lineDash } from '../primitives/ChartLineMarks';   // 0022 B53.1
import { ChartGrid } from '../primitives/ChartGrid';
import { nearestIndex } from '../_base/seriesClick';
import { ChartReferenceLines, overlayPoints } from '../primitives/ChartReferenceLines';
import { scaleLinear } from '@visx/scale';   // VX9
import { ChartSecondaryAxes } from '../primitives/ChartSecondaryAxes';   // VX9
import { ChartLegend } from '../primitives/ChartLegend';
import { BASE_CHART_CLASSES } from '../_base/constants';
import { ChartHeader } from '../_base/ChartHeader';
import { pickCurve } from '../primitives/ChartLineMarks';   // VX4

export const LineMultiInner: React.FC<LineMultiInnerProps> = (props) => {
    const {
        data, width, height, margin, className,
        unstyled = LINE_MULTI_DEFAULTS.unstyled, bindId, ariaLabel, description, colorScheme, title, subtitle,
        curved = LINE_MULTI_DEFAULTS.curved, showDots = LINE_MULTI_DEFAULTS.showDots,
        strokeWidth = LINE_MULTI_DEFAULTS.strokeWidth,
        showXAxis = LINE_MULTI_DEFAULTS.showXAxis, showYAxis = LINE_MULTI_DEFAULTS.showYAxis,
        showGrid = LINE_MULTI_DEFAULTS.showGrid, showLegend = LINE_MULTI_DEFAULTS.showLegend,
        highlightSeriesId = null,
        formatY, onHover,
        lineStyle, dotRadius = 3, valueLabels = 'none', valueLabelSize = 11, xDateFormat,   // 0022 B53.1
    } = props;

    const dims = useInnerDims(width, height, margin, props);
    const seriesIds = useMemo(() => data.map((s) => s.id), [data]);
    // VX9 (twinx): la serie elegida va con su propia escala, a la derecha; las demás, con la de la izquierda
    const twin = data.length > 1 ? data.find((s) => s.id === props.twinSeries) : undefined;
    const mainData = useMemo(() => (twin ? data.filter((s) => s.id !== twin.id) : data), [data, twin]);
    const { xScale: xScaleRaw, yScale: yScaleRaw } = useLineMultiScales(mainData, dims.innerWidth, dims.innerHeight);
    const xScale = adaptScale(xScaleRaw, props, 'x');   // VX1: mínimo / máximo, log, al revés…
    const yScale = adaptScale(yScaleRaw, props, 'y');   // VX1: mínimo / máximo, log, al revés…
    const colorMap = useLineMultiColors(seriesIds, colorScheme);
    const yScale2 = useMemo(() => {
        if (!twin) return null;
        const vs = twin.data.map((d) => d.value).filter(Number.isFinite);
        return scaleLinear<number>({ domain: [Math.min(0, ...vs), Math.max(1e-9, ...vs)], range: [dims.innerHeight, 0], nice: true });
    }, [twin, dims.innerHeight]);
    const { hovered, enter, leave } = useLineMultiHover(onHover);
    const classes = useMemo(() => buildLineMultiClasses(className, unstyled), [className, unstyled]);
    const yTickFormat = formatY ?? formatTick;
    const curve = pickCurve(curved, props.lineStep, curveMonotoneX);   // VX4: escalonada

    const legendItems = useMemo(
        () => data.map((s) => ({ id: s.id, label: s.label ?? s.id, color: colorMap[s.id] })),
        [data, colorMap],
    );

    if (data.length === 0) {
        return (<div className={classes}><svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Empty multi-line chart'} /></div>);
    }

    return (
        <div className={classes} data-bind-id={bindId}>
            <ChartHeader title={title} subtitle={subtitle} />
            {showLegend && <ChartLegend items={legendItems} />}
            <div className={BASE_CHART_CLASSES.container} style={{ position: 'relative' }}>
                <svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Multi-line chart'}>
                    {description && <desc>{description}</desc>}
                    <Group top={plotTop(dims, props)} left={plotLeft(dims, props)}>
                        {showGrid && <ChartGrid yScale={yScale} width={dims.innerWidth} height={dims.innerHeight} axis="rows" />}

                        {data.map((series) => {
                            const active = highlightSeriesId ?? hovered;
                            const isDimmed = active != null && active !== series.id;
                            const ys = twin && yScale2 && series.id === twin.id ? yScale2 : yScale;
                            return (
                                <g key={series.id}
                                    onMouseEnter={() => enter(series.id)}
                                    onMouseLeave={leave}
                                    onClick={props.onSelect ? (e) => {
                                        const dates = series.data.map((d) => d.date);
                                        const i = nearestIndex(e, plotLeft(dims, props), xScale, dates);
                                        if (i >= 0) props.onSelect!({ seriesId: series.id, date: dates[i] }, i);
                                    } : undefined}
                                    style={{ cursor: 'pointer' }}
                                >
                                    <LinePath
                                        data={[...series.data]}
                                        x={(d) => xScale(toDate(d.date)) ?? 0}
                                        y={(d) => ys(d.value) ?? 0}
                                        stroke={colorMap[series.id]}
                                        strokeWidth={hovered === series.id ? strokeWidth + 1 : strokeWidth}
                                        strokeOpacity={isDimmed ? 0.2 : 1}
                                        {...lineDash(lineStyle, strokeWidth)}
                                        curve={curve}
                                    />
                                    {/* Wider invisible hit area */}
                                    <LinePath
                                        data={[...series.data]}
                                        x={(d) => xScale(toDate(d.date)) ?? 0}
                                        y={(d) => ys(d.value) ?? 0}
                                        stroke="transparent"
                                        strokeWidth={12}
                                        curve={curve}
                                    />
                                    {showDots && series.data.map((pt, pi) => (
                                        <ChartPointShape
                                            key={pi}
                                            shape={props.pointShape ?? 'circle'}
                                            cx={xScale(toDate(pt.date)) ?? 0}
                                            cy={ys(pt.value) ?? 0}
                                            r={dotRadius} fill={colorMap[series.id]}
                                            opacity={isDimmed ? 0.2 : 1}
                                        />
                                    ))}
                                    <ChartPointLabels size={valueLabelSize} labels={labelIndices(valueLabels,
                                        series.data.map((p) => p.value)).map((i) => ({
                                        x: xScale(toDate(series.data[i].date)) ?? 0, y: ys(series.data[i].value) ?? 0,
                                        text: formatLabel(series.data[i].value, formatY), color: colorMap[series.id] }))} />
                                </g>
                            );
                        })}

                        {showXAxis && <ChartAxis scale={xScale} {...xAxisLayout(dims, props)} tickFormat={dateTickFormat(xDateFormat)} />}
                        {showYAxis && <ChartAxis scale={yScale} {...yAxisLayout(dims, props)} tickFormat={yTickFormat} />}
                        {twin && yScale2 && <ChartAxis scale={yScale2} orientation="right" left={dims.innerWidth}
                            tickFormat={yTickFormat} label={twin.label ?? twin.id} className="w3f-chart-axis--twin" />}
                        <ChartSecondaryAxes {...props} xScale={xScale} yScale={yScale} width={dims.innerWidth} height={dims.innerHeight} />
                        <ChartReferenceLines lines={props.referenceLines} bands={props.referenceBands} annotation={props.annotation}
                            points={overlayPoints(data)} xScale={xScale}
                            yScale={(v: number) => yScale(v)} width={dims.innerWidth} height={dims.innerHeight} />
                    </Group>
                </svg>
            </div>
        </div>
    );
};

LineMultiInner.displayName = 'LineMultiInner';
export default LineMultiInner;
