'use client'

import React from 'react';
import type { StackProps } from './Stack.types';
import { STACK_DEFAULTS } from './Stack.constants';
import { buildStackClasses, buildStackStyles } from './Stack.utils';

export type { StackProps, StackSize, StackAlign, StackJustify } from './Stack.types';

/**
 * Stack — Contenedor flex para separar elementos vertical u horizontalmente.
 *
 * @example
 * // Horizontal con gap libre y alineación
 * <Stack horizontal gap="1rem" justify="end" align="center">
 *   <Button>Cancelar</Button>
 *   <Button color="primary">Guardar</Button>
 * </Stack>
 *
 * @example
 * // Vertical compacto
 * <Stack size="sm">
 *   <Input name="email" />
 *   <Input name="password" />
 * </Stack>
 */
const Stack: React.FC<StackProps> = ({
    as: Tag = 'div',
    children,
    horizontal = STACK_DEFAULTS.horizontal,
    direction,
    size       = STACK_DEFAULTS.size,
    spacing,
    gap,
    align,
    alignItems,
    justify,
    justifyContent,
    className,
    style,
    flex,
    overflow,
    overflowY,
    overflowX,
    padding,
    paddingTop,
    paddingBottom,
    paddingLeft,
    paddingRight,
    minWidth,
    maxWidth,
    width,
    height,
    minHeight,
    maxHeight,
    background,
    border,
    borderRight,
    borderLeft,
    borderTop,
    borderBottom,
    borderRadius,
    userSelect,
    whiteSpace,
    cursor,
    ...rest
}) => {
    // direction='row' is equivalent to horizontal=true
    const isHorizontal = horizontal || direction === 'row';
    const resolvedAlign   = align   ?? alignItems;
    const resolvedJustify = justify ?? justifyContent;

    const classes     = buildStackClasses(isHorizontal, size, spacing, gap, className);
    const inlineStyle = buildStackStyles(gap, resolvedAlign, resolvedJustify, {
        ...(flex          !== undefined && { flex }),
        ...(overflow      !== undefined && { overflow }),
        ...(overflowY     !== undefined && { overflowY }),
        ...(overflowX     !== undefined && { overflowX }),
        ...(padding       !== undefined && { padding }),
        ...(paddingTop    !== undefined && { paddingTop }),
        ...(paddingBottom !== undefined && { paddingBottom }),
        ...(paddingLeft   !== undefined && { paddingLeft }),
        ...(paddingRight  !== undefined && { paddingRight }),
        ...(minWidth      !== undefined && { minWidth }),
        ...(maxWidth      !== undefined && { maxWidth }),
        ...(width         !== undefined && { width }),
        ...(height        !== undefined && { height }),
        ...(minHeight     !== undefined && { minHeight }),
        ...(maxHeight     !== undefined && { maxHeight }),
        ...(background    !== undefined && { background }),
        ...(border        !== undefined && { border }),
        ...(borderRight   !== undefined && { borderRight }),
        ...(borderLeft    !== undefined && { borderLeft }),
        ...(borderTop     !== undefined && { borderTop }),
        ...(borderBottom  !== undefined && { borderBottom }),
        ...(borderRadius  !== undefined && { borderRadius }),
        ...(userSelect    !== undefined && { userSelect: userSelect as React.CSSProperties['userSelect'] }),
        ...(whiteSpace    !== undefined && { whiteSpace: whiteSpace as React.CSSProperties['whiteSpace'] }),
        ...(cursor        !== undefined && { cursor }),
        ...style,
    });

    return (
        <Tag className={classes} style={inlineStyle} {...rest}>
            {children}
        </Tag>
    );
};

Stack.displayName = 'Stack';

export { Stack };
export default Stack;
