'use client'

import React, { useMemo, useRef, useEffect, useLayoutEffect, useState } from 'react';
import { ArrowUp, ArrowDown, ArrowUpDown, Search } from 'lucide-react';
import Pagination from '../../NAVIGATION/Pagination/Pagination';
import type { TableProps, TableColumn, SortState } from './Table.types';
import { ROW_PREFIX_KEY, ROW_STYLE_KEY } from './Table.types';
import { PAGE_SIZE_OPTIONS, TABLE_DEFAULTS } from './Table.constants';
import { buildContainerClasses, buildTableClasses, formatNumber, headerGroupRows, mergeSpans } from './Table.utils';
import {
    useTableSort,
    useTableFilter,
    useTablePagination,
    useColumnResize,
    useColumnReorder,
    useManualQuery,
    useRowReorder,
} from './Table.hooks';

/** Contenido de una celda sin `cell`: React no dibuja `true` / `false`, así que van como texto. */
const cellContent = (value: unknown): React.ReactNode =>
    typeof value === 'boolean' ? String(value) : (value as React.ReactNode);

/** Estilo y prefijo de una celda que vienen en la fila (`__style` / `__prefix`, formato condicional). */
const cellExtra = (row: Record<string, unknown>, key: string) => {
    const styles = row[ROW_STYLE_KEY] as Record<string, React.CSSProperties> | undefined;
    const prefixes = row[ROW_PREFIX_KEY] as Record<string, string> | undefined;
    return { style: styles?.[key], prefix: prefixes?.[key] };
};

/** Alineación de una celda de datos: la de la columna; si no, la de la tabla (variables CSS); los números
 *  (`format`) a la derecha salvo --w3f-table-num-text-align. El estilo de la fila (`__style`) manda al final. */
const cellAlignStyle = <T,>(col: TableColumn<T>, extra?: React.CSSProperties): React.CSSProperties | undefined => {
    const base: React.CSSProperties = col.format
        ? { textAlign: 'var(--w3f-table-num-text-align, right)' as React.CSSProperties['textAlign'], fontVariantNumeric: 'tabular-nums' }
        : {};
    if (col.align) base.textAlign = col.align;
    if (col.verticalAlign) base.verticalAlign = col.verticalAlign;
    if (col.lineLeft) base.borderLeft = col.lineLeft;   // 0022 B50
    if (col.lineRight) base.borderRight = col.lineRight;
    return Object.keys(base).length || extra ? { ...base, ...extra } : undefined;
};

/** Alineación del encabezado de una columna (y su ancho, si tiene). */
const headerAlignStyle = <T,>(col: TableColumn<T>, width?: React.CSSProperties): React.CSSProperties | undefined => {
    if (!col.headerAlign && !col.headerVerticalAlign && !col.lineLeft && !col.lineRight) return width;
    return { ...width, ...(col.headerAlign ? { textAlign: col.headerAlign } : {}),
             ...(col.headerVerticalAlign ? { verticalAlign: col.headerVerticalAlign } : {}),
             ...(col.lineLeft ? { borderLeft: col.lineLeft } : {}), ...(col.lineRight ? { borderRight: col.lineRight } : {}) };
};

/** Contenido de una celda sin `cell`: con formato numérico si la columna lo pide. */
const renderValue = <T,>(col: TableColumn<T>, value: unknown): React.ReactNode =>
    formatNumber(value, col.format, col.decimals, col.locale) ?? cellContent(value);

/**
 * Componente Table - Tabla de datos avanzada.
 * Soporta sorting, filtering, paginación, resize y reordenamiento de columnas.
 */
const Table = React.forwardRef(<T extends Record<string, unknown>>(
    {
        data = [] as T[],
        columns = [] as TableColumn<T>[],
        enableSorting = TABLE_DEFAULTS.enableSorting,
        enableFiltering = TABLE_DEFAULTS.enableFiltering,
        enablePagination = TABLE_DEFAULTS.enablePagination,
        enableColumnResize = TABLE_DEFAULTS.enableColumnResize,
        columnWidths: initialWidths,
        onColumnWidthsChange,
        hideHeader = false,
        enableColumnReorder = TABLE_DEFAULTS.enableColumnReorder,
        maxHeight,
        fitRows = false,
        fitMoreLabel = '… y {n} filas más (no entran en la tarjeta)',
        fitWidth = false,
        style,
        pageSize: initialPageSize = TABLE_DEFAULTS.pageSize,
        variant = TABLE_DEFAULTS.variant,
        size = TABLE_DEFAULTS.size,
        color = TABLE_DEFAULTS.color,
        className = TABLE_DEFAULTS.className,
        paginationProps = {},
        unstyled = TABLE_DEFAULTS.unstyled,
        onRowClick,
        onCellDoubleClick,
        selectedRowKey,
        selectedRowValue,
        manual = TABLE_DEFAULTS.manual,
        rowCount,
        onQueryChange,
        onColumnOrderChange,
        enableRowReorder = TABLE_DEFAULTS.enableRowReorder,
        onRowReorder,
        mergeMode = 'span',
        groupHeaders = true,
        ariaLabel,
        ...rest
    }: TableProps<T>,
    ref: React.Ref<HTMLDivElement>
) => {
    const headerRowRef = useRef<HTMLTableRowElement>(null);
    const theadRef = useRef<HTMLTableSectionElement>(null);
    const tbodyRef = useRef<HTMLTableSectionElement>(null);

    // Hooks
    const { sortState, handleSort } = useTableSort();
    const { globalFilter, handleFilterChange, filteredData } = useTableFilter(data, columns);
    const { columnWidths, initWidths, handleResizeMouseDown, widthsInitializedRef } = useColumnResize(initialWidths, onColumnWidthsChange, fitWidth);
    const { orderedColumns, handleDragMouseDown } = useColumnReorder(columns, onColumnOrderChange);

    // 0022 C-M: arrastrar filas; las filas se resuelven al soltar, con la página que se ve en ese momento
    const pageRef = useRef<T[]>([]);
    const { handleRowDragMouseDown } = useRowReorder((fromIndex, toIndex, position) => {
        const page = pageRef.current;
        if (!onRowReorder || !page[fromIndex] || !page[toIndex]) return;
        onRowReorder({ fromIndex, toIndex, position, row: page[fromIndex], targetRow: page[toIndex] });
    });

    // Sorted data (modo manual: `data` ya viene filtrada, ordenada y paginada del servidor)
    const sortedData = useMemo(() => {
        if (manual) return data;
        if (!sortState.key || !sortState.direction) return filteredData;
        return [...filteredData].sort((a, b) => {
            const aVal = a[sortState.key!];
            const bVal = b[sortState.key!];
            if (aVal == null && bVal == null) return 0;
            if (aVal == null) return 1;
            if (bVal == null) return -1;

            let comparison: number;
            if (typeof aVal === 'number' && typeof bVal === 'number') {
                comparison = aVal - bVal;
            } else {
                comparison = String(aVal).localeCompare(String(bVal), undefined, { numeric: true, sensitivity: 'base' });
            }
            return sortState.direction === 'desc' ? -comparison : comparison;
        });
    }, [manual, data, filteredData, sortState]);

    // Pagination
    const totalRows = manual ? (rowCount ?? data.length) : sortedData.length;
    const {
        currentPage, setCurrentPage, pageSize,
        totalPages, handlePageSizeChange, resetPage
    } = useTablePagination(totalRows, initialPageSize);

    // Reset page on sort/filter (modo manual: lo hace useManualQuery, después del retardo de la búsqueda)
    useEffect(() => { if (!manual) resetPage(); }, [manual, sortState, globalFilter, resetPage]);

    useManualQuery(manual, currentPage, pageSize, sortState, globalFilter, setCurrentPage, onQueryChange);

    const paginatedData = useMemo(() => {
        if (!enablePagination || manual) return sortedData;
        const start = (currentPage - 1) * pageSize;
        return sortedData.slice(start, start + pageSize);
    }, [sortedData, currentPage, pageSize, enablePagination, manual]);

    // Init column widths
    useEffect(() => {
        if (enableColumnResize && !widthsInitializedRef.current) {
            initWidths(headerRowRef.current);
        }
    }, [enableColumnResize, columns, initWidths, widthsInitializedRef]);

    // Columns to render
    const displayColumns = enableColumnReorder ? orderedColumns : columns;
    pageRef.current = paginatedData;   // 0022 C-M

    // 0026 X12 (tablas para papel): con fitRows la tabla muestra solo las filas que entran en el alto que tiene.
    // Se mide la cabecera y la primera fila (todas miden lo mismo) y se recorta; si cambia el tamaño se vuelve a
    // medir. Sin alto (jsdom, un contenedor que crece con el contenido) no se recorta nada.
    const wrapperRef = useRef<HTMLDivElement>(null);
    const [fitCount, setFitCount] = useState<number | null>(null);
    const [fitTick, setFitTick] = useState(0);
    useEffect(() => {
        if (!fitRows || !wrapperRef.current || typeof ResizeObserver === 'undefined') return undefined;
        // también la tabla: si cambia el alto de las filas (la letra o el CSS que terminan de cargar) se vuelve a medir
        const ro = new ResizeObserver(() => setFitTick((k) => k + 1));
        ro.observe(wrapperRef.current);
        const table = wrapperRef.current.querySelector('table');
        if (table) ro.observe(table);
        return () => ro.disconnect();
    }, [fitRows]);
    useLayoutEffect(() => {
        if (!fitRows) return;
        const wrap = wrapperRef.current;
        const first = tbodyRef.current?.querySelector('tr[data-row-index]') as HTMLElement | null;
        // todo con getBoundingClientRect: con CSS zoom (el tablero), clientHeight viene sin zoom y las filas con zoom
        const avail = wrap ? wrap.getBoundingClientRect().height : 0;
        const rowH = first ? first.getBoundingClientRect().height : 0;
        // toda la cabecera (con las filas de grupos de X14), no solo la de encabezados
        const headH = theadRef.current ? theadRef.current.getBoundingClientRect().height : 0;
        if (avail <= 0 || rowH <= 0) return;
        let n = Math.max(1, Math.floor((avail - headH) / rowH));
        // FL16: si no entran todas, una fila menos para el aviso «… y N filas más» (antes se cortaba sin decir nada)
        if (n < paginatedData.length) n = Math.max(1, n - 1);
        if (n !== fitCount) setFitCount(n);
    }, [fitRows, paginatedData, fitCount, fitTick]);
    const visibleData = fitRows && fitCount != null ? paginatedData.slice(0, fitCount) : paginatedData;
    const fitHidden = fitRows ? paginatedData.length - visibleData.length : 0;
    // 0026 X14: filas de grupos arriba de los encabezados y valores repetidos combinados (en las filas que se ven)
    const groupRows = useMemo(() => (groupHeaders ? headerGroupRows(displayColumns) : []), [groupHeaders, displayColumns]);
    const mergeKeys = useMemo(() => (mergeMode === 'none' ? []
        : displayColumns.filter((c) => c.merge).map((c) => c.accessorKey)), [mergeMode, displayColumns]);
    const spans = useMemo(() => (mergeKeys.length ? mergeSpans(visibleData, mergeKeys) : null),
        [visibleData, mergeKeys]);
    const spanMode = enableRowReorder || mergeMode === 'blank' ? 'blank' : 'span';
    // 0022 B44: el ancho de una columna. Con fitWidth los anchos son proporciones: la tabla ocupa siempre el 100 % de su
    // caja (en una tarjeta del tablero, agrandar una columna ya no empuja la última afuera, donde quedaba cortada)
    const widthOf = (key: string): number | undefined =>
        enableColumnResize ? columnWidths[key] : initialWidths?.[key];
    const widthSum = fitWidth ? displayColumns.reduce((s, c) => s + (widthOf(c.accessorKey) || 0), 0) : 0;
    const colWidth = (key: string): React.CSSProperties | undefined => {
        const w = widthOf(key);
        if (!w) return undefined;
        return { width: fitWidth && widthSum > 0 ? `${(w / widthSum) * 100}%` : `${w}px` };
    };
    const containerStyle = fitRows
        ? { height: '100%', display: 'flex', flexDirection: 'column' as const, minHeight: 0, overflow: 'hidden', ...style }
        : style;

    // Classes
    const containerClasses = buildContainerClasses(className, unstyled);
    const tableClassList = buildTableClasses(size, variant, color, enableColumnResize, unstyled);
    // con anchos dados el reparto es fijo; ahí el encabezado se parte en renglones (w3f-data-analysis 0027 M5: con
    // nowrap los encabezados de una tabla angosta se encimaban unos con otros)
    const fixedLayout = Boolean(enableColumnResize ? Object.keys(columnWidths).length
        : initialWidths && Object.keys(initialWidths).length);

    const renderSortIcon = (columnKey: string) => {
        if (sortState.key === columnKey) {
            if (sortState.direction === 'asc') return <ArrowUp size={14} />;
            if (sortState.direction === 'desc') return <ArrowDown size={14} />;
        }
        return <ArrowUpDown size={14} />;
    };

    return (
        <div ref={ref} className={containerClasses} style={containerStyle} {...rest}>
            {enableFiltering && (
                <div className="w3f-table-toolbar">
                    <div className="w3f-table-filter">
                        <span className="w3f-table-filter-icon">
                            <Search size={16} />
                        </span>
                        <input
                            type="text"
                            className="w3f-table-filter-input"
                            placeholder="Buscar..."
                            value={globalFilter}
                            onChange={handleFilterChange}
                            aria-label="Filtrar tabla"
                        />
                    </div>
                </div>
            )}

            <div
                ref={wrapperRef}
                className={['w3f-table-wrapper', maxHeight ? 'w3f-table-wrapper-scrollable' : ''].filter(Boolean).join(' ')}
                style={maxHeight ? { maxHeight: typeof maxHeight === 'number' ? `${maxHeight}px` : maxHeight }
                    : fitRows ? { overflow: 'hidden' } : undefined}
            >
                {/* 0026 X17: con anchos dados, reparto fijo (dos tablas con los mismos anchos quedan alineadas) */}
                <table className={[tableClassList, fixedLayout ? 'w3f-table--fixed' : '', fitWidth ? 'w3f-table--fit' : '']
                    .filter(Boolean).join(' ')} aria-label={ariaLabel || undefined}
                    style={fixedLayout ? { tableLayout: 'fixed', ...(fitWidth ? { width: '100%' } : {}) } : undefined}>
                    {(enableColumnResize || initialWidths) && (   /* 0026 X17: los anchos también por colgroup (valen con la cabecera colapsada) */
                        <colgroup>
                            {displayColumns.map((col) => (
                                <col key={col.accessorKey} style={colWidth(col.accessorKey)} />
                            ))}
                        </colgroup>
                    )}
                    <thead ref={theadRef} style={hideHeader ? { visibility: 'collapse' } : undefined}>
                        {groupRows.map((cells, level) => (
                            <tr key={`g${level}`} className="w3f-table-group-row" data-group-level={level}>
                                {cells.map((g) => (
                                    <th key={g.key} colSpan={g.span}
                                        className={g.label == null ? 'w3f-table-group-empty' : 'w3f-table-group-header'}>
                                        {g.label}
                                    </th>
                                ))}
                            </tr>
                        ))}
                        <tr ref={headerRowRef}>
                            {displayColumns.map((col) => {
                                const isSortable = enableSorting && col.sortable !== false && !col.cell;
                                const isSorted = sortState.key === col.accessorKey;
                                // 0026 X17: sin resize, los anchos del prop igual se aplican (una tabla de totales alineada)
                                const widthStyle = colWidth(col.accessorKey);

                                return (
                                    <th
                                        key={col.accessorKey}
                                        data-column-key={col.accessorKey}
                                        className={[
                                            isSortable ? 'w3f-table-sortable' : '',
                                            isSorted ? 'w3f-table-sorted' : '',
                                            enableColumnReorder ? 'w3f-table-draggable' : '',
                                        ].filter(Boolean).join(' ')}
                                        style={headerAlignStyle(col, widthStyle)}
                                        onClick={isSortable ? () => handleSort(col.accessorKey) : undefined}
                                        onMouseDown={enableColumnReorder ? (e) => handleDragMouseDown(e, col.accessorKey, headerRowRef) : undefined}
                                        aria-sort={isSorted ? (sortState.direction === 'asc' ? 'ascending' : 'descending') : undefined}
                                    >
                                        <span className="w3f-table-header-content">
                                            {col.header}
                                            {isSortable && (
                                                <span className="w3f-table-sort-icon">
                                                    {renderSortIcon(col.accessorKey)}
                                                </span>
                                            )}
                                        </span>
                                        {enableColumnResize && (
                                            <div
                                                className="w3f-table-resize-handle"
                                                onMouseDown={(e) => handleResizeMouseDown(e, col.accessorKey)}
                                            />
                                        )}
                                    </th>
                                );
                            })}
                        </tr>
                    </thead>
                    <tbody ref={tbodyRef}>
                        {visibleData.length === 0 ? (
                            <tr>
                                <td colSpan={displayColumns.length} className="w3f-table-empty">
                                    No se encontraron resultados
                                </td>
                            </tr>
                        ) : (
                            visibleData.map((row, rowIndex) => {
                                const isSelected = selectedRowKey != null
                                    && row[selectedRowKey] === selectedRowValue;
                                return (
                                    <tr
                                        // Clave única siempre: la posición en la página (+ id). Solo con el id,
                                        // ids repetidos o una fila sin id (clave = posición) chocaban y React
                                        // dejaba filas viejas dibujadas al cambiar los datos.
                                        key={`${rowIndex}:${String((row as Record<string, unknown>).id ?? '')}`}
                                        data-row-index={rowIndex}
                                        onClick={onRowClick ? () => onRowClick(row, rowIndex) : undefined}
                                        style={{
                                            cursor: onRowClick ? 'pointer' : undefined,
                                            backgroundColor: isSelected ? 'var(--w3f-primary-50, #eff6ff)' : undefined,
                                            outline: isSelected ? '2px solid var(--w3f-primary, #3b82f6)' : undefined,
                                            outlineOffset: '-2px',
                                        }}
                                    >
                                        {displayColumns.map((col, colIndex) => {
                                            const span = spans ? spans[rowIndex][col.accessorKey] : undefined;
                                            if (span === 0 && spanMode === 'span') return null;   // 0026 X14: la tapa la de arriba
                                            const repeated = span === 0;
                                            const extra = cellExtra(row, col.accessorKey);
                                            const style = cellAlignStyle(col, extra.style);
                                            const isHandle = enableRowReorder && colIndex === 0;   // 0022 C-M
                                            const classes = [isHandle ? 'w3f-table-row-handle' : '',
                                                span != null && span > 1 && spanMode === 'span' ? 'w3f-table-merged' : '',
                                                repeated ? 'w3f-table-merged-repeat' : ''].filter(Boolean).join(' ');
                                            return (
                                                <td
                                                    key={col.accessorKey}
                                                    style={style}
                                                    rowSpan={span != null && span > 1 && spanMode === 'span' ? span : undefined}
                                                    className={classes || undefined}
                                                    onMouseDown={isHandle ? (e) => handleRowDragMouseDown(e, rowIndex, tbodyRef) : undefined}
                                                    onDoubleClick={onCellDoubleClick
                                                        ? () => onCellDoubleClick({ row, column: col.accessorKey, value: row[col.accessorKey], rowIndex })
                                                        : undefined}
                                                >
                                                    {repeated ? null : <>
                                                        {extra.prefix ? `${extra.prefix} ` : null}
                                                        {col.cell ? col.cell(row) : renderValue(col, row[col.accessorKey])}
                                                    </>}
                                                </td>
                                            );
                                        })}
                                    </tr>
                                );
                            })
                        )}
                    </tbody>
                </table>
                {fitHidden > 0 && fitMoreLabel && (
                    <div className="w3f-table-fit-more" data-hidden-rows={fitHidden}
                        style={{ fontSize: '0.7rem', opacity: 0.75, padding: '0.1rem 0.4rem', whiteSpace: 'nowrap' }}>
                        {fitMoreLabel.replace('{n}', fitHidden.toLocaleString('es-AR'))}
                    </div>
                )}
            </div>

            {enablePagination && (
                <div className="w3f-table-pagination">
                    <div className="w3f-table-pagination-info">
                        <span>
                            {totalRows === 0
                                ? '0 resultados'
                                : `${(currentPage - 1) * pageSize + 1}-${Math.min(currentPage * pageSize, totalRows)} de ${totalRows}`
                            }
                        </span>
                        <span>|</span>
                        <label>
                            Filas:
                            <select
                                className="w3f-table-page-size-select"
                                value={pageSize}
                                onChange={handlePageSizeChange}
                                aria-label="Filas por página"
                            >
                                {PAGE_SIZE_OPTIONS.map(opt => (
                                    <option key={opt} value={opt}>{opt}</option>
                                ))}
                            </select>
                        </label>
                    </div>

                    <Pagination
                        count={totalPages}
                        page={currentPage}
                        onChange={(_e: React.MouseEvent, newPage: number) => setCurrentPage(newPage)}
                        size="sm"
                        showFirstButton
                        showLastButton
                        aria-label={ariaLabel ? `Paginación: ${ariaLabel}` : 'Paginación'}
                        {...paginationProps}
                    />
                </div>
            )}
        </div>
    );
}) as <T extends Record<string, unknown>>(props: TableProps<T> & React.RefAttributes<HTMLDivElement>) => React.ReactElement | null;

(Table as React.FC).displayName = 'Table';

export { Table };
export default Table;
