'use client'

import React from 'react';

/**
 * 0022 B53.3 (w3f-data-analysis): un punto con forma (círculo, cuadrado, triángulo, rombo) para Dispersión y Puntos
 * por categoría. Recibe las mismas props SVG que un <circle> (fill, opacity, stroke, eventos…).
 */
export type ChartPointShapeName = 'circle' | 'square' | 'triangle' | 'diamond';

export interface ChartPointShapeProps extends Omit<React.SVGProps<SVGElement>, 'ref'> {
    shape?: ChartPointShapeName;
    cx: number;
    cy: number;
    r: number;
}

/** El `d` de un path con la forma (para square / triangle / diamond). */
export const shapePath = (shape: ChartPointShapeName, cx: number, cy: number, r: number): string => {
    if (shape === 'square') return `M${cx - r},${cy - r}H${cx + r}V${cy + r}H${cx - r}Z`;
    if (shape === 'triangle') return `M${cx},${cy - r * 1.2}L${cx + r * 1.1},${cy + r * 0.8}L${cx - r * 1.1},${cy + r * 0.8}Z`;
    if (shape === 'diamond') return `M${cx},${cy - r * 1.3}L${cx + r * 1.3},${cy}L${cx},${cy + r * 1.3}L${cx - r * 1.3},${cy}Z`;
    return '';
};

export const ChartPointShape: React.FC<ChartPointShapeProps> = ({ shape = 'circle', cx, cy, r, className, ...rest }) => {
    const cls = className ? `w3f-chart-point ${className}` : 'w3f-chart-point';   // VX3: la capa y las reglas CSS
    if (shape === 'circle') return <circle cx={cx} cy={cy} r={r} className={cls} {...(rest as React.SVGProps<SVGCircleElement>)} />;
    return <path d={shapePath(shape, cx, cy, r)} data-shape={shape} className={cls} {...(rest as React.SVGProps<SVGPathElement>)} />;
};

/** Recta de mínimos cuadrados y = a + b·x y su R² (null con menos de 2 puntos o X constante). */
export const linearFit = (xs: number[], ys: number[]): { a: number; b: number; r2: number } | null => {
    const pts = xs.map((x, i) => [x, ys[i]]).filter(([x, y]) => Number.isFinite(x) && Number.isFinite(y));
    const n = pts.length;
    if (n < 2) return null;
    const mx = pts.reduce((s, [x]) => s + x, 0) / n;
    const my = pts.reduce((s, [, y]) => s + y, 0) / n;
    const sxx = pts.reduce((s, [x]) => s + (x - mx) ** 2, 0);
    if (sxx === 0) return null;
    const b = pts.reduce((s, [x, y]) => s + (x - mx) * (y - my), 0) / sxx;
    const a = my - b * mx;
    const ssTot = pts.reduce((s, [, y]) => s + (y - my) ** 2, 0);
    const ssRes = pts.reduce((s, [x, y]) => s + (y - (a + b * x)) ** 2, 0);
    return { a, b, r2: ssTot === 0 ? 1 : 1 - ssRes / ssTot };
};

export default ChartPointShape;
