export const BASE_Z_INDEX = 100;

/** «Ir a esta ventana»: el evento que recibe el contenedor del Desktop con `detail.el` (un elemento del canvas, p. ej.
 *  una Window o un WindowGroup): la vista se centra en él (sin cambiar el zoom) y se resalta un momento. Lo manda
 *  DesktopTree; cualquiera puede mandarlo con `focusDesktopElement`. */
export const FOCUS_EVENT = 'w3f-desktop-focus';
/** Clase que se le pone un momento al elemento al que se fue. */
export const FOCUS_FLASH_CLASS = 'w3f-desktop-flash';

/** La vista (zoom, x, y) para que entren todos los rectángulos `rects` (en px del canvas) en un viewport de vw × vh, con
 *  `margin` px alrededor; el zoom entre minZoom y maxZoom (y nunca más de 1: «ver todo» no agranda). Sin nada, null. */
export function fitView(rects: { left: number; top: number; width: number; height: number }[], vw: number, vh: number,
                        minZoom: number, maxZoom: number, margin = 24): { zoom: number; x: number; y: number } | null {
    const r = rects.filter((q) => q.width > 0 && q.height > 0);
    if (!r.length || vw <= 0 || vh <= 0) return null;
    const x0 = Math.min(...r.map((q) => q.left)), y0 = Math.min(...r.map((q) => q.top));
    const x1 = Math.max(...r.map((q) => q.left + q.width)), y1 = Math.max(...r.map((q) => q.top + q.height));
    const w = x1 - x0, h = y1 - y0;
    let zoom = Math.min((vw - 2 * margin) / w, (vh - 2 * margin) / h, 1, maxZoom);
    zoom = Math.max(minZoom, Math.floor(zoom * 100) / 100);
    return { zoom, x: Math.round((vw - w * zoom) / 2 - x0 * zoom), y: Math.round((vh - h * zoom) / 2 - y0 * zoom) };
}

/** Centra la vista del Desktop que contiene a `el` en ese elemento. */
export function focusDesktopElement(el: HTMLElement): boolean {
    const root = el.closest('.w3f-desktop');
    if (!root) return false;
    root.dispatchEvent(new CustomEvent(FOCUS_EVENT, { detail: { el } }));
    return true;
}

/** La rueda sobre estos elementos desplaza su contenido (no hace zoom); con Ctrl hace zoom igual. */
export const WHEEL_SCROLL_SELECTOR = '.w3f-window';
