'use client'

import React, { useMemo } from 'react';
import { Group } from '@visx/group';
import { Mercator, Graticule } from '@visx/geo';
import type { GeoInnerProps, GeoFeatureDatum } from './Geo.types';
import { GEO_DEFAULTS } from './Geo.constants';
import { buildGeoClasses, buildTooltipContent, geoPointStyle } from './Geo.utils';
import { resolveColorScheme } from '../_base/utils';
import { useGeoColorScale, useGeoInteraction } from './Geo.hooks';
import { ChartTooltip } from '../primitives/ChartTooltip';
import { BASE_CHART_CLASSES } from '../_base/constants';
import { ChartHeader } from '../_base/ChartHeader';

import './Geo.css';

export const GeoInner: React.FC<GeoInnerProps> = (props) => {
    const {
        data, width, height, className,
        unstyled = GEO_DEFAULTS.unstyled,
        bindId, ariaLabel, description, colorScheme, title, subtitle,
        showTooltip = GEO_DEFAULTS.showTooltip,
        showGraticule = GEO_DEFAULTS.showGraticule,
        fillDefault = GEO_DEFAULTS.fillDefault,
        strokeColor = GEO_DEFAULTS.strokeColor,
        strokeWidth = GEO_DEFAULTS.strokeWidth,
        colorScale: scaleType = 'linear',
        onHover, onSelect,
        showRegionLabels = false, regionLabelSize = 9,   // 0022 B53.6
        pointMaxRadius = 18, pointOpacity = 0.7, pointColor,   // 0022 PB11
    } = props;
    const points = data.points ?? [];
    const [hoveredPoint, setHoveredPoint] = React.useState<number | null>(null);
    const pointStyle = useMemo(() => geoPointStyle(points, data.groups ?? [], resolveColorScheme(colorScheme),
                                                   pointMaxRadius, pointColor), [points, data.groups, colorScheme,
                                                   pointMaxRadius, pointColor]);

    // Build value lookup: feature id → datum
    const valueMap = useMemo(() => {
        const map = new Map<string, GeoFeatureDatum>();
        for (const v of data.values) {
            map.set(v.id, v);
        }
        return map;
    }, [data.values]);

    // Extract numeric values for color scale
    const numericValues = useMemo(
        () => data.values.map((v) => v.value),
        [data.values],
    );

    const colorScale = useGeoColorScale(numericValues, colorScheme, props.colorLog ? 'log' : scaleType, props.colorMin, props.colorMax);   // VX4
    const { hoveredIndex, handleEnter, handleLeave, handleClick } = useGeoInteraction(onHover, onSelect);
    const classes = useMemo(() => buildGeoClasses(className, unstyled), [className, unstyled]);

    const geojsonFeatures = data.geojson?.features;

    if (!geojsonFeatures || geojsonFeatures.length === 0) {
        return (
            <div className={classes}>
                <svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Empty geo chart'} />
            </div>
        );
    }

    const centerX = width / 2;
    const centerY = height / 2;

    return (
        <div className={classes} data-bind-id={bindId}>
            <ChartHeader title={title} subtitle={subtitle} />
            <div className={BASE_CHART_CLASSES.container} style={{ position: 'relative' }}>
                <svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Choropleth map'}>
                    {description && <desc>{description}</desc>}
                    <Mercator<any>
                        data={geojsonFeatures}
                        fitSize={[[width, height], data.geojson as any]}
                    >
                        {(mercator) => (
                            <Group>
                                {showGraticule && (
                                    <Graticule
                                        graticule={(g) => mercator.path(g) || ''}
                                        stroke="var(--w3f-border-light, #ddd)"
                                        strokeWidth={0.3}
                                        strokeOpacity={0.4}
                                    />
                                )}
                                {mercator.features.map(({ feature, path }, i) => {
                                    const featureId = feature.id ?? feature.properties?.iso_a3 ?? feature.properties?.id ?? feature.properties?.name ?? String(i);
                                    const match = valueMap.get(String(featureId));
                                    const fillColor = match ? colorScale(match.value) : fillDefault;
                                    const isHovered = hoveredIndex === i;
                                    const dimmed = hoveredIndex != null && !isHovered;

                                    const datum: GeoFeatureDatum = match ?? {
                                        id: String(featureId),
                                        value: 0,
                                        label: feature.properties?.name ?? String(featureId),
                                    };

                                    return (
                                        <path
                                            key={`geo-${i}`}
                                            d={path || ''}
                                            fill={fillColor}
                                            stroke={strokeColor}
                                            strokeWidth={isHovered ? strokeWidth * 2 : strokeWidth}
                                            opacity={dimmed ? 0.6 : 1}
                                            style={{ transition: 'opacity 120ms ease-out, stroke-width 120ms ease-out', cursor: onSelect ? 'pointer' : 'default' }}
                                            onMouseEnter={() => handleEnter(datum, i)}
                                            onMouseLeave={handleLeave}
                                            onClick={onSelect ? () => handleClick(datum, i) : undefined}
                                        />
                                    );
                                })}
                                {showRegionLabels && mercator.features.map(({ feature }, i) => {
                                    const [lx, ly] = mercator.path.centroid(feature as any);
                                    if (!Number.isFinite(lx) || !Number.isFinite(ly)) return null;
                                    const name = feature.properties?.name ?? String(feature.id ?? '');
                                    return (
                                        <text key={`geo-label-${i}`} x={lx} y={ly} fontSize={regionLabelSize}
                                            textAnchor="middle" dominantBaseline="central" pointerEvents="none"
                                            className="w3f-chart-region-label"
                                            style={{ fill: 'var(--w3f-chart-value-label-color, #888899)',
                                                     fontFamily: 'var(--w3f-chart-label-font, inherit)' }}>
                                            {name}
                                        </text>
                                    );
                                })}
                                {points.map((p, i) => {   /* 0022 PB11: los puntos encima de las formas */
                                    const xy = mercator.projection([p.lon, p.lat]);
                                    if (!xy || !Number.isFinite(xy[0]) || !Number.isFinite(xy[1])) return null;
                                    const st = pointStyle[i];
                                    const dimmed = hoveredPoint != null && hoveredPoint !== i;
                                    return (
                                        <circle key={`geo-pt-${i}`} cx={xy[0]} cy={xy[1]} r={st.r} fill={st.fill}
                                            className="w3f-chart-geo-point" data-group={p.group}
                                            fillOpacity={dimmed ? pointOpacity * 0.4 : pointOpacity}
                                            stroke="var(--w3f-chart-mark-outline, #fff)" strokeWidth={0.8}
                                            style={{ cursor: onSelect ? 'pointer' : 'default' }}
                                            onMouseEnter={() => setHoveredPoint(i)}
                                            onMouseLeave={() => setHoveredPoint(null)}
                                            onClick={onSelect ? () => onSelect({ id: p.label ?? `${p.lat},${p.lon}`,
                                                value: p.value, label: p.label, ...(p as any) }, i) : undefined} />
                                    );
                                })}
                            </Group>
                        )}
                    </Mercator>
                </svg>

                {showTooltip && hoveredPoint != null && points[hoveredPoint] && (
                    <ChartTooltip left={centerX} top={centerY} visible offsetY={-24}>
                        {buildTooltipContent({ id: '', value: points[hoveredPoint].value,
                                               label: [points[hoveredPoint].label, points[hoveredPoint].group]
                                                   .filter(Boolean).join(' · ') })}
                    </ChartTooltip>
                )}
                {(data.groups?.length ?? 0) > 1 && (   /* 0022 PB11: qué color es cada grupo */
                    <div className="w3f-chart-geo-legend" style={{ display: 'flex', flexWrap: 'wrap', gap: '0.25rem 0.75rem',
                                                                  fontSize: '0.75rem', padding: '0.25rem 0.5rem' }}>
                        {data.groups!.map((g, i) => (
                            <span key={g} style={{ display: 'inline-flex', alignItems: 'center', gap: '0.3rem' }}>
                                <span style={{ width: 10, height: 10, borderRadius: '50%', display: 'inline-block',
                                               background: resolveColorScheme(colorScheme)[i % resolveColorScheme(colorScheme).length] }} />
                                {g}
                            </span>
                        ))}
                    </div>
                )}
                {showTooltip && hoveredIndex != null && (() => {
                    const feature = geojsonFeatures[hoveredIndex];
                    if (!feature) return null;
                    const featureId = feature.id ?? feature.properties?.iso_a3 ?? feature.properties?.id ?? feature.properties?.name ?? String(hoveredIndex);
                    const match = valueMap.get(String(featureId));
                    const datum: GeoFeatureDatum = match ?? {
                        id: String(featureId),
                        value: 0,
                        label: feature.properties?.name ?? String(featureId),
                    };
                    return (
                        <ChartTooltip
                            left={centerX}
                            top={centerY}
                            visible
                            offsetY={-24}
                        >
                            {buildTooltipContent(datum)}
                        </ChartTooltip>
                    );
                })()}
            </div>
        </div>
    );
};

GeoInner.displayName = 'GeoInner';
export default GeoInner;
