'use client'

import React, { useMemo } from 'react';
import { Group } from '@visx/group';
import type { ScatterDatum, ScatterInnerProps } from './Scatter.types';
import { SCATTER_DEFAULTS } from './Scatter.constants';
import { buildScatterClasses, buildTooltipContent, formatTick } from './Scatter.utils';
import {
    useScatterAccessors,
    useScatterScales,
    useScatterColors,
    useScatterInteraction,
    useInnerDims,
} from './Scatter.hooks';
import { adaptScale, plotLeft, plotTop, xAxisLayout, yAxisLayout } from '../_base/axisLayout';   // 0026 X7
import { ChartAxis } from '../primitives/ChartAxis';
import { ChartPointShape, linearFit } from '../primitives/ChartPointShape';   // 0022 B53.3
import { ChartGrid } from '../primitives/ChartGrid';
import { ChartReferenceLines, overlayPoints } from '../primitives/ChartReferenceLines';
import { hexBins, hexPath } from './Scatter.hexbin';   // VX9
import { ChartSecondaryAxes } from '../primitives/ChartSecondaryAxes';   // VX9
import { ChartTooltip } from '../primitives/ChartTooltip';
import { BASE_CHART_CLASSES } from '../_base/constants';
import { ChartHeader } from '../_base/ChartHeader';
import { ChartMarkDecorLayer } from '../primitives/ChartMarkDecor';   // VX3

export const ScatterInner: React.FC<ScatterInnerProps> = (props) => {
    const {
        data,
        width,
        height,
        margin,
        className,
        unstyled = SCATTER_DEFAULTS.unstyled,
        bindId,
        ariaLabel,
        description,
        colorScheme, title, subtitle,
        getX: getXProp,
        getY: getYProp,
        getR: getRProp,
        getLabel: getLabelProp,
        showXAxis = SCATTER_DEFAULTS.showXAxis,
        showYAxis = SCATTER_DEFAULTS.showYAxis,
        showGrid = SCATTER_DEFAULTS.showGrid,
        showTooltip = SCATTER_DEFAULTS.showTooltip,
        pointRadius = SCATTER_DEFAULTS.pointRadius,
        xDomain,
        yDomain,
        formatX,
        formatY,
        onHover,
        onSelect,
        highlightIndex = null,
        pointShape = 'circle', pointOpacity = 0.8, pointStroke, trendLine = false,   // 0022 B53.3
    } = props;

    const { getX, getY, getR, getLabel } = useScatterAccessors(getXProp, getYProp, getRProp, getLabelProp);
    const dims = useInnerDims(width, height, margin, props);
    const { xScale: xScaleRaw, yScale: yScaleRaw } = useScatterScales(data, dims.innerWidth, dims.innerHeight, getX, getY, xDomain, yDomain);
    const xScale = adaptScale(xScaleRaw, props, 'x');   // VX1: mínimo / máximo, log, al revés…
    const yScale = adaptScale(yScaleRaw, props, 'y');   // VX1: mínimo / máximo, log, al revés…
    const colors = useScatterColors(data, colorScheme);
    const { hoveredIndex, handleEnter, handleLeave, handleClick } = useScatterInteraction(onHover, onSelect);

    const classes = useMemo(() => buildScatterClasses(className, unstyled), [className, unstyled]);
    const xTickFormat = formatX ?? formatTick;
    const yTickFormat = formatY ?? formatTick;

    if (data.length === 0) {
        return (
            <div className={classes}>
                <svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Empty scatter chart'} />
            </div>
        );
    }

    return (
        <div className={classes} data-bind-id={bindId}>
            <ChartHeader title={title} subtitle={subtitle} />
            <div className={BASE_CHART_CLASSES.container} style={{ position: 'relative' }}>
                <svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Scatter chart'}>
                    {description && <desc>{description}</desc>}
                    <Group top={plotTop(dims, props)} left={plotLeft(dims, props)}>
                        {showGrid && (
                            <ChartGrid
                                xScale={xScale}
                                yScale={yScale}
                                width={dims.innerWidth}
                                height={dims.innerHeight}
                                axis="both"
                            />
                        )}

                        {props.hexbin ? (() => {   // VX9: hexágonos con la cantidad de puntos de cada uno
                            const size = props.hexSize ?? 14;
                            const bins = hexBins(data.map((d) => [xScale(getX(d)) ?? NaN, yScale(getY(d)) ?? NaN] as [number, number]), size);
                            const max = Math.max(1, ...bins.map((b) => b.n));
                            return (
                                <g className="w3f-chart-hexbins">
                                    {bins.map((b, i) => (
                                        <path key={i} className="w3f-chart-hexbin" d={hexPath(b.x, b.y, size)} fill={colors[0]}
                                            fillOpacity={0.15 + 0.85 * (b.n / max)} stroke={pointStroke || 'none'}>
                                            <title>{`${b.n}`}</title>
                                        </path>
                                    ))}
                                </g>
                            );
                        })() : data.map((d, i) => {
                            const cx = xScale(getX(d)) ?? 0;
                            const cy = yScale(getY(d)) ?? 0;
                            const r = getR(d) ?? pointRadius;

                            return (
                                <ChartPointShape
                                    key={i}
                                    shape={pointShape}
                                    cx={cx}
                                    cy={cy}
                                    r={r}
                                    fill={colors[i]}
                                    opacity={
                                        highlightIndex != null
                                            ? (highlightIndex === i ? 1 : 0.3)
                                            : hoveredIndex != null && hoveredIndex !== i ? Math.min(0.4, pointOpacity) : pointOpacity
                                    }
                                    stroke={highlightIndex === i ? 'var(--w3f-chart-mark-outline, #fff)' : (pointStroke || undefined)}
                                    strokeWidth={highlightIndex === i ? 2 : (pointStroke ? 1 : undefined)}
                                    onMouseEnter={() => handleEnter(d, i)}
                                    onMouseLeave={handleLeave}
                                    onClick={onSelect ? () => handleClick(d, i) : undefined}
                                    style={{ cursor: highlightIndex === i ? 'pointer' : onSelect ? 'pointer' : undefined, transition: 'opacity 120ms ease-out' }}
                                />
                            );
                        })}

                        {trendLine && (() => {   // 0022 B53.3: la recta de tendencia y su ecuación
                            const fit = linearFit(data.map(getX), data.map(getY));
                            if (!fit) return null;
                            const [x0, x1] = xScale.domain() as [number, number];
                            const fmt = (v: number) => v.toLocaleString('es-AR', { maximumFractionDigits: 3 });
                            return (
                                <g className="w3f-chart-trend" pointerEvents="none">
                                    <line x1={xScale(x0)} y1={yScale(fit.a + fit.b * x0)} x2={xScale(x1)} y2={yScale(fit.a + fit.b * x1)}
                                        stroke="var(--w3f-chart-trend-color, #f97316)" strokeWidth={2} strokeDasharray="6 4" />
                                    <text x={dims.innerWidth - 4} y={12} textAnchor="end" fontSize={11}
                                        style={{ fill: 'var(--w3f-chart-trend-color, #f97316)' }}>
                                        {`y = ${fmt(fit.b)}·x ${fit.a < 0 ? '−' : '+'} ${fmt(Math.abs(fit.a))}  (R² = ${fmt(fit.r2)})`}
                                    </text>
                                </g>
                            );
                        })()}
                        {showXAxis && (
                            <ChartAxis scale={xScale} {...xAxisLayout(dims, props)} tickFormat={xTickFormat} />
                        )}
                        {showYAxis && (
                            <ChartAxis scale={yScale} {...yAxisLayout(dims, props)} tickFormat={yTickFormat} />
                        )}
                        <ChartSecondaryAxes {...props} xScale={xScale} yScale={yScale} width={dims.innerWidth} height={dims.innerHeight} />
                        <ChartReferenceLines lines={props.referenceLines} bands={props.referenceBands} annotation={props.annotation}
                            points={overlayPoints(data)} xScale={xScale}
                            yScale={(v: number) => yScale(v)} width={dims.innerWidth} height={dims.innerHeight} />
                    </Group>
                    <ChartMarkDecorLayer {...props} />   {/* VX3: trama, hueco, borde de dos colores */}
                </svg>

                {showTooltip && hoveredIndex != null && (
                    <ChartTooltip
                        left={(xScale(getX(data[hoveredIndex])) ?? 0) + plotLeft(dims, props)}
                        top={(yScale(getY(data[hoveredIndex])) ?? 0) + plotTop(dims, props)}
                        visible
                        offsetY={-12}
                    >
                        {buildTooltipContent(data[hoveredIndex], getX, getY)}
                    </ChartTooltip>
                )}
            </div>
        </div>
    );
};

ScatterInner.displayName = 'ScatterInner';
export default ScatterInner;
