import { useState, useCallback, useEffect, useRef } from 'react';
import type React from 'react';
import { bringToFront, syncWindowOrder } from './Desktop.utils';
import { WHEEL_SCROLL_SELECTOR } from './Desktop.constants';

// ── useWindowOrder ─────────────────────────────────────────────────────────────

/**
 * Gestiona el orden z-index de las ventanas en el Desktop.
 * La ventana con foco más reciente queda al frente (mayor z-index).
 */
export function useWindowOrder(children: React.ReactNode) {
    const [windowOrder, setWindowOrder] = useState<string[]>([]);

    useEffect(() => {
        const currentKeys: string[] = [];
        const childArray = Array.isArray(children) ? children : [children];
        for (const child of childArray) {
            if (child && typeof child === 'object' && 'key' in child && child.key) {
                currentKeys.push(String(child.key));
            }
        }
        setWindowOrder((prev) => syncWindowOrder(prev, currentKeys));
    }, [children]);

    const handleWindowFocus = useCallback((key: string) => {
        setWindowOrder((prev) => bringToFront(prev, key));
    }, []);

    return { windowOrder, handleWindowFocus };
}

// ── useCanvasTransform ────────────────────────────────────────────────────────

interface UseCanvasTransformOptions {
    zoomEnabled: boolean;
    panEnabled: boolean;
    defaultZoom: number;
    minZoom: number;
    maxZoom: number;
    zoomStep: number;
    defaultPan: { x: number; y: number };
    containerRef: React.RefObject<HTMLDivElement | null>;
}

/**
 * Gestiona zoom (hacia el cursor) y pan (drag sobre el fondo) del canvas interno.
 *
 * Zoom: rueda del mouse → zoom hacia el punto del cursor.
 * Pan: mousedown en el fondo del canvas → drag para desplazar.
 *
 * Se usa transform-origin: 0 0 con:
 *   transform: translate(pan.x, pan.y) scale(zoom)
 */
export function useCanvasTransform({
    zoomEnabled,
    panEnabled,
    defaultZoom,
    minZoom,
    maxZoom,
    zoomStep,
    defaultPan,
    containerRef,
}: UseCanvasTransformOptions) {
    const [zoom, setZoom] = useState(defaultZoom);
    const [pan, setPan] = useState(defaultPan);
    const [isPanning, setIsPanning] = useState(false);

    // Refs para acceder a estado actual dentro de callbacks sin stale closures
    const stateRef = useRef({ zoom, pan });
    useEffect(() => {
        stateRef.current = { zoom, pan };
    }, [zoom, pan]);

    // ── Zoom con rueda del mouse ─────────────────────────────────────────────
    // Usa addEventListener no-pasivo para poder llamar preventDefault()
    useEffect(() => {
        if (!zoomEnabled) return;
        const el = containerRef.current;
        if (!el) return;

        const onWheel = (e: WheelEvent) => {
            // Sobre una ventana la rueda desplaza su contenido (menús, listas, tablas); Ctrl + rueda hace zoom igual
            const target = e.target as Element | null;
            if (!e.ctrlKey && target?.closest?.(WHEEL_SCROLL_SELECTOR)) return;
            e.preventDefault();
            const { zoom: currentZoom, pan: currentPan } = stateRef.current;
            const delta = e.deltaY < 0 ? zoomStep : -zoomStep;
            const newZoom = Math.min(maxZoom, Math.max(minZoom, Math.round((currentZoom + delta) * 100) / 100));

            if (newZoom === currentZoom) return;

            // Zoom hacia el punto del cursor (zoom-to-cursor)
            const rect = el.getBoundingClientRect();
            const cursorX = e.clientX - rect.left;
            const cursorY = e.clientY - rect.top;

            // Punto en el canvas bajo el cursor (coordenadas del canvas sin transformar)
            const canvasX = (cursorX - currentPan.x) / currentZoom;
            const canvasY = (cursorY - currentPan.y) / currentZoom;

            // Nuevo pan para que el mismo punto del canvas siga bajo el cursor
            const newPanX = cursorX - canvasX * newZoom;
            const newPanY = cursorY - canvasY * newZoom;

            setZoom(newZoom);
            setPan({ x: newPanX, y: newPanY });
        };

        el.addEventListener('wheel', onWheel, { passive: false });
        return () => el.removeEventListener('wheel', onWheel);
    }, [zoomEnabled, containerRef, zoomStep, minZoom, maxZoom]);

    // ── Controles de zoom ───────────────────────────────────────────────────
    const clamp = useCallback(
        (v: number) => Math.min(maxZoom, Math.max(minZoom, Math.round(v * 100) / 100)),
        [minZoom, maxZoom],
    );

    const zoomIn  = useCallback(() => setZoom((prev) => clamp(prev + zoomStep)), [clamp, zoomStep]);
    const zoomOut = useCallback(() => setZoom((prev) => clamp(prev - zoomStep)), [clamp, zoomStep]);
    const resetZoom = useCallback(() => {
        setZoom(defaultZoom);
        setPan(defaultPan);
    }, [defaultZoom, defaultPan]);

    /** Establece el zoom directamente (desde Slider). No ajusta el pan. */
    const setZoomLevel = useCallback((v: number) => setZoom(clamp(v)), [clamp]);

    // ── Focus desde árbol lateral (CustomEvent 'w3f-desktop-focus') ────────
    useEffect(() => {
        const handler = (e: Event) => {
            const { x, y } = (e as CustomEvent<{ x: number; y: number }>).detail;
            setPan({ x, y });
        };
        window.addEventListener('w3f-desktop-focus', handler);
        return () => window.removeEventListener('w3f-desktop-focus', handler);
    }, []);

    // ── Pan: drag sobre el fondo (infinito) ──────────────────────────────────
    // El handler va en el viewport: se puede arrastrar desde cualquier punto de
    // fondo visible, esté o no dentro del rectángulo del canvas → pan sin límites.
    const handlePanStart = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
        if (!panEnabled || e.button !== 0) return;
        // Solo el fondo: el viewport o el canvas mismo (no una Window/grupo hijo)
        const target = e.target as HTMLElement;
        const isBackground = target === e.currentTarget
            || target.parentElement === e.currentTarget;
        if (!isBackground) return;
        e.preventDefault();

        const startMouse = { x: e.clientX, y: e.clientY };
        const startPan = { ...stateRef.current.pan };

        setIsPanning(true);

        const handleMouseMove = (ev: MouseEvent) => {
            setPan({
                x: startPan.x + (ev.clientX - startMouse.x),
                y: startPan.y + (ev.clientY - startMouse.y),
            });
        };

        const handleMouseUp = () => {
            setIsPanning(false);
            document.removeEventListener('mousemove', handleMouseMove);
            document.removeEventListener('mouseup', handleMouseUp);
        };

        document.addEventListener('mousemove', handleMouseMove);
        document.addEventListener('mouseup', handleMouseUp);
    }, [panEnabled]);

    /** Zoom y desplazamiento a la vez (prop `view` del Desktop). */
    const setView = useCallback((v: { zoom: number; x: number; y: number }) => {
        setZoom(clamp(v.zoom));
        setPan({ x: v.x, y: v.y });
    }, [clamp]);

    return { zoom, pan, isPanning, zoomIn, zoomOut, resetZoom, setZoomLevel, setView, handlePanStart };
}
