'use client'

import React, { useMemo } from 'react';
import { Group } from '@visx/group';
import type { BoxPlotInnerProps } from './BoxPlot.types';
import { BOXPLOT_DEFAULTS } from './BoxPlot.constants';
import { buildBoxPlotClasses, buildTooltipContent, formatTick } from './BoxPlot.utils';
import {
    useBoxPlotStats,
    // (VX6: las escalas se arman en el componente, según la orientación)
    useBoxPlotColors,
    useBoxPlotInteraction,
    useInnerDims,
} from './BoxPlot.hooks';
import { adaptScale, plotLeft, plotTop, xAxisLayout, yAxisLayout } from '../_base/axisLayout';   // 0026 X7
import { ChartAxis } from '../primitives/ChartAxis';
import { ChartGrid } from '../primitives/ChartGrid';
import { ChartReferenceLines } from '../primitives/ChartReferenceLines';
import { ChartSecondaryAxes } from '../primitives/ChartSecondaryAxes';   // VX9
import { ChartTooltip } from '../primitives/ChartTooltip';
import { BASE_CHART_CLASSES } from '../_base/constants';
import { buildBandScale, buildLinearScale, safeExtent } from '../_base/utils';   // VX6
import { lineDash } from '../primitives/ChartLineMarks';   // VX6
import { ChartHeader } from '../_base/ChartHeader';

export const BoxPlotInner: React.FC<BoxPlotInnerProps> = (props) => {
    const {
        data, width, height, margin, className,
        unstyled = BOXPLOT_DEFAULTS.unstyled, bindId, ariaLabel, description, colorScheme, title, subtitle,
        showXAxis = BOXPLOT_DEFAULTS.showXAxis, showYAxis = BOXPLOT_DEFAULTS.showYAxis,
        showGrid = BOXPLOT_DEFAULTS.showGrid, showTooltip = BOXPLOT_DEFAULTS.showTooltip,
        showOutliers = BOXPLOT_DEFAULTS.showOutliers, boxWidth = BOXPLOT_DEFAULTS.boxWidth,
        yDomain, formatY, onHover, onSelect,
        // VX6 (lo que trae matplotlib en boxplot)
        boxOrientation = 'vertical', boxWhisker = 'iqr15', boxShowMeans = 'none', boxMeanColor,
        boxNotch = false, boxShowCaps = true, boxCapWidth = 0.5, boxMedianColor, boxMedianWidth = 2.5,
        boxFlierShape = 'circle', boxFlierColor, boxWhiskerStyle = 'solid',
    } = props;

    const stats = useBoxPlotStats(data, boxWhisker);
    // VX6: acostados, los nombres de los grupos van a la izquierda: el margen según el más largo
    const hMargin = useMemo(() => {
        if (boxOrientation !== 'horizontal') return margin;
        const longest = Math.max(0, ...data.map((d) => String(d.group).length));
        const base = margin ?? { top: 20, right: 20, bottom: 40, left: 50 };
        return { ...base, left: Math.max(base.left, Math.min(220, Math.round(longest * 6.5) + 14)) };
    }, [margin, data, boxOrientation]);
    const dims = useInnerDims(width, height, hMargin, props);
    const H = boxOrientation === 'horizontal';
    // las escalas: categorías a lo ancho y valores a lo alto (o al revés, con las cajas acostadas)
    const { catScale, valScale } = useMemo(() => {
        const groups = stats.map((st) => st.group);
        const all = stats.flatMap((st) => [st.min, st.max, ...st.outliers, ...(st.mean != null ? [st.mean] : [])]);
        const [lo, hi] = yDomain ?? safeExtent(all);
        return {
            catScale: buildBandScale(groups, H ? [0, dims.innerHeight] : [0, dims.innerWidth], 0.3),
            valScale: buildLinearScale(lo, hi, H ? [0, dims.innerWidth] : [dims.innerHeight, 0]),
        };
    }, [stats, dims.innerWidth, dims.innerHeight, yDomain, H]);
    const xScale = adaptScale(H ? valScale : catScale, props, 'x') as any;   // VX1
    const yScale = adaptScale(H ? catScale : valScale, props, 'y') as any;   // VX1
    const cat = H ? yScale : xScale;
    const val = H ? xScale : yScale;
    const colors = useBoxPlotColors(stats, colorScheme);
    const { hoveredIndex, handleEnter, handleLeave, handleClick } = useBoxPlotInteraction(onHover, onSelect);

    const classes = useMemo(() => buildBoxPlotClasses(className, unstyled), [className, unstyled]);
    const yf = formatY ?? formatTick;

    if (data.length === 0) {
        return (
            <div className={classes}>
                <svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Empty box plot'} />
            </div>
        );
    }

    const halfBox = Math.min(boxWidth, cat.bandwidth()) / 2;
    // (c = lugar sobre la categoría, v = valor) → (x, y)
    const pt = (c: number, v: number): [number, number] => (H ? [val(v) ?? 0, c] : [c, val(v) ?? 0]);
    const seg = (c1: number, v1: number, c2: number, v2: number, p2: React.SVGProps<SVGLineElement>, key?: string) => {
        const [x1, y1] = pt(c1, v1);
        const [x2, y2] = pt(c2, v2);
        return <line key={key} x1={x1} y1={y1} x2={x2} y2={y2} {...p2} />;
    };
    const flier = (cx: number, v: number, color: string, k: number) => {
        const [x, y] = pt(cx, v);
        const r = 3;
        if (boxFlierShape === 'x') return <path key={k} className="w3f-chart-box-flier" d={`M${x - r},${y - r}L${x + r},${y + r}M${x - r},${y + r}L${x + r},${y - r}`} stroke={color} strokeWidth={1.5} />;
        if (boxFlierShape === 'diamond') return <path key={k} className="w3f-chart-box-flier" d={`M${x},${y - r * 1.3}L${x + r * 1.3},${y}L${x},${y + r * 1.3}L${x - r * 1.3},${y}Z`} fill="none" stroke={color} strokeWidth={1.5} />;
        if (boxFlierShape === 'square') return <rect key={k} className="w3f-chart-box-flier" x={x - r} y={y - r} width={2 * r} height={2 * r} fill="none" stroke={color} strokeWidth={1.5} />;
        return <circle key={k} className="w3f-chart-box-flier" cx={x} cy={y} r={r} fill="none" stroke={color} strokeWidth={1.5} />;
    };

    return (
        <div className={classes} data-bind-id={bindId}>
            <ChartHeader title={title} subtitle={subtitle} />
            <div className={BASE_CHART_CLASSES.container} style={{ position: 'relative' }}>
                <svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Box plot'}>
                    {description && <desc>{description}</desc>}
                    <Group top={plotTop(dims, props)} left={plotLeft(dims, props)}>
                        {showGrid && (H
                            ? <ChartGrid xScale={val} width={dims.innerWidth} height={dims.innerHeight} axis="columns" />
                            : <ChartGrid yScale={val} width={dims.innerWidth} height={dims.innerHeight} axis="rows" />)}

                        {stats.map((st, i) => {
                            const cx = (cat(st.group) ?? 0) + cat.bandwidth() / 2;
                            const isHovered = hoveredIndex === i;
                            const opacity = hoveredIndex != null && !isHovered ? 0.4 : 1;
                            const fill = colors[i];
                            const wh = { stroke: fill, strokeWidth: 1.5, ...lineDash(boxWhiskerStyle, 1.5) };
                            const cap = halfBox * boxCapWidth;
                            // la caja (con muesca: se angosta en la mediana, matplotlib notch)
                            const nLo = Math.max(st.notchLow ?? st.median, st.firstQuartile);
                            const nHi = Math.min(st.notchHigh ?? st.median, st.thirdQuartile);
                            const boxPts: Array<[number, number]> = boxNotch
                                ? [[cx - halfBox, st.firstQuartile], [cx - halfBox, nLo], [cx - halfBox * 0.5, st.median],
                                   [cx - halfBox, nHi], [cx - halfBox, st.thirdQuartile], [cx + halfBox, st.thirdQuartile],
                                   [cx + halfBox, nHi], [cx + halfBox * 0.5, st.median], [cx + halfBox, nLo],
                                   [cx + halfBox, st.firstQuartile]]
                                : [[cx - halfBox, st.firstQuartile], [cx - halfBox, st.thirdQuartile],
                                   [cx + halfBox, st.thirdQuartile], [cx + halfBox, st.firstQuartile]];
                            const boxPath = 'M' + boxPts.map(([c, v]) => pt(c, v).join(',')).join('L') + 'Z';
                            const medHalf = boxNotch ? halfBox * 0.5 : halfBox;

                            return (
                                <g
                                    key={st.group}
                                    opacity={opacity}
                                    style={{ transition: 'opacity 120ms ease-out', cursor: onSelect ? 'pointer' : undefined }}
                                    onMouseEnter={() => handleEnter(st, i)}
                                    onMouseLeave={handleLeave}
                                    onClick={onSelect ? () => handleClick(st, i) : undefined}
                                >
                                    {/* Bigotes (de la caja al mínimo / máximo) y sus topes */}
                                    {seg(cx, st.thirdQuartile, cx, st.max, wh, 'wu')}
                                    {seg(cx, st.firstQuartile, cx, st.min, wh, 'wl')}
                                    {boxShowCaps && seg(cx - cap, st.max, cx + cap, st.max, { stroke: fill, strokeWidth: 1.5 }, 'cu')}
                                    {boxShowCaps && seg(cx - cap, st.min, cx + cap, st.min, { stroke: fill, strokeWidth: 1.5 }, 'cl')}

                                    {/* La caja (Q1 → Q3) */}
                                    <path d={boxPath} fill={fill} fillOpacity={0.3} stroke={fill} strokeWidth={1.5} className="w3f-chart-box" />

                                    {/* La mediana */}
                                    {seg(cx - medHalf, st.median, cx + medHalf, st.median,
                                        { stroke: boxMedianColor ?? fill, strokeWidth: boxMedianWidth, className: 'w3f-chart-box-median' }, 'med')}

                                    {/* VX6: el promedio, como punto o como línea */}
                                    {boxShowMeans === 'line' && st.mean != null && seg(cx - halfBox, st.mean, cx + halfBox, st.mean,
                                        { stroke: boxMeanColor ?? fill, strokeWidth: 1.5, strokeDasharray: '4 3', className: 'w3f-chart-box-mean' }, 'mean')}
                                    {boxShowMeans === 'point' && st.mean != null && (() => {
                                        const [x, y] = pt(cx, st.mean);
                                        return <path d={`M${x},${y - 5}L${x + 5},${y}L${x},${y + 5}L${x - 5},${y}Z`}
                                            fill={boxMeanColor ?? '#ffffff'} stroke={fill} strokeWidth={1} className="w3f-chart-box-mean" />;
                                    })()}

                                    {/* Atípicos */}
                                    {showOutliers && st.outliers.map((v, oi) => flier(cx, v, boxFlierColor ?? fill, oi))}
                                </g>
                            );
                        })}

                        {showXAxis && <ChartAxis scale={xScale} {...xAxisLayout(dims, props)} tickFormat={H ? yf : undefined} />}
                        {showYAxis && <ChartAxis scale={yScale} {...yAxisLayout(dims, props)} tickFormat={H ? undefined : yf} />}
                        <ChartSecondaryAxes {...props} xScale={xScale} yScale={yScale} width={dims.innerWidth} height={dims.innerHeight} />
                        {!H && <ChartReferenceLines lines={props.referenceLines} bands={props.referenceBands} annotation={props.annotation}
                            points={[]} xScale={xScale}
                            yScale={(v: number) => yScale(v)} width={dims.innerWidth} height={dims.innerHeight} />}
                    </Group>
                </svg>

                {showTooltip && hoveredIndex != null && (() => {
                    const st = stats[hoveredIndex];
                    const [x, y] = pt((cat(st.group) ?? 0) + cat.bandwidth() / 2, st.median);
                    return (
                        <ChartTooltip left={x + plotLeft(dims, props)} top={y + plotTop(dims, props)} visible offsetY={-12}>
                            {buildTooltipContent(st)}
                        </ChartTooltip>
                    );
                })()}
            </div>
        </div>
    );
};

BoxPlotInner.displayName = 'BoxPlotInner';
export default BoxPlotInner;
