import type { GeoFeatureDatum } from './Geo.types';
import { GEO_ROOT_CLASS } from './Geo.constants';
import { buildChartRootClasses, resolveColorScheme } from '../_base/utils';
import type { ColorSchemeName } from '../_base/types';
import type { GeoColorScale } from './Geo.types';

export function buildGeoClasses(className: string | undefined, unstyled: boolean | undefined): string {
    return buildChartRootClasses(GEO_ROOT_CLASS, className, unstyled);
}

/**
 * Build a sequential color scale function that maps a value within [min, max]
 * to a color interpolated between the first and last colors of the resolved palette.
 * Returns a function: (value: number) => string (hex/rgb color).
 */
export function buildGeoColorScale(
    min: number,
    max: number,
    colorScheme: ColorSchemeName | readonly string[] | undefined,
    scale: GeoColorScale = 'linear',
    values: readonly number[] = [],
): (value: number) => string {
    const palette = resolveColorScheme(colorScheme);
    const lightColor = palette[0];
    // a 2-color list is used as is (from → to); a palette goes from its first to its next-to-last color
    const darkColor = palette.length === 2
        ? palette[1]
        : palette[Math.min(palette.length - 1, palette.length > 2 ? palette.length - 2 : palette.length - 1)];
    return (value: number) => interpolateColor(lightColor, darkColor, scalePosition(value, min, max, scale, values));
}

/** Position 0..1 of `value` on the color scale (0022 M4.5.5: linear, by rank or logarithmic). */
export function scalePosition(value: number, min: number, max: number, scale: GeoColorScale,
                              values: readonly number[]): number {
    const clamp = (t: number) => (Number.isFinite(t) ? Math.max(0, Math.min(1, t)) : 0);
    if (scale === 'quantile' && values.length > 1) {
        const sorted = [...values].sort((a, b) => a - b);
        const below = sorted.filter((v) => v < value).length;
        const equal = sorted.filter((v) => v === value).length;
        return clamp((below + (equal - 1) / 2) / (sorted.length - 1));
    }
    if (scale === 'log') {
        const shift = min <= 0 ? 1 - min : 0;   // log needs positive values
        const lo = Math.log(min + shift), hi = Math.log(max + shift);
        return clamp((Math.log(value + shift) - lo) / (hi - lo || 1));
    }
    return clamp((value - min) / (max - min || 1));
}

/**
 * Linearly interpolate between two CSS colors (hex or rgb).
 * Falls back to `to` if parsing fails.
 */
function interpolateColor(from: string, to: string, t: number): string {
    const c1 = parseColor(from);
    const c2 = parseColor(to);
    if (!c1 || !c2) return to;
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * t);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * t);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * t);
    return `rgb(${r},${g},${b})`;
}

function parseColor(color: string): [number, number, number] | null {
    // Hex: #rgb or #rrggbb
    const hexMatch = color.match(/^#([0-9a-f]{3,8})$/i);
    if (hexMatch) {
        const hex = hexMatch[1];
        if (hex.length === 3) {
            return [
                parseInt(hex[0] + hex[0], 16),
                parseInt(hex[1] + hex[1], 16),
                parseInt(hex[2] + hex[2], 16),
            ];
        }
        if (hex.length >= 6) {
            return [
                parseInt(hex.slice(0, 2), 16),
                parseInt(hex.slice(2, 4), 16),
                parseInt(hex.slice(4, 6), 16),
            ];
        }
    }
    // rgb(r,g,b)
    const rgbMatch = color.match(/^rgb\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/);
    if (rgbMatch) {
        return [Number(rgbMatch[1]), Number(rgbMatch[2]), Number(rgbMatch[3])];
    }
    return null;
}

export function buildTooltipContent(datum: GeoFeatureDatum): string {
    const name = datum.label ?? datum.id;
    return `${name}: ${datum.value.toLocaleString()}`;
}

/**
 * 0022 PB11 (w3f-data-analysis): radio y color de cada punto. El área es proporcional al valor (radio ∝ √valor),
 * el mayor mide `maxRadius`; un punto nunca baja de 2 px. Con grupos, el color del grupo en la paleta.
 */
export function geoPointStyle(points: readonly { value: number; group?: string }[], groups: readonly string[],
                              palette: readonly string[], maxRadius: number, color?: string): { r: number; fill: string }[] {
    const top = Math.max(0, ...points.map((p) => Math.abs(Number(p.value) || 0)));
    return points.map((p) => {
        const v = Math.abs(Number(p.value) || 0);
        const r = top > 0 ? Math.max(2, maxRadius * Math.sqrt(v / top)) : Math.max(2, maxRadius / 3);
        const gi = p.group != null ? groups.indexOf(p.group) : -1;
        const fill = gi >= 0 ? palette[gi % palette.length] : (color || palette[0]);
        return { r, fill };
    });
}
