'use client'

import React, { useMemo } from 'react';
import { Group } from '@visx/group';
import type { WaterfallInnerProps } from './Waterfall.types';
import { WATERFALL_DEFAULTS } from './Waterfall.constants';
import { buildWaterfallClasses, buildTooltipContent, formatTick } from './Waterfall.utils';
import {
    useWaterfallBars,
    useWaterfallScales,
    useWaterfallInteraction,
    useInnerDims,
} from './Waterfall.hooks';
import { adaptScale, plotLeft, plotTop, xAxisLayout, yAxisLayout } from '../_base/axisLayout';   // 0026 X7
import { ChartAxis } from '../primitives/ChartAxis';
import { ChartGrid } from '../primitives/ChartGrid';
import { ChartReferenceLines, waterfallPoints } from '../primitives/ChartReferenceLines';
import { ChartSecondaryAxes } from '../primitives/ChartSecondaryAxes';   // VX9
import { ChartTooltip } from '../primitives/ChartTooltip';
import { BASE_CHART_CLASSES } from '../_base/constants';
import { ChartHeader } from '../_base/ChartHeader';
import { ChartMarkDecorLayer } from '../primitives/ChartMarkDecor';   // VX3

export const WaterfallInner: React.FC<WaterfallInnerProps> = (props) => {
    const {
        data,
        width,
        height,
        margin,
        className,
        unstyled = WATERFALL_DEFAULTS.unstyled,
        bindId,
        ariaLabel,
        description, title, subtitle,
        showXAxis = WATERFALL_DEFAULTS.showXAxis,
        showYAxis = WATERFALL_DEFAULTS.showYAxis,
        showGrid = WATERFALL_DEFAULTS.showGrid,
        showTooltip = WATERFALL_DEFAULTS.showTooltip,
        showLabels = WATERFALL_DEFAULTS.showLabels,
        labelSize = 10,   // 0022 B53.6
        showConnectors = WATERFALL_DEFAULTS.showConnectors,
        positiveColor = WATERFALL_DEFAULTS.positiveColor,
        negativeColor = WATERFALL_DEFAULTS.negativeColor,
        totalColor = WATERFALL_DEFAULTS.totalColor,
        formatY,
        onHover,
        onSelect,
        highlightIndex = null,
    } = props;

    const bars = useWaterfallBars(data);
    const dims = useInnerDims(width, height, margin, props);
    const { xScale: xScaleRaw, yScale: yScaleRaw } = useWaterfallScales(bars, data, dims.innerWidth, dims.innerHeight);
    const xScale = adaptScale(xScaleRaw, props, 'x');   // VX1: mínimo / máximo, log, al revés…
    const yScale = adaptScale(yScaleRaw, props, 'y');   // VX1: mínimo / máximo, log, al revés…
    const { hoveredIndex, handleEnter, handleLeave, handleClick } = useWaterfallInteraction(onHover, onSelect);

    const classes = useMemo(() => buildWaterfallClasses(className, unstyled), [className, unstyled]);
    const yTickFormat = formatY ?? formatTick;

    if (data.length === 0) {
        return (
            <div className={classes}>
                <svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Empty waterfall chart'} />
            </div>
        );
    }

    const bandwidth = xScale.bandwidth();

    return (
        <div className={classes} data-bind-id={bindId}>
            <ChartHeader title={title} subtitle={subtitle} />
            <div className={BASE_CHART_CLASSES.container} style={{ position: 'relative' }}>
                <svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Waterfall chart'}>
                    {description && <desc>{description}</desc>}
                    <Group top={plotTop(dims, props)} left={plotLeft(dims, props)}>
                        {showGrid && (
                            <ChartGrid
                                xScale={xScale}
                                yScale={yScale}
                                width={dims.innerWidth}
                                height={dims.innerHeight}
                                axis="y"
                            />
                        )}

                        {bars.map((bar, i) => {
                            const x = xScale(bar.datum.label) ?? 0;
                            const ya = yScale(bar.y0) ?? 0, yb = yScale(bar.y1) ?? 0;   // VX3: también con el eje al revés
                            const yTop = Math.min(ya, yb);
                            const yBot = Math.max(ya, yb);
                            const barHeight = Math.max(yBot - yTop, 1);
                            const fill = bar.datum.isTotal
                                ? totalColor
                                : bar.datum.value >= 0
                                    ? positiveColor
                                    : negativeColor;

                            return (
                                <g key={i}>
                                    {/* Connector line from previous bar */}
                                    {showConnectors && i > 0 && !bar.datum.isTotal && (
                                        <line
                                            x1={xScale(bars[i - 1].datum.label)! + bandwidth}
                                            y1={yScale(bar.y0) ?? 0}
                                            x2={x}
                                            y2={yScale(bar.y0) ?? 0}
                                            stroke="var(--w3f-chart-connector-color, #94a3b8)"
                                            strokeWidth={1}
                                            strokeDasharray="3,3"
                                        />
                                    )}
                                    <rect
                                        className="visx-bar"
                                        x={x}
                                        y={yTop}
                                        width={bandwidth}
                                        height={barHeight}
                                        fill={fill}
                                        opacity={
                                            highlightIndex != null
                                                ? (highlightIndex === i ? 1 : 0.3)
                                                : hoveredIndex != null && hoveredIndex !== i ? 0.4 : 0.85
                                        }
                                        stroke={highlightIndex === i ? 'var(--w3f-chart-mark-outline, #fff)' : undefined}
                                        strokeWidth={highlightIndex === i ? 2 : undefined}
                                        rx={2}
                                        onMouseEnter={() => handleEnter(bar.datum, i)}
                                        onMouseLeave={handleLeave}
                                        onClick={onSelect ? () => handleClick(bar.datum, i) : undefined}
                                        style={{ cursor: highlightIndex === i ? 'pointer' : onSelect ? 'pointer' : 'default', transition: 'opacity 120ms ease-out' }}
                                    />
                                    {showLabels && (
                                        <text
                                            x={x + bandwidth / 2}
                                            y={yTop - 4}
                                            textAnchor="middle"
                                            fontSize={labelSize}
                                            fill="currentColor"
                                            className="w3f-chart-value-label"
                                            pointerEvents="none"
                                        >
                                            {bar.datum.isTotal
                                                ? bar.cumulative.toLocaleString()
                                                : `${bar.datum.value >= 0 ? '+' : ''}${bar.datum.value.toLocaleString()}`}
                                        </text>
                                    )}
                                </g>
                            );
                        })}

                        {showXAxis && (
                            <ChartAxis scale={xScale} {...xAxisLayout(dims, props)} />
                        )}
                        {showYAxis && (
                            <ChartAxis scale={yScale} {...yAxisLayout(dims, props)} tickFormat={yTickFormat} />
                        )}
                        <ChartSecondaryAxes {...props} xScale={xScale} yScale={yScale} width={dims.innerWidth} height={dims.innerHeight} />
                        <ChartReferenceLines lines={props.referenceLines} bands={props.referenceBands} annotation={props.annotation}
                            points={waterfallPoints(data)} xScale={xScale}
                            yScale={(v: number) => yScale(v)} width={dims.innerWidth} height={dims.innerHeight} />
                    </Group>
                    <ChartMarkDecorLayer {...props} />   {/* VX3: trama, hueco, borde de dos colores */}
                </svg>

                {showTooltip && hoveredIndex != null && bars[hoveredIndex] && (
                    <ChartTooltip
                        left={(xScale(bars[hoveredIndex].datum.label) ?? 0) + bandwidth / 2 + plotLeft(dims, props)}
                        top={(yScale(Math.max(bars[hoveredIndex].y0, bars[hoveredIndex].y1)) ?? 0) + plotTop(dims, props)}
                        visible
                        offsetY={-16}
                    >
                        {buildTooltipContent(bars[hoveredIndex])}
                    </ChartTooltip>
                )}
            </div>
        </div>
    );
};

WaterfallInner.displayName = 'WaterfallInner';
export default WaterfallInner;
