'use client'

import React, { useMemo } from 'react';
import { Group } from '@visx/group';
import { Bar as VisxBar } from '@visx/shape';
import type { BarStackedHInnerProps } from './BarStackedHorizontal.types';
import { BAR_SH_DEFAULTS } from './BarStackedHorizontal.constants';
import { buildBarSHClasses, formatTick } from './BarStackedHorizontal.utils';
import { useBarSHAccessors, useBarSHScales, useStackHData, useBarSHColors, useBarSHInteraction, useInnerDims } from './BarStackedHorizontal.hooks';
import { adaptScale, plotLeft, plotTop, xAxisLayout, yAxisLayout } from '../_base/axisLayout';   // 0026 X7
import { ChartAxis } from '../primitives/ChartAxis';
import { ChartGrid } from '../primitives/ChartGrid';
import { ChartTooltip } from '../primitives/ChartTooltip';
import { ChartSegmentLabel, segmentText, barOpacity } from '../primitives/ChartSegmentLabel';   // FL15
import { ChartLegend } from '../primitives/ChartLegend';
import { BASE_CHART_CLASSES } from '../_base/constants';
import { ChartHeader } from '../_base/ChartHeader';
import { ChartMarkDecorLayer } from '../primitives/ChartMarkDecor';   // VX3

export const BarStackedHorizontalInner: React.FC<BarStackedHInnerProps> = (props) => {
    const {
        data, width, height, margin, className, keys,
        unstyled = BAR_SH_DEFAULTS.unstyled, bindId, ariaLabel, description, colorScheme,
        title, subtitle,
        titleSize, titleColor, subtitleSize, subtitleColor,
        titleAlign, subtitleAlign,
        titleBold, titleItalic, titleUnderline,
        subtitleBold, subtitleItalic, subtitleUnderline,
        getLabel: gL,
        showXAxis = BAR_SH_DEFAULTS.showXAxis, showYAxis = BAR_SH_DEFAULTS.showYAxis,
        showGrid = BAR_SH_DEFAULTS.showGrid, showTooltip = BAR_SH_DEFAULTS.showTooltip,
        showLegend = BAR_SH_DEFAULTS.showLegend,
        padding = BAR_SH_DEFAULTS.padding, barRadius = BAR_SH_DEFAULTS.barRadius,
        formatX, highlightIndex = null, highlightKey = null, onHover, onSelect,
        axisFontSize,
        segmentLabels = 'none', segmentLabelMin = 4, segmentLabelDecimals = 1, segmentLabelSize,   // FL15
        mutedBars, mutedOpacity = 0.45,
    } = props;

    const { getLabel } = useBarSHAccessors(gL);
    const dims = useInnerDims(width, height, margin, props);
    const { xScale: xScaleRaw, yScale: yScaleRaw } = useBarSHScales(data, keys, dims.innerWidth, dims.innerHeight, getLabel, padding);
    const xScale = adaptScale(xScaleRaw, props, 'x');   // VX1: mínimo / máximo, log, al revés…
    const yScale = adaptScale(yScaleRaw, props, 'y');   // VX1: mínimo / máximo, log, al revés…
    const stackRows = useStackHData(data, keys, getLabel);
    const colorMap = useBarSHColors(keys, colorScheme);
    const { hovered, handleEnter, handleLeave, handleClick } = useBarSHInteraction(onHover, onSelect);
    const classes = useMemo(() => buildBarSHClasses(className, unstyled), [className, unstyled]);
    const xTickFormat = formatX ?? formatTick;

    const legendItems = useMemo(() => keys.map((k) => ({ id: k, label: k, color: colorMap[k] })), [keys, colorMap]);

    if (data.length === 0) {
        return (<div className={classes}><svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Empty stacked horizontal bar chart'} /></div>);
    }

    return (
        <div className={classes} data-bind-id={bindId}>
            <ChartHeader
                title={title} subtitle={subtitle}
                titleStyle={titleSize || titleColor || titleAlign || titleBold || titleItalic || titleUnderline ? {
                    fontSize: titleSize, color: titleColor, textAlign: titleAlign,
                    fontWeight: titleBold ? 700 : undefined,
                    fontStyle: titleItalic ? 'italic' : undefined,
                    textDecoration: titleUnderline ? 'underline' : undefined,
                } : undefined}
                subtitleStyle={subtitleSize || subtitleColor || subtitleAlign || subtitleBold || subtitleItalic || subtitleUnderline ? {
                    fontSize: subtitleSize, color: subtitleColor, textAlign: subtitleAlign,
                    fontWeight: subtitleBold ? 700 : undefined,
                    fontStyle: subtitleItalic ? 'italic' : undefined,
                    textDecoration: subtitleUnderline ? 'underline' : undefined,
                } : undefined}
            />
            {showLegend && <ChartLegend items={legendItems} />}
            <div className={BASE_CHART_CLASSES.container} style={{ position: 'relative' }}>
                <svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Stacked horizontal bar chart'}>
                    {description && <desc>{description}</desc>}
                    <Group top={plotTop(dims, props)} left={plotLeft(dims, props)}>
                        {showGrid && <ChartGrid xScale={xScale} width={dims.innerWidth} height={dims.innerHeight} axis="columns" />}

                        {stackRows.map((row, gi) => {
                            const barY = yScale(row.label) ?? 0;
                            const bh = yScale.bandwidth();
                            return (
                                <Group key={row.label}>
                                    {row.segments.map((seg, ki) => {
                                        const x0 = xScale(seg.x0) ?? 0;
                                        const x1 = xScale(seg.x1) ?? 0;
                                        const barX = Math.min(x0, x1);   // VX3: también con el eje al revés
                                        const barW = Math.abs(x1 - x0);
                                        const isHovered = hovered?.groupIdx === gi && hovered?.keyIdx === ki;
                                        const isHighlightedGroup = highlightIndex === gi;
                                        const isHighlightedBar = isHighlightedGroup && (highlightKey == null || highlightKey === seg.key);
                                        const isDimmed = highlightIndex != null
                                            ? !isHighlightedBar
                                            : hovered != null && !isHovered;
                                        const total = row.segments.reduce((a, s) => a + (s.value || 0), 0);   // FL15
                                        const label = segmentText(seg.value, total, segmentLabels, segmentLabelMin, segmentLabelDecimals);
                                        return (
                                            <React.Fragment key={seg.key}>
                                            <VisxBar
                                                x={barX} y={barY}
                                                width={Math.max(barW, 0)} height={bh}
                                                fill={colorMap[seg.key]}
                                                opacity={(isDimmed ? 0.3 : 1) * barOpacity(String(row.label), mutedBars, mutedOpacity)}
                                                stroke={isHighlightedBar ? 'var(--w3f-chart-mark-outline, #fff)' : undefined}
                                                strokeWidth={isHighlightedBar ? 2 : undefined}
                                                rx={barRadius}
                                                onMouseEnter={() => handleEnter(data[gi], gi, ki)}
                                                onMouseLeave={handleLeave}
                                                onClick={onSelect ? () => handleClick(data[gi], gi, seg.key) : undefined}
                                                style={{ cursor: onSelect ? 'pointer' : undefined, transition: 'opacity 120ms ease-out' }}
                                            />
                                            <ChartSegmentLabel x={barX} y={barY} width={Math.max(barW, 0)} height={bh}
                                                text={label} size={segmentLabelSize ?? axisFontSize ?? 11} fill={colorMap[seg.key]} />
                                            </React.Fragment>
                                        );
                                    })}
                                </Group>
                            );
                        })}

                        {showXAxis && <ChartAxis scale={xScale} {...xAxisLayout(dims, props)} tickFormat={xTickFormat} tickFontSize={axisFontSize} />}
                        {showYAxis && <ChartAxis scale={yScale} {...yAxisLayout(dims, props)} tickFontSize={axisFontSize} />}
                    </Group>
                    <ChartMarkDecorLayer {...props} />   {/* VX3: trama, hueco, borde de dos colores */}
                </svg>

                {showTooltip && hovered != null && (() => {
                    const row = stackRows[hovered.groupIdx];
                    const seg = row.segments[hovered.keyIdx];
                    return (
                        <ChartTooltip
                            left={(xScale(seg.x1) ?? 0) + plotLeft(dims, props)}
                            top={(yScale(row.label) ?? 0) + yScale.bandwidth() / 2 + plotTop(dims, props)}
                            visible offsetX={8}
                        >
                            {`${seg.key}: ${seg.value.toLocaleString()}`}
                        </ChartTooltip>
                    );
                })()}
            </div>
        </div>
    );
};

BarStackedHorizontalInner.displayName = 'BarStackedHorizontalInner';
export default BarStackedHorizontalInner;
