'use client'

import React from 'react';
import { Area } from '@visx/shape';
import { lineDash } from '../ChartLineMarks/ChartLineMarks';

/** VX8: what the error bar of each point measures (matplotlib errorbar yerr / xerr). */
export type ChartErrorKind = 'none' | 'std' | 'sem' | 'ci95' | 'range' | 'col' | 'pct';

/**
 * VX8 (w3f-data-analysis): error bars, as matplotlib errorbar. The data rows bring their own figures (the app's
 * chart engine adds them): `errStd` (standard deviation of the group), `errSem` (standard error), `errCi`
 * (half the 95 % confidence interval), `errMin` / `errMax` (the group's range) and `errCol` (another column).
 */
export interface ChartErrorBarsProps {
    /** Which figure the bars show; 'pct' = a fixed percentage of the value. */
    errorBars?: ChartErrorKind;
    /** For 'pct': the percentage (10 = ±10 %). */
    errorPct?: number;
    /** Half the width of the caps, px (matplotlib capsize; 0 = no caps). */
    errorCapSize?: number;
    /** Thickness of the caps, px (matplotlib capthick). */
    errorCapThick?: number;
    /** Color of the bars (matplotlib ecolor). Default: the text color. */
    errorColor?: string;
    /** Thickness of the bars, px (matplotlib elinewidth). */
    errorLineWidth?: number;
    /** 'solid' | 'dashed' | 'dotted' (matplotlib elinestyle). */
    errorLineStyle?: string;
    /** 'both', or only the part above ('up') or below ('down') the value (matplotlib uplims / lolims). */
    errorSide?: 'both' | 'up' | 'down';
    /** VX9 (matplotlib fill_between y2): a shaded band from low to high of each point (same figures as the bars). */
    errorBand?: ChartErrorKind;
    /** Opacity of the band (0–1). */
    errorBandOpacity?: number;
}

/** The props that turn the error bars on (to pass them through from a chart). */
export const ERROR_BAR_PROPS = ['errorBars', 'errorPct', 'errorCapSize', 'errorCapThick', 'errorColor',
    'errorLineWidth', 'errorLineStyle', 'errorSide', 'errorBand', 'errorBandOpacity'] as const;

/** [low, high] of a point's error bar, in data units; null when the point has no figure for that kind. */
export function errorExtent(d: any, value: number, kind: ChartErrorKind | undefined, pct = 10,
    side: 'both' | 'up' | 'down' = 'both'): [number, number] | null {
    if (!kind || kind === 'none' || !Number.isFinite(value)) return null;
    let lo: number, hi: number;
    if (kind === 'pct') {
        const e = Math.abs(value) * pct / 100;
        lo = value - e; hi = value + e;
    } else if (kind === 'range') {
        lo = Number(d?.errMin); hi = Number(d?.errMax);
    } else {
        const e = Number(d?.[{ std: 'errStd', sem: 'errSem', ci95: 'errCi', col: 'errCol' }[kind]]);
        if (!Number.isFinite(e)) return null;
        lo = value - Math.abs(e); hi = value + Math.abs(e);
    }
    if (!Number.isFinite(lo) || !Number.isFinite(hi)) return null;
    if (side === 'up') lo = value;
    if (side === 'down') hi = value;
    return [lo, hi];
}

/**
 * The value scale widened so the error bars fit (when the user did not fix the axis limits).
 * `scale` is a linear scale (copy / domain / nice).
 */
export function scaleForErrors<S>(scale: S, rows: readonly any[], value: (d: any) => number,
    p: ChartErrorBarsProps & { yMin?: number; yMax?: number; xMin?: number; xMax?: number }, axis: 'x' | 'y'): S {
    const s = scale as any;
    const kind = p.errorBars && p.errorBars !== 'none' ? p.errorBars : p.errorBand;   // VX9: también la banda
    if (!kind || kind === 'none' || !s || typeof s.copy !== 'function' || typeof s.bandwidth === 'function') return scale;
    if ((axis === 'y' ? p.yMax ?? p.yMin : p.xMax ?? p.xMin) != null) return scale;
    const d = s.domain();
    if (typeof d[0] !== 'number') return scale;
    let lo = d[0] as number, hi = d[d.length - 1] as number;
    let grew = false;
    for (const r of rows) {
        const ext = errorExtent(r, value(r), kind, p.errorPct, kind === p.errorBars ? p.errorSide : 'both');
        if (!ext) continue;
        if (ext[1] > hi) { hi = ext[1]; grew = true; }
        if (ext[0] < lo) { lo = ext[0]; grew = true; }
    }
    if (!grew) return scale;
    const out = s.copy().domain([lo, hi]);
    return (typeof out.nice === 'function' ? out.nice() : out) as S;
}

export interface ChartErrorBarsLayerProps extends ChartErrorBarsProps {
    /** One item per point: where it is across the axis (px) and its row and value. */
    items: readonly { at: number; row: any; value: number }[];
    /** The value scale (value → px). */
    valueScale: (v: number) => number | undefined;
    /** true = the values run along X (horizontal bars: matplotlib xerr). */
    horizontal?: boolean;
}

export const ERROR_BAR_CLASS = 'w3f-chart-errorbar';

export const ChartErrorBars: React.FC<ChartErrorBarsLayerProps> = ({
    items, valueScale, horizontal = false, errorBars, errorPct = 10, errorCapSize = 6, errorCapThick,
    errorColor, errorLineWidth = 1.5, errorLineStyle = 'solid', errorSide = 'both',
}) => {
    if (!errorBars || errorBars === 'none') return null;
    const color = errorColor || 'var(--w3f-chart-axis-tick-label-color, #94a3b8)';
    const capW = errorCapThick ?? errorLineWidth;
    const pt = (c: number, v: number): [number, number] => (horizontal ? [v, c] : [c, v]);
    return (
        <g className={`${ERROR_BAR_CLASS}s`} pointerEvents="none">
            {items.map((it, i) => {
                const ext = errorExtent(it.row, it.value, errorBars, errorPct, errorSide);
                if (!ext) return null;
                const a = valueScale(ext[0]), b = valueScale(ext[1]);
                if (a == null || b == null || !Number.isFinite(a) || !Number.isFinite(b)) return null;
                const [x1, y1] = pt(it.at, a);
                const [x2, y2] = pt(it.at, b);
                const cap = (v: number, k: string) => {
                    const [p1x, p1y] = pt(it.at - errorCapSize, v);
                    const [p2x, p2y] = pt(it.at + errorCapSize, v);
                    return <line key={k} x1={p1x} y1={p1y} x2={p2x} y2={p2y} stroke={color} strokeWidth={capW} />;
                };
                return (
                    <g key={i} className={ERROR_BAR_CLASS}>
                        <line x1={x1} y1={y1} x2={x2} y2={y2} stroke={color} strokeWidth={errorLineWidth}
                            {...lineDash(errorLineStyle as any, errorLineWidth)} />
                        {errorCapSize > 0 && errorSide !== 'up' && cap(a, 'lo')}
                        {errorCapSize > 0 && errorSide !== 'down' && cap(b, 'hi')}
                    </g>
                );
            })}
        </g>
    );
};

ChartErrorBars.displayName = 'ChartErrorBars';

/** VX9: the band from low to high of each point (matplotlib fill_between with y2), under the line. */
export const ChartErrorBand: React.FC<ChartErrorBarsProps & {
    items: readonly { at: number; row: any; value: number }[];
    valueScale: (v: number) => number | undefined;
    color: string;
    curve?: any;
}> = ({ items, valueScale, color, curve, errorBand, errorBandOpacity = 0.2, errorPct = 10 }) => {
    if (!errorBand || errorBand === 'none') return null;
    const pts = items.map((it) => ({ at: it.at, ext: errorExtent(it.row, it.value, errorBand, errorPct) }))
        .filter((p): p is { at: number; ext: [number, number] } => !!p.ext);
    if (pts.length < 2) return null;
    return (
        <Area data={pts} x={(p) => p.at} y0={(p) => valueScale(p.ext[0]) ?? 0} y1={(p) => valueScale(p.ext[1]) ?? 0}
            fill={color} fillOpacity={errorBandOpacity} curve={curve} className="w3f-chart-error-band" pointerEvents="none" />
    );
};

ChartErrorBand.displayName = 'ChartErrorBand';

export default ChartErrorBars;
