// Ventanas que no se tapan (windowLayout="avoid", B23 de w3f-data-analysis): cuando una ventana se abre, se suelta
// después de arrastrarla o cambia de tamaño encima de otra, se corre sola al lugar libre más cercano. Al activar la
// opción se acomodan las que ya se tapan: quedan las que no se pueden arrastrar y las primeras; se corren las demás.

import type { LinkRect } from './Desktop.links';
import { relPos } from './Desktop.links';

export type WindowLayoutMode = 'free' | 'avoid';

/** Atributo del canvas del Desktop con el modo ('free' | 'avoid'); cada Window lo lee al abrirse / soltarse. */
export const WINDOW_LAYOUT_ATTR = 'data-window-layout';
/** Evento que el Desktop manda a su canvas al activar 'avoid': cada ventana se acomoda (detail.placed). */
export const SETTLE_EVENT = 'w3f:settle-windows';
/** Evento que una ventana manda a su canvas cuando creció sola (alto automático: llegaron los datos); las que quedaron
 *  tapadas se corren (w3f-data-analysis FL18: antes solo se acomodaba al abrirse, con el alto de antes). */
export const GREW_EVENT = 'w3f:window-grew';
/** Separación mínima entre ventanas. */
export const GAP = 16;

export const overlaps = (a: LinkRect, b: LinkRect, gap: number) =>
    a.left < b.left + b.width + gap && b.left < a.left + a.width + gap
    && a.top < b.top + b.height + gap && b.top < a.top + a.height + gap;

/**
 * Cuánto mover `me` (dx, dy) para que no toque ninguna de `others` (con `gap` de separación), lo menos posible.
 * {0, 0} si ya está libre. Prueba quedarse donde está y las posiciones pegadas a cada lado de cada ventana (y sus
 * esquinas); se queda con la libre más cercana. No sale de x, y ≥ 0. Si ninguna sirve, a la derecha de todas.
 */
export function freeSpot(me: LinkRect, others: LinkRect[], gap = GAP): { dx: number; dy: number } {
    const blockers = others.filter((o) => o.width > 0 && o.height > 0);
    const free = (x: number, y: number) => {
        if (x < 0 || y < 0) return false;
        const r = { left: x, top: y, width: me.width, height: me.height };
        return blockers.every((o) => !overlaps(r, o, gap));
    };
    if (free(me.left, me.top)) return { dx: 0, dy: 0 };

    const xs = new Set<number>([me.left]);
    const ys = new Set<number>([me.top]);
    for (const o of blockers) {
        xs.add(o.left + o.width + gap);      // a la derecha
        xs.add(o.left - me.width - gap);     // a la izquierda
        xs.add(o.left);                      // alineada a la izquierda
        ys.add(o.top + o.height + gap);      // abajo
        ys.add(o.top - me.height - gap);     // arriba
        ys.add(o.top);                       // alineada arriba
    }
    let best: { dx: number; dy: number; d: number } | null = null;
    for (const x of xs) {
        for (const y of ys) {
            if (!free(x, y)) continue;
            const dx = x - me.left, dy = y - me.top;
            const d = Math.hypot(dx, dy);
            if (!best || d < best.d - 0.5) best = { dx, dy, d };
        }
    }
    if (best) return { dx: best.dx, dy: best.dy };
    const right = Math.max(...blockers.map((o) => o.left + o.width)) + gap;
    return { dx: right - me.left, dy: 0 };
}

/** Rectángulos (en el canvas) de las ventanas visibles del canvas, menos `except`. */
export function windowRects(canvas: HTMLElement, except?: Element | null): LinkRect[] {
    return (Array.from(canvas.querySelectorAll('.w3f-window')) as HTMLElement[])
        .filter((w) => w !== except && w.offsetWidth > 0 && w.offsetHeight > 0)
        .map((w) => relPos(w, canvas));
}

/** El canvas del Desktop con la opción activada que contiene a `el`, o null. */
export function avoidCanvas(el: Element | null): HTMLElement | null {
    const canvas = el?.closest(`[${WINDOW_LAYOUT_ATTR}]`) as HTMLElement | null;
    return canvas && canvas.getAttribute(WINDOW_LAYOUT_ATTR) === 'avoid' ? canvas : null;
}
