import { useEffect, type MutableRefObject, type RefObject } from 'react';
import { routeOrthogonal } from './Desktop.route';

// Líneas rotuladas entre ventanas de todo el Desktop (aunque estén en distintos WindowGroup).
// La ventana de destino lleva data-links='[{"id","label","color"}]' (prop `links` de Window) y cada origen
// data-link-id (prop `linkId`). Se dibujan en un SVG del canvas, debajo de las ventanas.
// Con `draggable: true`, el punto del origen (con su rótulo) se arrastra hasta otra ventana: el Desktop avisa
// onLinkChange({target, index, label, from, to}) y la app decide (useLinkDrag).

/** Forma de las líneas: curva directa (pasa por debajo de las ventanas) o en ángulo recto rodeándolas. */
export type LinkRouting = 'curve' | 'orthogonal';

export interface DesktopLink { id: string; label?: string; color?: string; draggable?: boolean; }
export interface LinkChange {
    target: string;   // data-link-id de la ventana que tiene la línea en `links`
    index: number;    // posición de la línea en `links`
    label: string;
    from: string;     // origen actual
    to: string;       // ventana (data-link-id) donde se soltó
}
export interface LinkRect { left: number; top: number; width: number; height: number; }
export interface LinkGeometry {
    d: string; x1: number; y1: number; x2: number; y2: number;
    sx: number; sy: number; tx: number; ty: number;   // rótulos: cerca de cada punta, del lado de afuera
}

export const LINK_DEFAULT_COLOR = '#f59e0b';
const SVG_NS = 'http://www.w3.org/2000/svg';
const CTRL = 90;          // largo de los tiradores de la curva
const SPREAD = 26;        // separación entre las líneas que llegan a la misma ventana
const BADGE = 0.28;       // los rótulos van a ese tramo del tirador de cada punta (afuera de la ventana)

/** Lee data-links; lo que no sea una lista de {id} se ignora. */
export function parseLinks(attr: string | null | undefined): DesktopLink[] {
    if (!attr) return [];
    try {
        const v = JSON.parse(attr);
        return Array.isArray(v) ? v.filter((l) => l && typeof l.id === 'string' && l.id) : [];
    } catch {
        return [];
    }
}

/** Posición en píxeles de layout relativa a `ancestor` (sin el zoom del canvas, como en WindowGroup). */
export function relPos(el: HTMLElement, ancestor: HTMLElement): LinkRect {
    let left = 0, top = 0;
    let cur: HTMLElement | null = el;
    while (cur && cur !== ancestor) {
        left += cur.offsetLeft;
        top  += cur.offsetTop;
        cur   = cur.offsetParent as HTMLElement | null;
    }
    return { left, top, width: el.offsetWidth, height: el.offsetHeight };
}

/**
 * Curva de `s` a `t` (bordes enfrentados). `offset` corre las dos puntas a lo largo del borde, para que las
 * líneas que llegan a la misma ventana (o salen dos veces de la misma, A = B) no se encimen.
 */
export function linkPath(s: LinkRect, t: LinkRect, offset = 0): LinkGeometry {
    const sCx = s.left + s.width / 2, sCy = s.top + s.height / 2;
    const tCx = t.left + t.width / 2, tCy = t.top + t.height / 2;
    const dx = tCx - sCx, dy = tCy - sCy;
    let x1: number, y1: number, x2: number, y2: number, c1x: number, c1y: number, c2x: number, c2y: number;
    if (Math.abs(dx) >= Math.abs(dy) || (dx === 0 && dy === 0)) {
        const dir = dx >= 0 ? 1 : -1;
        x1 = dir > 0 ? s.left + s.width : s.left;  y1 = sCy + offset;
        x2 = dir > 0 ? t.left : t.left + t.width;  y2 = tCy + offset;
        c1x = x1 + dir * CTRL; c1y = y1; c2x = x2 - dir * CTRL; c2y = y2;
    } else {
        const dir = dy >= 0 ? 1 : -1;
        x1 = sCx + offset; y1 = dir > 0 ? s.top + s.height : s.top;
        x2 = tCx + offset; y2 = dir > 0 ? t.top : t.top + t.height;
        c1x = x1; c1y = y1 + dir * CTRL; c2x = x2; c2y = y2 - dir * CTRL;
    }
    return {
        d: `M ${x1} ${y1} C ${c1x} ${c1y} ${c2x} ${c2y} ${x2} ${y2}`,
        x1, y1, x2, y2,
        sx: x1 + (c1x - x1) * BADGE, sy: y1 + (c1y - y1) * BADGE,
        tx: x2 + (c2x - x2) * BADGE, ty: y2 + (c2y - y2) * BADGE,
    };
}

const attrEsc = (v: string) => v.replace(/["\\]/g, '\\$&');

// Recorridos en ángulo recto ya calculados, por canvas y por línea: se rehacen solo si algo se movió
const routeCache = new WeakMap<HTMLElement, Map<string, { sig: string; geo: LinkGeometry }>>();

/** Atributo del canvas con el `linkRouting` del Desktop: lo leen también las líneas propias de WindowGroup. */
export const LINK_ROUTING_ATTR = 'data-link-routing';

/** Ventanas visibles del canvas (obstáculos del recorrido en ángulo recto) y una firma de sus posiciones. */
export function obstaclesOf(canvas: HTMLElement): { rects: LinkRect[]; sig: string } {
    const rects = (Array.from(canvas.querySelectorAll('.w3f-window')) as HTMLElement[])
        .filter((w) => w.offsetWidth > 0 && w.offsetHeight > 0)
        .map((w) => relPos(w, canvas));
    return { rects, sig: rects.map((r) => `${r.left},${r.top},${r.width},${r.height}`).join(';') };
}

function svgEl(tag: string, attrs: Record<string, string>): SVGElement {
    const el = document.createElementNS(SVG_NS, tag);
    for (const [k, v] of Object.entries(attrs)) el.setAttribute(k, v);
    return el;
}

function makeLine(key: string): SVGGElement {
    const g = svgEl('g', { 'data-link': key }) as SVGGElement;
    g.appendChild(svgEl('path', { fill: 'none', 'stroke-width': '2.5', opacity: '0.8' }));
    return g;
}

/** Puntos y rótulos de las dos puntas: van en la capa de arriba (no los tapan las ventanas). */
function makeBadges(key: string): SVGGElement {
    const g = svgEl('g', { 'data-link': key }) as SVGGElement;
    for (const role of ['src', 'dst']) {
        g.appendChild(svgEl('circle', { r: '5', 'data-role': role }));
        g.appendChild(svgEl('rect', { rx: '4', height: '18', 'data-role': `${role}-box` }));
        g.appendChild(svgEl('text', {
            fill: '#0f172a', 'font-size': '12', 'font-weight': '700', 'font-family': 'system-ui, sans-serif',
            'text-anchor': 'middle', 'dominant-baseline': 'central', 'data-role': `${role}-text`,
        }));
    }
    return g;
}

function groupFor(svg: SVGSVGElement, key: string, make: (key: string) => SVGGElement): SVGGElement {
    let g = svg.querySelector(`[data-link="${attrEsc(key)}"]`) as SVGGElement | null;
    if (!g) { g = make(key); svg.appendChild(g); }
    g.style.display = '';
    return g;
}

/**
 * Redibuja todas las líneas del canvas (una pasada): la curva en `svg` (debajo de las ventanas) y los puntos con
 * rótulo en `top` (encima). Exportada para los tests.
 */
export function drawDesktopLinks(canvas: HTMLElement, svg: SVGSVGElement, top: SVGSVGElement = svg,
                                 routing: LinkRouting = 'curve'): void {
    const used = new Set<string>();
    const obstacles = routing === 'orthogonal' ? obstaclesOf(canvas) : null;
    let cache = routeCache.get(canvas);
    if (!cache) { cache = new Map(); routeCache.set(canvas, cache); }
    const targets = Array.from(canvas.querySelectorAll('[data-links]')) as HTMLElement[];
    targets.forEach((target, ti) => {
        const links = parseLinks(target.getAttribute('data-links'));
        const tPos = relPos(target, canvas);
        links.forEach((link, i) => {
            const src = canvas.querySelector(`[data-link-id="${attrEsc(link.id)}"]`) as HTMLElement | null;
            if (!src || src === target) return;
            const key = `${target.getAttribute('data-link-id') || ti}|${i}`;
            const badgeKey = top === svg ? `${key}|b` : key;
            used.add(key); used.add(badgeKey);
            const color = link.color || LINK_DEFAULT_COLOR;
            const label = link.label ?? '';
            const sPos = relPos(src, canvas), offset = (i - (links.length - 1) / 2) * SPREAD;
            let geo: LinkGeometry | null = null;
            if (obstacles) {
                const sig = `${obstacles.sig}|${sPos.left},${sPos.top},${sPos.width},${sPos.height}|`
                    + `${tPos.left},${tPos.top},${tPos.width},${tPos.height}|${offset}`;
                const hit = cache!.get(key);
                if (hit && hit.sig === sig) geo = hit.geo;
                else {
                    geo = routeOrthogonal(sPos, tPos, obstacles.rects, offset);
                    if (geo) cache!.set(key, { sig, geo }); else cache!.delete(key);
                }
            }
            geo = geo ?? linkPath(sPos, tPos, offset);   // sin camino libre (o routing curve): la curva
            const path = groupFor(svg, key, makeLine).querySelector('path')!;
            path.setAttribute('d', geo.d);
            path.setAttribute('stroke', color);
            const badges = groupFor(top, badgeKey, makeBadges);
            badges.setAttribute('data-target', target.getAttribute('data-link-id') ?? '');
            badges.setAttribute('data-index', String(i));
            badges.setAttribute('data-src', link.id);
            badges.setAttribute('data-label', label);
            badges.setAttribute('data-draggable', link.draggable ? '1' : '');
            const w = Math.max(18, 8 * label.length + 8);
            for (const [role, x, y, lx, ly] of [['src', geo.x1, geo.y1, geo.sx, geo.sy],
                                               ['dst', geo.x2, geo.y2, geo.tx, geo.ty]] as const) {
                const dot = badges.querySelector(`[data-role="${role}"]`)!;
                dot.setAttribute('cx', String(x)); dot.setAttribute('cy', String(y)); dot.setAttribute('fill', color);
                const box = badges.querySelector(`[data-role="${role}-box"]`) as SVGElement;
                const text = badges.querySelector(`[data-role="${role}-text"]`) as SVGElement;
                box.style.display = text.style.display = label ? '' : 'none';
                box.setAttribute('x', String(lx - w / 2)); box.setAttribute('y', String(ly - 9));
                box.setAttribute('width', String(w)); box.setAttribute('fill', color);
                text.setAttribute('x', String(lx)); text.setAttribute('y', String(ly));
                if (text.textContent !== label) text.textContent = label;
                // el punto del origen y su rótulo se agarran (el resto del SVG no recibe el mouse)
                const grab = role === 'src' && link.draggable;
                for (const el of [dot as SVGElement, box, text]) {
                    el.style.pointerEvents = grab ? 'all' : 'none';
                    el.style.cursor = grab ? 'grab' : '';
                }
            }
        });
    });
    for (const layer of new Set([svg, top])) {
        (Array.from(layer.querySelectorAll('[data-link]')) as SVGGElement[]).forEach((g) => {
            if (!used.has(g.getAttribute('data-link') ?? '')) g.style.display = 'none';
        });
    }
}

/** Un solo bucle de animación por Desktop: sigue a las ventanas mientras se arrastran. */
export function useDesktopLinks(canvasRef: RefObject<HTMLElement | null>, svgRef: RefObject<SVGSVGElement | null>,
                                topRef?: RefObject<SVGSVGElement | null>,
                                routingRef?: RefObject<LinkRouting | undefined>) {
    useEffect(() => {
        let raf = 0;
        const loop = () => {
            if (canvasRef.current && svgRef.current) {
                drawDesktopLinks(canvasRef.current, svgRef.current, topRef?.current ?? svgRef.current,
                                 routingRef?.current ?? 'curve');
            }
            raf = requestAnimationFrame(loop);
        };
        raf = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(raf);
    }, [canvasRef, svgRef, topRef, routingRef]);
}

/** La ventana (data-link-id) más de arriba bajo el punto, salvo las de `exclude`; null si no hay. */
export function linkTargetAt(x: number, y: number, exclude: string[] = []): HTMLElement | null {
    const hits = typeof document.elementsFromPoint === 'function' ? document.elementsFromPoint(x, y) : [];
    for (const el of hits) {
        const win = (el as HTMLElement).closest?.('[data-link-id]') as HTMLElement | null;
        if (win) return exclude.includes(win.getAttribute('data-link-id') ?? '') ? null : win;
    }
    return null;
}

/**
 * Arrastre de las líneas `draggable`: se agarra el punto del origen (o su rótulo), una línea punteada sigue al
 * puntero (con el zoom del canvas) y se resalta la ventana de abajo; al soltar sobre otra ventana con data-link-id
 * se llama a onLinkChange. No mueve nada por su cuenta: la app cambia `links` si corresponde.
 */
export function useLinkDrag(canvasRef: RefObject<HTMLElement | null>, topRef: RefObject<SVGSVGElement | null>,
                            zoomRef: MutableRefObject<number>,
                            onChangeRef: MutableRefObject<((c: LinkChange) => void) | undefined>) {
    useEffect(() => {
        const top = topRef.current;
        if (!top) return;
        const isGrip = (el: EventTarget | null) =>
            !!(el as Element)?.getAttribute?.('data-role')?.startsWith('src') &&
            (el as Element).closest('g[data-link]')?.getAttribute('data-draggable') === '1';
        const toCanvas = (e: PointerEvent) => {
            const r = canvasRef.current!.getBoundingClientRect();
            const z = zoomRef.current || 1;
            return { x: (e.clientX - r.left) / z, y: (e.clientY - r.top) / z };
        };
        const onDown = (e: PointerEvent) => {
            if (!isGrip(e.target) || !canvasRef.current) return;
            e.preventDefault();
            e.stopPropagation();
            const g = (e.target as Element).closest('g[data-link]') as SVGGElement;
            const dst = g.querySelector('[data-role="dst"]')!;
            const x0 = dst.getAttribute('cx'), y0 = dst.getAttribute('cy');
            const color = dst.getAttribute('fill') || LINK_DEFAULT_COLOR;
            const ghost = svgEl('path', { fill: 'none', stroke: color, 'stroke-width': '2.5',
                                          'stroke-dasharray': '6 5', 'data-role': 'drag' });
            top.appendChild(ghost);
            g.style.opacity = '0.35';
            const target = g.getAttribute('data-target') ?? '';
            const from = g.getAttribute('data-src') ?? '';
            let over: HTMLElement | null = null;
            let outline = '';
            const mark = (win: HTMLElement | null) => {
                if (win === over) return;
                if (over) over.style.outline = outline;
                over = win;
                if (over) { outline = over.style.outline; over.style.outline = `2px dashed ${color}`; }
            };
            const onMove = (ev: PointerEvent) => {
                const p = toCanvas(ev);
                ghost.setAttribute('d', `M ${x0} ${y0} L ${p.x} ${p.y}`);
                mark(linkTargetAt(ev.clientX, ev.clientY, [target]));
            };
            const onUp = (ev: PointerEvent) => {
                window.removeEventListener('pointermove', onMove);
                window.removeEventListener('pointerup', onUp);
                const win = linkTargetAt(ev.clientX, ev.clientY, [target]);
                mark(null);
                ghost.remove();
                g.style.opacity = '';
                const to = win?.getAttribute('data-link-id') ?? '';
                if (to && to !== from) {
                    onChangeRef.current?.({ target, index: Number(g.getAttribute('data-index')) || 0,
                                            label: g.getAttribute('data-label') ?? '', from, to });
                }
            };
            window.addEventListener('pointermove', onMove);
            window.addEventListener('pointerup', onUp);
        };
        // que el clic en el punto no empiece a desplazar el escritorio (pan con mousedown en el fondo)
        const onMouseDown = (e: MouseEvent) => { if (isGrip(e.target)) e.stopPropagation(); };
        top.addEventListener('pointerdown', onDown);
        top.addEventListener('mousedown', onMouseDown);
        return () => {
            top.removeEventListener('pointerdown', onDown);
            top.removeEventListener('mousedown', onMouseDown);
        };
    }, [canvasRef, topRef, zoomRef, onChangeRef]);
}
