'use client'

import React from 'react';
import { AxisBottom, AxisLeft, AxisRight, AxisTop } from '@visx/axis';
import type { ChartAxisProps } from './ChartAxis.types';
import { CHART_AXIS_DEFAULTS } from './ChartAxis.constants';
import { buildAxisClasses } from './ChartAxis.utils';
import { useTickFormat } from './ChartAxis.hooks';
import { wrapWords } from '../../_base/axisLayout';   // VX5

/**
 * W3F ChartAxis — thin primitive wrapper around `@visx/axis`.
 *
 * - Picks the correct axis component based on `orientation`.
 * - Applies W3F theming via CSS variables (no hardcoded colors).
 * - Forwards tick count, format, and label props.
 */
export const ChartAxis: React.FC<ChartAxisProps> = (props) => {
    const {
        scale,
        orientation,
        top,
        left,
        numTicks = CHART_AXIS_DEFAULTS.numTicks,
        tickFormat,
        label,
        labelOffset = CHART_AXIS_DEFAULTS.labelOffset,
        hideAxisLine = CHART_AXIS_DEFAULTS.hideAxisLine,
        hideTicks = CHART_AXIS_DEFAULTS.hideTicks,
        hideTickLabels = CHART_AXIS_DEFAULTS.hideTickLabels,
        tickRotate = 0,
        tickFontSize = 11,
        className,
        tickLength = 8,
        tickWidth,
        tickDirection = 'out',
        tickPad = 0,
        mirrorOffset,
        frame,
        wrapLabels,
    } = props;

    const format = useTickFormat(tickFormat);
    const rootClass = buildAxisClasses(orientation, className);

    const commonProps = {
        scale,
        top,
        left,
        numTicks,
        tickFormat: format,
        label,
        labelOffset,
        hideAxisLine,
        // VX1: hacia adentro, las rayitas las dibuja manualTicks (visx solo las pone hacia afuera)
        hideTicks: hideTicks || tickDirection === 'in',
        tickLength,
        tickLineProps: tickWidth != null ? { strokeWidth: tickWidth } : undefined,
        hideZero: false,
        stroke: 'var(--w3f-chart-axis-stroke)',
        tickStroke: 'var(--w3f-chart-axis-tick-stroke)',
        tickLabelProps: () => ({
            fill: 'var(--w3f-chart-axis-tick-label-color)',
            fontSize: tickFontSize,
            fontFamily: 'var(--w3f-chart-axis-font, inherit)',   // 0022 B46: letra de los ejes
            textAnchor:
                tickRotate !== 0 && (orientation === 'bottom' || orientation === 'top')
                    ? ('end' as const)
                    : orientation === 'left'
                      ? ('end' as const)
                      : orientation === 'right'
                        ? ('start' as const)
                        : ('middle' as const),
            dy: tickPad && (orientation === 'top' || orientation === 'bottom')
                ? (orientation === 'top' ? -1 : 1) * (0.25 * tickFontSize + tickPad)
                : orientation === 'top' ? '-0.25em' : '0.25em',
            dx: tickPad && (orientation === 'left' || orientation === 'right')
                ? (orientation === 'left' ? -tickPad : tickPad) : undefined,
            angle: tickRotate,
        }),
        labelProps: {
            fill: 'var(--w3f-chart-axis-label-color)',
            fontSize: 12,
            fontWeight: 500,
            textAnchor: 'middle' as const,
        },
    };

    const AxisComponent =
        orientation === 'top'
            ? AxisTop
            : orientation === 'right'
              ? AxisRight
              : orientation === 'bottom'
                ? AxisBottom
                : AxisLeft;

    // Hide tick labels by rendering an empty string.
    const finalTickFormat = hideTickLabels ? () => '' : format;

    // VX1: rayitas propias (hacia adentro y / o del otro lado del dibujo) en las posiciones de las marcas
    const horizontal = orientation === 'top' || orientation === 'bottom';
    const sc = scale as unknown as { ticks?: (n: number) => unknown[]; domain: () => unknown[]; bandwidth?: () => number };
    const tickValues = (hideTicks || (tickDirection !== 'in' && mirrorOffset == null)) ? []
        : (typeof sc.ticks === 'function' ? sc.ticks(numTicks) : sc.domain());
    const half = typeof sc.bandwidth === 'function' ? sc.bandwidth() / 2 : 0;
    const pos = (v: unknown) => ((scale as unknown as (x: unknown) => number)(v) ?? 0) + half;
    // hacia adentro del dibujo: abajo → arriba, arriba → abajo, izquierda → derecha, derecha → izquierda
    const inward = orientation === 'bottom' || orientation === 'right' ? -1 : 1;
    const base = { x: left ?? 0, y: top ?? 0 };
    const tick = (v: unknown, k: number, offset: number, sign: number) => {
        const p0 = pos(v);
        const len = tickLength * sign;
        return horizontal
            ? <line key={k} x1={base.x + p0} x2={base.x + p0} y1={base.y + offset} y2={base.y + offset + len} />
            : <line key={k} x1={base.x + offset} x2={base.x + offset + len} y1={base.y + p0} y2={base.y + p0} />;
    };
    const ownTicks = tickValues.length ? (
        <g className="w3f-chart-axis__ticks" stroke="var(--w3f-chart-axis-tick-stroke)" strokeWidth={tickWidth ?? 1}>
            {tickDirection === 'in' && tickValues.map((v, k) => tick(v, k, 0, inward))}
            {mirrorOffset != null && tickValues.map((v, k) =>
                tick(v, 1000 + k, mirrorOffset, tickDirection === 'in' ? -inward : inward))}
        </g>
    ) : null;

    // VX5 (Text.wrap): cada rótulo en renglones del ancho de su categoría (o del espacio entre marcas)
    const isHorizontal = orientation === 'top' || orientation === 'bottom';
    const sc2 = scale as unknown as { bandwidth?: () => number; range: () => number[] };
    const slot = typeof sc2.bandwidth === 'function' ? sc2.bandwidth()
        : Math.abs((sc2.range()[1] ?? 0) - (sc2.range()[0] ?? 0)) / Math.max(1, numTicks);
    const wrapTick = wrapLabels && isHorizontal && !tickRotate && !hideTickLabels
        ? ({ x, y, formattedValue, ...rest }: { x: number; y: number; formattedValue?: string }) => {
            const lines = wrapWords(formattedValue ?? '', Math.max(slot - 4, 20), tickFontSize);
            const up = orientation === 'top' ? -(lines.length - 1) * tickFontSize * 1.1 : 0;
            return (
                <text x={x} y={y + up} {...(rest as React.SVGProps<SVGTextElement>)} className="w3f-chart-axis__wrapped">
                    {lines.map((l, k) => <tspan key={k} x={x} dy={k === 0 ? 0 : tickFontSize * 1.1}>{l}</tspan>)}
                </text>
            );
        }
        : undefined;

    return (
        <g className={rootClass}>
            {frame && (
                <rect className="w3f-chart-axis__frame" x={0} y={0} width={frame.width} height={frame.height}
                    fill="none" stroke="var(--w3f-chart-axis-stroke)" />
            )}
            <AxisComponent {...commonProps} tickFormat={finalTickFormat} {...(wrapTick ? { tickComponent: wrapTick } : {})} />
            {ownTicks}
        </g>
    );
};

ChartAxis.displayName = 'ChartAxis';

export default ChartAxis;
