import type { TableVariant, TableSize, TableColor, TableNumberFormat, TableHeaderGroupCell } from './Table.types';
import { TABLE_COLORS, TABLE_SIZES, TABLE_VARIANTS } from './Table.constants';

/**
 * Construye las clases CSS del contenedor de la tabla.
 */
export const buildContainerClasses = (className?: string, unstyled?: boolean): string => {
    return ['w3f-table-container', unstyled && 'w3f-table--unstyled', className].filter(Boolean).join(' ');
};

/**
 * Construye las clases CSS del elemento table.
 */
export const buildTableClasses = (
    size: TableSize,
    variant: TableVariant,
    color: TableColor,
    enableColumnResize: boolean,
    unstyled?: boolean
): string => {
    if (unstyled) {
        return 'w3f-table w3f-table--unstyled';
    }
    return [
        'w3f-table',
        TABLE_SIZES[size] || '',
        TABLE_VARIANTS[variant] || '',
        TABLE_COLORS[color] || '',
        enableColumnResize ? 'w3f-table-fixed' : '',
    ].filter(Boolean).join(' ');
};

const formatters = new Map<string, Intl.NumberFormat>();

/**
 * Texto de un número con el formato de la columna. Devuelve null si no corresponde (sin formato o
 * el valor no es un número finito): la celda muestra el valor tal cual.
 */
export const formatNumber = (
    value: unknown,
    format?: TableNumberFormat,
    decimals?: number,
    locale = 'es-AR'
): string | null => {
    if (!format || typeof value !== 'number' || !Number.isFinite(value)) return null;
    const digits = decimals ?? (format === 'percent' ? 1 : 2);
    const key = `${locale}|${format}|${digits}`;
    let fmt = formatters.get(key);
    if (!fmt) {
        fmt = new Intl.NumberFormat(locale, {
            style: format === 'percent' ? 'percent' : 'decimal',
            minimumFractionDigits: digits,
            maximumFractionDigits: digits,
            // 0027 (w3f-data-analysis): sin «-0» (un −0 de los datos, o −0,004 redondeado a 0): signo solo si es < 0
            signDisplay: 'negative',
        } as Intl.NumberFormatOptions);
        formatters.set(key, fmt);
    }
    return fmt.format(value);
};

/**
 * 0026 X14: las filas de grupos de la cabecera (una por nivel), arriba de la de encabezados. En cada nivel se juntan
 * las columnas seguidas con el mismo camino hasta ese nivel; las que no tienen ese nivel van en celdas vacías
 * (también juntas). Sin grupos, ninguna fila.
 */
export const headerGroupRows = (columns: { accessorKey: string; groups?: string[] }[]): TableHeaderGroupCell[][] => {
    const depth = columns.reduce((m, c) => Math.max(m, c.groups?.length ?? 0), 0);
    const rows: TableHeaderGroupCell[][] = [];
    for (let level = 0; level < depth; level++) {
        const row: TableHeaderGroupCell[] = [];
        let prevPath: string | null = null;
        columns.forEach((col) => {
            const g = col.groups ?? [];
            const label = level < g.length ? g[level] : null;
            // el camino hasta este nivel; null = la columna no tiene este nivel (celda vacía)
            const path = label == null ? null : JSON.stringify(g.slice(0, level + 1));
            const last = row[row.length - 1];
            if (last && path === prevPath) last.span += 1;
            else row.push({ key: `${level}:${col.accessorKey}`, label, span: 1 });
            prevPath = path;
        });
        rows.push(row);
    }
    return rows;
};

const isBlank = (v: unknown) => v == null || v === '';

/**
 * 0026 X14: para cada fila y cada columna combinada, cuántas filas abarca su celda: n ≥ 1 = la celda de arriba del
 * bloque (rowSpan n); 0 = tapada por la de arriba. Por jerarquía: la columna k combina solo si las anteriores también
 * son iguales. Los vacíos no se combinan.
 */
export const mergeSpans = (rows: Record<string, unknown>[], keys: string[]): Record<string, number>[] => {
    const out: Record<string, number>[] = rows.map(() => ({}));
    keys.forEach((key, j) => {
        let start = 0;
        for (let i = 1; i <= rows.length; i++) {
            const same = i < rows.length && !isBlank(rows[i][key])
                && keys.slice(0, j + 1).every((k) => String(rows[i][k]) === String(rows[start][k]));
            if (same) {
                out[i][key] = 0;
            } else {
                if (start < rows.length) out[start][key] = i - start;
                start = i;
            }
        }
    });
    return out;
};
