'use client'

/**
 * FormulaEditor — un casillero de fórmulas con colores, autocompletar y marcas (0022 M8.5a de w3f-data-analysis):
 * las [columnas] y las funciones conocidas van en color y las desconocidas marcadas (title con el motivo), los
 * paréntesis sin cerrar o de más se señalan; al escribir «[» se ofrecen las columnas y al escribir letras, las
 * funciones (↑ ↓, Enter / Tab inserta, Esc cierra, Ctrl + espacio abre); debajo, la firma y qué hace la función en
 * la que está el cursor. Es un <textarea> de verdad (controlado) con una capa coloreada detrás: funciona con el
 * `bind=` de w3f-python y con las pruebas en pantalla (fill), y se estira como cualquier casillero.
 *
 * @example
 * <FormulaEditor value={f} onChange={setF} columns={['ventas', 'costo']}
 *                functions={[{ name: 'SUMA', sig: 'SUMA([columna])', doc: 'La suma de la columna en el grupo.' }]} />
 */
import React, { forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState } from 'react';
import type { FormulaCompletion, FormulaCompletionItem, FormulaEditorProps, FormulaFunction, FormulaMode,
    FormulaToken } from './FormulaEditor.types';

const KEYWORDS = new Set(['VAR', 'RETURN', 'DEVOLVER']);
const SQL_KEYWORDS = new Set(['CASE', 'WHEN', 'THEN', 'ELSE', 'END', 'AND', 'OR', 'NOT', 'IN', 'IS', 'NULL', 'DISTINCT',
    'AS', 'LIKE', 'BETWEEN', 'FILTER', 'WHERE', 'OVER', 'PARTITION', 'BY', 'ORDER', 'CAST', 'TRUE', 'FALSE']);
const TOKEN_RE = /\[[^\[\]]*\]?|"[^"]*"?|'[^']*'?|\d+(?:\.\d+)?|[\p{L}_][\p{L}\p{N}_]*|\s+|[()]|<>|<=|>=|==|!=|[+\-*/;,=<>]|./gu;
const WORD_END = /([\p{L}_][\p{L}\p{N}_]*)$/u;
const WORD_CHAR = /[\p{L}\p{N}_]/u;
const COLORS: Record<FormulaToken['type'], string> = {
    column: 'var(--w3f-formula-col, #7ec699)',
    'column-unknown': 'var(--w3f-formula-bad, #f87171)',
    func: 'var(--w3f-formula-func, #6cb6ff)',
    'func-unknown': 'var(--w3f-formula-bad, #f87171)',
    keyword: 'var(--w3f-formula-kw, #c792ea)',
    string: 'var(--w3f-formula-str, #e6a86c)',
    number: 'var(--w3f-formula-num, #d2a8ff)',
    op: 'var(--w3f-formula-op, inherit)',
    paren: 'inherit',
    'paren-bad': 'var(--w3f-formula-bad, #f87171)',
    ident: 'var(--w3f-formula-ident, inherit)',
    ws: 'inherit',
    text: 'inherit',
};

/** El texto en trozos clasificados: [columnas], funciones (las que van seguidas de «(»), palabras clave, textos,
 *  números, paréntesis (los que no cierran o sobran, marcados). Puro: vitest. Con `columns` / `functions` vacíos no
 *  se marca nada como desconocido. */
export function tokenize(text: string, columns: string[] = [], functions: FormulaFunction[] = [],
                         mode: FormulaMode = 'expr'): FormulaToken[] {
    const cols = new Set(columns);
    const funcs = new Set(functions.map((f) => f.name.toUpperCase()));
    const out: FormulaToken[] = [];
    const opens: number[] = [];
    for (const m of text.matchAll(TOKEN_RE)) {
        const t = m[0];
        const at = m.index ?? 0;
        if (t[0] === '[') {
            if (t.length < 3 || !t.endsWith(']')) {
                out.push({ type: 'text', text: t });   // se está escribiendo
            } else {
                const name = t.slice(1, -1);
                out.push(cols.size === 0 || cols.has(name) ? { type: 'column', text: t }
                    : { type: 'column-unknown', text: t, title: `No existe la columna ${t}` });
            }
        } else if (t[0] === '"' || t[0] === "'") {
            out.push({ type: 'string', text: t });
        } else if (/^\d/.test(t)) {
            out.push({ type: 'number', text: t });
        } else if (/^[\p{L}_]/u.test(t)) {
            const up = t.toUpperCase();
            const isCall = /^\s*\(/.test(text.slice(at + t.length));
            if (mode === 'expr' && KEYWORDS.has(up)) {
                out.push({ type: 'keyword', text: t });
            } else if (isCall) {
                out.push(funcs.size === 0 || funcs.has(up) ? { type: 'func', text: t }
                    : { type: 'func-unknown', text: t, title: `Función desconocida: ${t}` });
            } else if (mode === 'sql') {
                out.push(SQL_KEYWORDS.has(up) ? { type: 'keyword', text: t }
                    : cols.has(t) ? { type: 'column', text: t } : { type: 'ident', text: t });
            } else {
                out.push({ type: 'ident', text: t });   // una variable (VAR …) o algo que el servidor va a explicar
            }
        } else if (/^\s+$/.test(t)) {
            out.push({ type: 'ws', text: t });
        } else if (t === '(') {
            opens.push(out.length);
            out.push({ type: 'paren', text: t });
        } else if (t === ')') {
            if (opens.length) {
                opens.pop();
                out.push({ type: 'paren', text: t });
            } else {
                out.push({ type: 'paren-bad', text: t, title: 'Sobra un paréntesis' });
            }
        } else {
            out.push({ type: 'op', text: t });
        }
    }
    for (const i of opens) out[i] = { type: 'paren-bad', text: '(', title: 'Falta cerrar este paréntesis' };
    return out;
}

function isCallLike(f: FormulaFunction): boolean {
    return !f.sig || f.sig.startsWith(f.name + '(');
}

/** Qué se puede completar donde está el cursor: dentro de un «[» abierto, las columnas que contengan lo escrito;
 *  en una palabra, las funciones que empiecen así (y en SQL, también las columnas). null si nada. Puro: vitest. */
export function completionAt(text: string, caret: number, columns: string[] = [], functions: FormulaFunction[] = [],
                             mode: FormulaMode = 'expr'): FormulaCompletion | null {
    const before = text.slice(0, caret);
    const br = before.lastIndexOf('[');
    if (mode === 'expr' && br >= 0 && before.indexOf(']', br) < 0) {
        const typed = before.slice(br + 1).toLowerCase();
        const items = columns.filter((c) => c.toLowerCase().includes(typed))
            .map((c): FormulaCompletionItem => ({ label: c, insert: `[${c}]`, detail: 'columna' }));
        const end = text[caret] === ']' ? caret + 1 : caret;
        return items.length ? { start: br, end, kind: 'column', items } : null;
    }
    const w = WORD_END.exec(before);
    if (!w || (text[caret] && WORD_CHAR.test(text[caret]))) return null;
    const typed = w[1];
    const up = typed.toUpperCase();
    const items: FormulaCompletionItem[] = [];
    for (const f of functions) {
        if (!f.name.toUpperCase().startsWith(up)) continue;
        const call = isCallLike(f);
        const empty = f.sig === `${f.name}()`;
        items.push({ label: f.name, insert: call ? `${f.name}()` : `${f.name} `, caretBack: call && !empty ? 1 : 0,
            detail: f.sig, doc: f.doc });
    }
    if (mode === 'sql') {
        for (const c of columns) {
            if (c.toLowerCase().startsWith(typed.toLowerCase())) items.push({ label: c, insert: c, detail: 'columna' });
        }
    }
    return items.length ? { start: caret - typed.length, end: caret, kind: 'function', items: items.slice(0, 12) } : null;
}

/** El texto con lo elegido en lugar del trozo, y dónde queda el cursor. Puro: vitest. */
export function applyCompletion(text: string, c: { start: number; end: number }, item: FormulaCompletionItem) {
    const next = text.slice(0, c.start) + item.insert + text.slice(c.end);
    return { text: next, caret: c.start + item.insert.length - (item.caretBack ?? 0) };
}

/** La función conocida en la que está el cursor (el «(» abierto más cercano que sigue a un nombre). Puro: vitest. */
export function enclosingFunction(text: string, caret: number, functions: FormulaFunction[] = []): FormulaFunction | null {
    const stack: string[] = [];
    let lastWord = '';
    for (const m of text.slice(0, caret).matchAll(TOKEN_RE)) {
        const t = m[0];
        if (t === '(') {
            stack.push(lastWord);
            lastWord = '';
        } else if (t === ')') {
            stack.pop();
            lastWord = '';
        } else if (/^[\p{L}_]/u.test(t)) {
            lastWord = t;
        } else if (!/^\s+$/.test(t)) {
            lastWord = '';
        }
    }
    for (let i = stack.length - 1; i >= 0; i--) {
        const f = functions.find((x) => x.name.toUpperCase() === stack[i].toUpperCase());
        if (f) return f;
    }
    return null;
}

const FormulaEditor = forwardRef<HTMLTextAreaElement, FormulaEditorProps>((props, ref) => {
    const { value = '', onChange, columns = [], functions = [], mode = 'expr', rows = 3, placeholder, readOnly,
        disabled, spellCheck = false, error, className = '', style = {}, name, id, 'aria-label': ariaLabel } = props;
    const taRef = useRef<HTMLTextAreaElement>(null);
    const preRef = useRef<HTMLPreElement>(null);
    useImperativeHandle(ref, () => taRef.current as HTMLTextAreaElement);
    const [caret, setCaret] = useState(0);
    const [open, setOpen] = useState(false);
    const [active, setActive] = useState(0);
    const [pending, setPending] = useState<number | null>(null);

    const tokens = useMemo(() => tokenize(value, columns, functions, mode), [value, columns, functions, mode]);
    const completion = useMemo(() => (open ? completionAt(value, caret, columns, functions, mode) : null),
        [open, value, caret, columns, functions, mode]);
    const enclosing = useMemo(() => enclosingFunction(value, caret, functions), [value, caret, functions]);
    const items = completion?.items ?? [];

    useEffect(() => {
        if (pending != null && taRef.current) {
            taRef.current.setSelectionRange(pending, pending);
            setPending(null);
        }
    }, [pending, value]);

    const syncCaret = useCallback(() => {
        if (taRef.current) setCaret(taRef.current.selectionStart ?? 0);
    }, []);

    const accept = useCallback((item: FormulaCompletionItem) => {
        if (!completion) return;
        const r = applyCompletion(value, completion, item);
        onChange?.(r.text);
        setCaret(r.caret);
        setPending(r.caret);
        setOpen(false);
    }, [completion, value, onChange]);

    const onInput = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        onChange?.(e.target.value);
        setCaret(e.target.selectionStart ?? e.target.value.length);
        setOpen(true);
        setActive(0);
    };

    const onKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
        if (e.ctrlKey && e.key === ' ') {
            e.preventDefault();
            setOpen(true);
            return;
        }
        if (!open || !items.length) return;
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            setActive((a) => (a + 1) % items.length);
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            setActive((a) => (a - 1 + items.length) % items.length);
        } else if (e.key === 'Enter' || e.key === 'Tab') {
            e.preventDefault();
            accept(items[Math.min(active, items.length - 1)]);
        } else if (e.key === 'Escape') {
            e.preventDefault();
            setOpen(false);
        }
    };

    const onScroll = () => {
        if (taRef.current && preRef.current) {
            preRef.current.scrollTop = taRef.current.scrollTop;
            preRef.current.scrollLeft = taRef.current.scrollLeft;
        }
    };

    const { padding = '0.4rem 0.5rem', fontFamily = 'Consolas, monospace', fontSize = '0.75rem', lineHeight = '1.4',
        resize = 'vertical', minHeight, height, color, width = '100%', flex, ...boxStyle } = style;
    const layer: React.CSSProperties = { padding, fontFamily, fontSize, lineHeight, margin: 0, whiteSpace: 'pre-wrap',
        wordBreak: 'break-word', overflowWrap: 'anywhere', tabSize: 4, boxSizing: 'border-box' };
    return (
        <div className={`w3f-formula ${className}`.trim()} style={{ width, flex, minWidth: 0, boxSizing: 'border-box' }} data-mode={mode}>
            <div className="w3f-formula__box" style={{ position: 'relative', boxSizing: 'border-box', ...boxStyle }}>
                <pre ref={preRef} aria-hidden className="w3f-formula__layer"
                     style={{ ...layer, position: 'absolute', inset: 0, overflow: 'hidden', pointerEvents: 'none',
                         background: 'transparent', color: color ?? 'var(--w3f-formula-fg, inherit)' }}>
                    {value ? tokens.map((t, i) => (
                        <span key={i} className={`w3f-formula__t w3f-formula__t--${t.type}`} title={t.title}
                              style={{ color: COLORS[t.type], textDecoration: t.title ? 'underline wavy' : undefined }}>{t.text}</span>
                    )) : <span style={{ opacity: 0.55 }}>{placeholder}</span>}
                    {'​'}
                </pre>
                <textarea ref={taRef} className="w3f-formula__input" rows={rows} value={value} name={name} id={id}
                          aria-label={ariaLabel} readOnly={readOnly} disabled={disabled} spellCheck={spellCheck}
                          autoComplete="off" autoCorrect="off" autoCapitalize="off"
                          onChange={onInput} onKeyDown={onKeyDown} onKeyUp={syncCaret} onClick={syncCaret}
                          onSelect={syncCaret} onScroll={onScroll} onBlur={() => setTimeout(() => setOpen(false), 150)}
                          style={{ ...layer, display: 'block', width: '100%', border: 'none', outline: 'none',
                              background: 'transparent', color: 'transparent', position: 'relative',
                              caretColor: color ?? 'var(--w3f-formula-caret, currentColor)', resize, minHeight, height }} />
            </div>
            {open && items.length > 0 && (
                <ul className="w3f-formula__list" role="listbox" aria-label="Sugerencias"
                    style={{ listStyle: 'none', margin: '0.15rem 0 0', padding: '0.2rem 0', maxHeight: 190, overflowY: 'auto',
                        border: '1px solid var(--w3f-formula-border, #4b5563)', borderRadius: 6, fontFamily, fontSize,
                        background: 'var(--w3f-formula-popup-bg, #1f2937)', color: 'var(--w3f-formula-popup-fg, #e5e7eb)' }}>
                    {items.map((it, i) => (
                        <li key={it.label + i} role="option" aria-selected={i === active} data-insert={it.insert}
                            onMouseDown={(e) => { e.preventDefault(); accept(it); }} onMouseEnter={() => setActive(i)}
                            style={{ padding: '0.2rem 0.5rem', cursor: 'pointer',
                                background: i === active ? 'var(--w3f-formula-active, rgba(96, 165, 250, 0.25))' : 'transparent' }}>
                            <span style={{ fontWeight: 600 }}>{it.label}</span>
                            {it.detail && <span style={{ opacity: 0.7, marginLeft: 8 }}>{it.detail}</span>}
                            {i === active && it.doc && (
                                <div style={{ opacity: 0.85, fontSize: '0.92em', whiteSpace: 'normal' }}>{it.doc}</div>
                            )}
                        </li>
                    ))}
                </ul>
            )}
            {(error || (enclosing && !(open && items.length))) && (
                <div className="w3f-formula__hint" style={{ fontSize: '0.72rem', marginTop: '0.15rem', opacity: 0.9 }}>
                    {error ? <span style={{ color: 'var(--w3f-formula-bad, #f87171)' }}>{error}</span>
                        : <><b>{enclosing!.sig ?? enclosing!.name}</b>{enclosing!.doc ? ` ${enclosing!.doc}` : ''}</>}
                </div>
            )}
        </div>
    );
});

FormulaEditor.displayName = 'FormulaEditor';

export { FormulaEditor };
export default FormulaEditor;
