/**
 * VX4 (w3f-data-analysis): la escala de color fija, como vmin / vmax / clim / norm de matplotlib: el valor que da el
 * primer color (`colorMin`), el que da el último (`colorMax`) y si la escala es logarítmica (`colorLog`). Sin valor,
 * los extremos de los datos. Lo usan el mapa de calor, el calendario y el mapa.
 */
export interface ChartColorRangeProps {
    colorMin?: number;
    colorMax?: number;
    colorLog?: boolean;
}

/** ¿Se eligió algo de la escala de color? */
export const hasColorRange = (p: ChartColorRangeProps) => p.colorMin != null || p.colorMax != null || !!p.colorLog;

/** Dónde cae `value` en la escala (0 = primer color, 1 = último), con los extremos y la escala elegidos. */
export function colorPosition(value: number, lo: number, hi: number, log?: boolean): number {
    const clamp = (t: number) => (Number.isFinite(t) ? Math.max(0, Math.min(1, t)) : 0);
    if (log) {
        const shift = lo <= 0 ? 1 - lo : 0;   // la logarítmica necesita valores positivos
        const a = Math.log(lo + shift), b = Math.log(hi + shift);
        return clamp((Math.log(Math.max(value, lo) + shift) - a) / (b - a || 1));
    }
    return clamp((value - lo) / (hi - lo || 1));
}
