import type { BoxPlotGroup, BoxPlotStats } from './BoxPlot.types';
import { BOXPLOT_ROOT_CLASS } from './BoxPlot.constants';
import { buildChartRootClasses, buildBandScale, buildLinearScale, safeExtent, formatTick } from '../_base/utils';

export function buildBoxPlotClasses(className: string | undefined, unstyled: boolean | undefined): string {
    return buildChartRootClasses(BOXPLOT_ROOT_CLASS, className, unstyled);
}

function quantile(sorted: number[], q: number): number {
    const pos = (sorted.length - 1) * q;
    const base = Math.floor(pos);
    const rest = pos - base;
    return sorted[base + 1] !== undefined
        ? sorted[base] + rest * (sorted[base + 1] - sorted[base])
        : sorted[base];
}

/** VX6 (whis): hasta dónde llegan los bigotes: 1,5 × RIC (como siempre), 3 × RIC, mínimo y máximo, o percentiles. */
export type BoxWhisker = 'iqr15' | 'iqr3' | 'minmax' | 'p5_95' | 'p1_99' | 'p10_90';

export function computeStats(group: BoxPlotGroup, whis: BoxWhisker = 'iqr15'): BoxPlotStats {
    const sorted = [...group.values].sort((a, b) => a - b);
    const q1 = quantile(sorted, 0.25);
    const median = quantile(sorted, 0.5);
    const q3 = quantile(sorted, 0.75);
    const iqr = q3 - q1;
    let lowerFence = q1 - 1.5 * iqr;
    let upperFence = q3 + 1.5 * iqr;
    if (whis === 'iqr3') { lowerFence = q1 - 3 * iqr; upperFence = q3 + 3 * iqr; }
    else if (whis === 'minmax') { lowerFence = -Infinity; upperFence = Infinity; }
    else if (whis !== 'iqr15') {
        const [a, b] = whis === 'p5_95' ? [0.05, 0.95] : whis === 'p1_99' ? [0.01, 0.99] : [0.1, 0.9];
        lowerFence = quantile(sorted, a);
        upperFence = quantile(sorted, b);
    }
    const outliers = sorted.filter((v) => v < lowerFence || v > upperFence);
    const inside = sorted.filter((v) => v >= lowerFence && v <= upperFence);
    const whiskerMin = inside.length ? Math.min(...inside) : q1;
    const whiskerMax = inside.length ? Math.max(...inside) : q3;
    const mean = sorted.reduce((s, v) => s + v, 0) / (sorted.length || 1);
    // VX6 (notch): el intervalo de confianza de la mediana (± 1,57 · RIC / √n)
    const notch = sorted.length ? (1.57 * iqr) / Math.sqrt(sorted.length) : 0;

    return {
        group: group.group,
        min: whiskerMin,
        firstQuartile: q1,
        median,
        thirdQuartile: q3,
        max: whiskerMax,
        outliers,
        mean,
        notchLow: median - notch,
        notchHigh: median + notch,
    };
}

export function buildBoxPlotScales(
    stats: readonly BoxPlotStats[],
    innerWidth: number,
    innerHeight: number,
    yDomain?: [number, number],
) {
    const groups = stats.map((s) => s.group);
    const allValues = stats.flatMap((s) => [s.min, s.max, ...s.outliers]);
    const [yMin, yMax] = yDomain ?? safeExtent(allValues);

    const xScale = buildBandScale(groups, [0, innerWidth], 0.3);
    const yScale = buildLinearScale(yMin, yMax, [innerHeight, 0]);

    return { xScale, yScale };
}

export { formatTick };

export function buildTooltipContent(stats: BoxPlotStats): string {
    return `${stats.group}: med=${stats.median.toFixed(1)}, Q1=${stats.firstQuartile.toFixed(1)}, Q3=${stats.thirdQuartile.toFixed(1)}`;
}
