'use client'

import React, { useMemo } from 'react';
import { Group } from '@visx/group';
import { Bar as VisxBar } from '@visx/shape';
import type { BarHorizontalDatum, BarHorizontalInnerProps } from './BarHorizontal.types';
import { BAR_H_DEFAULTS } from './BarHorizontal.constants';
import { buildBarHClasses, buildTooltipContent, formatTick } from './BarHorizontal.utils';
import {
    useBarHAccessors,
    useBarHScales,
    useBarHColors,
    useBarHInteraction,
    useInnerDims,
} from './BarHorizontal.hooks';
import { adaptScale, plotLeft, plotTop, xAxisLayout, yAxisLayout } from '../_base/axisLayout';   // 0026 X7
import { ChartAxis } from '../primitives/ChartAxis';
import { ChartGrid } from '../primitives/ChartGrid';
import { ChartTooltip } from '../primitives/ChartTooltip';
import { ChartTooltipMini } from '../primitives/ChartTooltipMini';   // 0022 PB12.4
import { BASE_CHART_CLASSES } from '../_base/constants';
import { ChartHeader } from '../_base/ChartHeader';
import { ChartMarkDecorLayer } from '../primitives/ChartMarkDecor';   // VX3
import { ChartErrorBars, scaleForErrors } from '../primitives/ChartErrorBars';   // VX8

export const BarHorizontalInner: React.FC<BarHorizontalInnerProps> = (props) => {
    const {
        data, width, height, margin, className,
        unstyled = BAR_H_DEFAULTS.unstyled, bindId, ariaLabel, description, colorScheme,
        title, subtitle,
        titleSize, titleColor, subtitleSize, subtitleColor,
        titleAlign, subtitleAlign,
        titleBold, titleItalic, titleUnderline, subtitleBold, subtitleItalic, subtitleUnderline,
        getLabel: gL, getValue: gV,
        showXAxis = BAR_H_DEFAULTS.showXAxis, showYAxis = BAR_H_DEFAULTS.showYAxis,
        showGrid = BAR_H_DEFAULTS.showGrid, showTooltip = BAR_H_DEFAULTS.showTooltip,
        padding = BAR_H_DEFAULTS.padding, barRadius = BAR_H_DEFAULTS.barRadius,
        xDomain, formatX, highlightIndex = null, onHover, onSelect,
        barLabels = 'none',
        barLabelPosition = 'top',
        categoryLabelSize = 10,
        valueLabelSize = 10,
        axisFontSize,
    } = props;

    const { getLabel, getValue } = useBarHAccessors(gL, gV);
    const dims = useInnerDims(width, height, margin, props);
    const { xScale: xScaleRaw, yScale: yScaleRaw } = useBarHScales(data, dims.innerWidth, dims.innerHeight, getLabel, getValue, padding, xDomain);
    const xScale = scaleForErrors(adaptScale(xScaleRaw, props, 'x'), data, getValue, props, 'x');   // VX1, VX8
    const yScale = adaptScale(yScaleRaw, props, 'y');   // VX1: mínimo / máximo, log, al revés…
    const colors = useBarHColors(data, colorScheme);
    const { hoveredIndex, handleEnter, handleLeave, handleClick } = useBarHInteraction(onHover, onSelect);
    const classes = useMemo(() => buildBarHClasses(className, unstyled), [className, unstyled]);
    const xTickFormat = formatX ?? formatTick;
    const total = useMemo(() => data.reduce((s, d) => s + getValue(d), 0), [data, getValue]);

    if (data.length === 0) {
        return (
            <div className={classes}>
                <svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Empty horizontal bar chart'} />
            </div>
        );
    }

    return (
        <div className={classes} data-bind-id={bindId}>
            <ChartHeader
                title={title} subtitle={subtitle}
                titleStyle={titleSize || titleColor || titleAlign || titleBold || titleItalic || titleUnderline ? {
                    fontSize: titleSize, color: titleColor, textAlign: titleAlign,
                    fontWeight: titleBold ? 700 : undefined,
                    fontStyle: titleItalic ? 'italic' : undefined,
                    textDecoration: titleUnderline ? 'underline' : undefined,
                } : undefined}
                subtitleStyle={subtitleSize || subtitleColor || subtitleAlign || subtitleBold || subtitleItalic || subtitleUnderline ? {
                    fontSize: subtitleSize, color: subtitleColor, textAlign: subtitleAlign,
                    fontWeight: subtitleBold ? 700 : undefined,
                    fontStyle: subtitleItalic ? 'italic' : undefined,
                    textDecoration: subtitleUnderline ? 'underline' : undefined,
                } : undefined}
            />
            <div className={BASE_CHART_CLASSES.container} style={{ position: 'relative' }}>
                <svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Horizontal bar chart'}>
                    {description && <desc>{description}</desc>}
                    <Group top={plotTop(dims, props)} left={plotLeft(dims, props)}>
                        {showGrid && (
                            <ChartGrid xScale={xScale} width={dims.innerWidth} height={dims.innerHeight} axis="columns" />
                        )}
                        {data.map((d, i) => {
                            const label = String(getLabel(d));
                            const value = getValue(d);
                            const bh = yScale.bandwidth();
                            const barY = yScale(label) ?? 0;
                            const xBase = (xScale.range() as number[])[0];   // VX3: la base (con el eje al revés, a la derecha)
                            const xVal = xScale(value) ?? xBase;
                            const barWidth = Math.abs(xVal - xBase);
                            return (
                                <VisxBar
                                    key={label}
                                    x={Math.min(xBase, xVal)}
                                    y={barY}
                                    width={Math.max(barWidth, 0)}
                                    height={bh}
                                    fill={colors[i]}
                                    opacity={
                                        highlightIndex != null
                                            ? (highlightIndex === i ? 1 : 0.3)
                                            : hoveredIndex != null && hoveredIndex !== i ? 0.5 : 1
                                    }
                                    stroke={highlightIndex === i ? 'var(--w3f-chart-mark-outline, #fff)' : undefined}
                                    strokeWidth={highlightIndex === i ? 2 : undefined}
                                    rx={barRadius}
                                    onMouseEnter={() => handleEnter(d, i)}
                                    onMouseLeave={handleLeave}
                                    onClick={onSelect ? () => handleClick(d, i) : undefined}
                                    style={{ cursor: onSelect ? 'pointer' : undefined, transition: 'opacity 120ms ease-out' }}
                                />
                            );
                        })}
                        {/* Bar value labels */}
                        {barLabels !== 'none' && data.map((d, i) => {
                            const value = getValue(d);
                            const labelText = barLabels === 'percent'
                                ? `${total > 0 ? ((value / total) * 100).toFixed(1) : 0}%`
                                : value.toLocaleString();
                            const bh = yScale.bandwidth();
                            const barY = yScale(String(getLabel(d))) ?? 0;
                            const barWidth = xScale(value) ?? 0;
                            return (
                                <text
                                    key={`lbl-${i}`}
                                    x={barLabelPosition === 'inside' ? barWidth - 4
                                        : barLabelPosition === 'center' ? barWidth / 2
                                        : barLabelPosition === 'base' ? 4 : barWidth + 4}
                                    y={barY + bh / 2}
                                    dominantBaseline="middle"
                                    textAnchor={barLabelPosition === 'inside' ? 'end' : barLabelPosition === 'center' ? 'middle' : 'start'}
                                    fontSize={valueLabelSize}
                                    fontFamily="var(--w3f-chart-label-font, inherit)"
                                    style={{ fill: 'var(--w3f-chart-bar-value-color, var(--w3f-chart-axis-tick-label-color, #6b7280))', userSelect: 'none' }}
                                >
                                    {labelText}
                                </text>
                            );
                        })}

                        {/* Category labels — always rendered for reliable visibility */}
                        {data.map((d, i) => {
                            const label = String(getLabel(d));
                            const bh = yScale.bandwidth();
                            const barY = yScale(label) ?? 0;
                            return (
                                <text
                                    key={`cat-${i}`}
                                    x={-6}
                                    y={barY + bh / 2}
                                    dominantBaseline="middle"
                                    textAnchor="end"
                                    fontSize={categoryLabelSize}
                                    fontFamily="var(--w3f-chart-label-font, inherit)"
                                    fill="var(--w3f-chart-category-label-color, var(--w3f-chart-value-label-color, #888899))"
                                >
                                    {label}
                                </text>
                            );
                        })}

                        {/* Axes — ChartAxis labels suppressed since we render our own */}
                        {showXAxis && <ChartAxis scale={xScale} {...xAxisLayout(dims, props)} tickFormat={xTickFormat} tickFontSize={axisFontSize} />}
                        {showYAxis && <ChartAxis scale={yScale} {...yAxisLayout(dims, props)} hideTickLabels />}
                        <ChartErrorBars {...props} horizontal valueScale={(v: number) => xScale(v)}
                            items={data.map((d) => ({ at: (yScale(String(getLabel(d))) ?? 0) + yScale.bandwidth() / 2, row: d, value: getValue(d) }))} />
                    </Group>
                    <ChartMarkDecorLayer {...props} />   {/* VX3: trama, hueco, borde de dos colores */}
                </svg>
                {showTooltip && hoveredIndex != null && (
                    <ChartTooltip
                        left={(xScale(getValue(data[hoveredIndex])) ?? 0) + plotLeft(dims, props)}
                        top={(yScale(String(getLabel(data[hoveredIndex]))) ?? 0) + yScale.bandwidth() / 2 + plotTop(dims, props)}
                        visible
                        offsetX={8}
                    >
                        {buildTooltipContent(data[hoveredIndex], getLabel, getValue)}
                        {props.tooltipCharts?.[String(getLabel(data[hoveredIndex]))] && (   /* 0022 PB12.4 */
                            <ChartTooltipMini points={props.tooltipCharts[String(getLabel(data[hoveredIndex]))]}
                                kind={props.tooltipChartKind} title={props.tooltipChartTitle} />
                        )}
                    </ChartTooltip>
                )}
            </div>
        </div>
    );
};

BarHorizontalInner.displayName = 'BarHorizontalInner';
export default BarHorizontalInner;
