'use client'

import React from 'react';
import { curveLinear, curveStep, curveStepAfter, curveStepBefore } from '@visx/curve';

/**
 * 0022 B53.1 (w3f-data-analysis): piezas compartidas de los gráficos de líneas y áreas —el trazo de la línea
 * (continua / rayas / puntos), el formato de las fechas del eje X y los rótulos con el valor de cada punto—.
 */

/** Cómo se dibuja la línea. */
export type ChartLineStyle = 'solid' | 'dashed' | 'dotted';

/** Las props SVG del trazo para el estilo y el grosor dados (las rayas crecen con el grosor). */
export const lineDash = (style: ChartLineStyle | undefined, width = 2): { strokeDasharray?: string; strokeLinecap?: 'round' } => {
    const w = Math.max(1, width);
    if (style === 'dashed') return { strokeDasharray: `${w * 4} ${w * 2.5}` };
    if (style === 'dotted') return { strokeDasharray: `0 ${w * 2.2}`, strokeLinecap: 'round' };
    return {};
};

/** Cómo se escriben las fechas del eje X ('auto' = las de siempre). */
export type ChartDateFormat = 'auto' | 'day_month' | 'month' | 'month_year' | 'quarter' | 'year';

const MESES = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];

/** La función de las marcas del eje X para ese formato (undefined con 'auto'). */
export const dateTickFormat = (format: ChartDateFormat | undefined): ((v: unknown) => string) | undefined => {
    if (!format || format === 'auto') return undefined;
    return (v: unknown) => {
        const d = v instanceof Date ? v : new Date(v as string | number);
        if (Number.isNaN(d.getTime())) return String(v);
        const m = d.getMonth();
        const y = d.getFullYear();
        switch (format) {
            case 'day_month': return `${d.getDate()} ${MESES[m]}`;
            case 'month': return MESES[m];
            case 'month_year': return `${MESES[m]} ${String(y).slice(2)}`;
            case 'quarter': return `T${Math.floor(m / 3) + 1} ${y}`;
            case 'year': return String(y);
            default: return d.toLocaleDateString();
        }
    };
};

/** Qué puntos llevan el rótulo con su valor. */
export type ChartValueLabels = 'none' | 'all' | 'last' | 'minmax';

/** Las posiciones (índices) de los puntos que llevan rótulo, para `n` puntos con esos valores. */
export const labelIndices = (mode: ChartValueLabels | undefined, values: number[]): number[] => {
    const n = values.length;
    if (!mode || mode === 'none' || n === 0) return [];
    if (mode === 'all') return values.map((_, i) => i);
    if (mode === 'last') return [n - 1];
    let lo = 0;
    let hi = 0;
    values.forEach((v, i) => {
        if (v < values[lo]) lo = i;
        if (v > values[hi]) hi = i;
    });
    return lo === hi ? [hi] : [lo, hi];
};

export interface ChartPointLabel { x: number; y: number; text: string; color?: string }

export interface ChartPointLabelsProps {
    labels: ChartPointLabel[];
    /** Tamaño de la letra (px). */
    size?: number;
}

export const POINT_LABEL_CLASS = 'w3f-chart-point-label';

/** Los rótulos de valores encima de cada punto (color: --w3f-chart-value-label-color, letra: --w3f-chart-label-font). */
export const ChartPointLabels: React.FC<ChartPointLabelsProps> = ({ labels, size = 11 }) => (
    <g pointerEvents="none">
        {labels.map((l, i) => (
            <text key={i} className={POINT_LABEL_CLASS} x={l.x} y={l.y - 8} textAnchor="middle" fontSize={size}
                style={{ fill: l.color ?? 'var(--w3f-chart-value-label-color, #888899)',
                         fontFamily: 'var(--w3f-chart-label-font, inherit)', fontVariantNumeric: 'tabular-nums' }}>
                {l.text}
            </text>
        ))}
    </g>
);

export const formatLabel = (v: number, format?: (n: number) => string): string =>
    format ? format(v) : v.toLocaleString('es-AR', { maximumFractionDigits: 2 });

/**
 * VX4 (w3f-data-analysis): lo que matplotlib le pone a las líneas: escalonada (drawstyle / where / step), color entre
 * los guiones (gapcolor), un punto cada N (markevery), puntos medio llenos (fillstyle) y el modo paletas (stem: un
 * palito desde la base hasta cada punto; linefmt / markerfmt / basefmt / orientation).
 */
export interface ChartLineExtrasProps {
    lineStep?: 'none' | 'pre' | 'mid' | 'post';
    lineGapColor?: string;
    dotEvery?: number;
    dotFill?: 'full' | 'none' | 'left' | 'right' | 'top' | 'bottom';
    lineMode?: 'line' | 'stem';
    stemLineStyle?: ChartLineStyle;
    stemBaseline?: 'solid' | 'dashed' | 'dotted' | 'none';
    stemOrientation?: 'vertical' | 'horizontal';
}

/** La curva de la línea: escalonada si se eligió; si no, la suave o la recta de siempre. */
export const pickCurve = <C,>(curved: boolean | undefined, step: ChartLineExtrasProps['lineStep'], smooth: C) => {
    if (step === 'pre') return curveStepBefore;
    if (step === 'mid') return curveStep;
    if (step === 'post') return curveStepAfter;
    return curved ? smooth : curveLinear;
};

/** ¿Lleva punto la posición i? (un punto cada N valores) */
export const dotShown = (i: number, every?: number) => !every || every <= 1 || i % every === 0;

/** Un punto medio lleno (o hueco): el contorno del color de la serie y la mitad pintada. */
export const HalfDot: React.FC<{ cx: number; cy: number; r: number; color: string; fill: NonNullable<ChartLineExtrasProps['dotFill']>;
    opacity?: number }> = ({ cx, cy, r, color, fill, opacity }) => {
    const half = fill === 'left' ? `M${cx},${cy - r}A${r},${r} 0 0 0 ${cx},${cy + r}Z`
        : fill === 'right' ? `M${cx},${cy - r}A${r},${r} 0 0 1 ${cx},${cy + r}Z`
        : fill === 'top' ? `M${cx - r},${cy}A${r},${r} 0 0 1 ${cx + r},${cy}Z`
        : fill === 'bottom' ? `M${cx - r},${cy}A${r},${r} 0 0 0 ${cx + r},${cy}Z` : '';
    return (
        <g opacity={opacity} pointerEvents="none" className="w3f-chart-halfdot">
            <circle cx={cx} cy={cy} r={r} fill="var(--w3f-chart-bg, transparent)" stroke={color} strokeWidth={1.5} />
            {half && <path d={half} fill={color} />}
        </g>
    );
};

export default ChartPointLabels;
