'use client'

import React, { forwardRef, useRef, useCallback, useEffect } from 'react';
import Slider from '../../INPUTS/Slider/Slider';
import type { DesktopProps } from './Desktop.types';
import { DESKTOP_CLASSES, DESKTOP_DEFAULTS, FOCUS_EVENT, FOCUS_FLASH_CLASS, fitView } from './Desktop.constants';
import { getWindowZIndex, buildDesktopClasses } from './Desktop.utils';
import { useWindowOrder, useCanvasTransform } from './Desktop.hooks';
import { useDesktopLinks, useLinkDrag, LINK_ROUTING_ATTR, relPos } from './Desktop.links';
import { SETTLE_EVENT, WINDOW_LAYOUT_ATTR } from './Desktop.overlap';

/**
 * Desktop Component - W3F Framework
 *
 * Entorno de escritorio para gestionar ventanas (Window) con:
 * - z-index dinámico (ventana con foco al frente)
 * - Zoom con rueda del mouse hacia el cursor (zoomable=true)
 * - Slider de zoom en toolbar inferior (showZoomControls=true)
 * - Pan arrastrando el fondo con cursor grab (pannable=true)
 * - Canvas interno grande para posicionar ventanas libremente
 *
 * @example
 * <Desktop zoomable pannable background="#1a1a2e" height="600px">
 *   <Window key="w1" title="Editor" initialPosition={{x:30,y:20}}>...</Window>
 *   <Window key="w2" title="Terminal" initialPosition={{x:400,y:100}}>...</Window>
 * </Desktop>
 */
const Desktop = forwardRef<HTMLDivElement, DesktopProps>(({
    children,
    unstyled         = DESKTOP_DEFAULTS.unstyled,
    className        = DESKTOP_DEFAULTS.className,
    style,
    background       = DESKTOP_DEFAULTS.background,
    height           = DESKTOP_DEFAULTS.height,
    // zoom
    zoomable         = DESKTOP_DEFAULTS.zoomable,
    defaultZoom      = DESKTOP_DEFAULTS.defaultZoom,
    minZoom          = DESKTOP_DEFAULTS.minZoom,
    maxZoom          = DESKTOP_DEFAULTS.maxZoom,
    zoomStep         = DESKTOP_DEFAULTS.zoomStep,
    showZoomControls = DESKTOP_DEFAULTS.showZoomControls,
    showFitAll       = true,
    // pan
    pannable         = DESKTOP_DEFAULTS.pannable,
    defaultPan       = DESKTOP_DEFAULTS.defaultPan,
    // canvas
    canvasWidth      = DESKTOP_DEFAULTS.canvasWidth,
    canvasHeight     = DESKTOP_DEFAULTS.canvasHeight,
    onViewChange,
    onLinkChange,
    linkRouting      = 'curve',
    windowLayout     = 'free',
    view,
}, forwardedRef) => {

    // ── Refs ────────────────────────────────────────────────────────────────
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef    = useRef<HTMLDivElement>(null);
    const linksRef     = useRef<SVGSVGElement>(null);
    const badgesRef    = useRef<SVGSVGElement>(null);
    const routingRef   = useRef(linkRouting);
    routingRef.current = linkRouting;
    useDesktopLinks(canvasRef, linksRef, badgesRef, routingRef);   // líneas `links` / `linkId` entre ventanas
    const zoomRef = useRef(1);
    const onLinkChangeRef = useRef(onLinkChange);
    useEffect(() => { onLinkChangeRef.current = onLinkChange; }, [onLinkChange]);
    useLinkDrag(canvasRef, badgesRef, zoomRef, onLinkChangeRef);   // arrastrar el punto de una línea `draggable`

    // Sin taparse (B23): al pasar a 'avoid', cada ventana se acomoda; primero cuentan las que no se arrastran
    // (data-fixed), después las demás en el orden en que se abrieron (las primeras se quedan, las otras se corren).
    useEffect(() => {
        const canvas = canvasRef.current;
        if (windowLayout !== 'avoid' || !canvas) return;
        const id = setTimeout(() => {
            const placed = (Array.from(canvas.querySelectorAll('.w3f-window[data-fixed]')) as HTMLElement[])
                .filter((w) => w.offsetWidth > 0).map((w) => relPos(w, canvas));
            canvas.dispatchEvent(new CustomEvent(SETTLE_EVENT, { detail: { placed } }));
        }, 50);
        return () => clearTimeout(id);
    }, [windowLayout]);

    // Merge forwarded ref + internal ref (necesario para non-passive wheel listener)
    const setRef = useCallback((node: HTMLDivElement | null) => {
        (containerRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
        if (typeof forwardedRef === 'function') {
            forwardedRef(node);
        } else if (forwardedRef) {
            (forwardedRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
        }
    }, [forwardedRef]);

    // ── State ───────────────────────────────────────────────────────────────
    const { windowOrder, handleWindowFocus } = useWindowOrder(children);
    const {
        zoom, pan, isPanning,
        zoomIn, zoomOut, resetZoom, setZoomLevel, setView,
        handlePanStart,
    } = useCanvasTransform({
        zoomEnabled:  zoomable,
        panEnabled:   pannable,
        defaultZoom,
        minZoom,
        maxZoom,
        zoomStep,
        defaultPan,
        containerRef,
    });
    zoomRef.current = zoom;

    // ── Vista: aplicar `view` cuando cambia su valor; avisar los cambios del usuario ──
    // `n` (opcional) permite volver a aplicar la misma vista
    const viewOk = !!view && [view.zoom, view.x, view.y].every(v => typeof v === 'number' && isFinite(v));
    const viewKey = viewOk ? `${view!.zoom}|${view!.x}|${view!.y}|${view!.n ?? ''}` : '';
    const appliedView = useRef('');
    useEffect(() => {
        if (!viewOk || !view || viewKey === appliedView.current) return;
        appliedView.current = viewKey;
        setView(view);
    }, [viewKey]);   // eslint-disable-line react-hooks/exhaustive-deps

    // ── Ir a una ventana (FOCUS_EVENT, lo manda DesktopTree): centrar la vista en ella, con el mismo zoom ──
    useEffect(() => {
        const root = containerRef.current;
        if (!root) return;
        const onFocus = (e: Event) => {
            const el = (e as CustomEvent).detail?.el as HTMLElement | undefined;
            const canvas = canvasRef.current;
            const vp = canvas?.parentElement;
            if (!el || !canvas || !vp || !canvas.contains(el)) return;
            const r = relPos(el, canvas);
            const z = zoomRef.current;
            const vw = vp.clientWidth, vh = vp.clientHeight, m = 24;
            // más grande que lo visible: el borde de arriba / de la izquierda a la vista; si no, centrada
            const x = r.width * z > vw - 2 * m ? m - r.left * z : vw / 2 - (r.left + r.width / 2) * z;
            const y = r.height * z > vh - 2 * m ? m - r.top * z : vh / 2 - (r.top + r.height / 2) * z;
            setView({ zoom: z, x: Math.round(x), y: Math.round(y) });
            el.classList.remove(FOCUS_FLASH_CLASS);
            void el.offsetWidth;   // vuelve a empezar la animación si se hace clic dos veces seguidas
            el.classList.add(FOCUS_FLASH_CLASS);
            window.setTimeout(() => el.classList.remove(FOCUS_FLASH_CLASS), 1600);
        };
        root.addEventListener(FOCUS_EVENT, onFocus);
        return () => root.removeEventListener(FOCUS_EVENT, onFocus);
    }, [setView]);

    // «Ver todo»: las ventanas (y los grupos) que se ven, en px del canvas → la vista que las muestra a todas
    const fitAll = useCallback(() => {
        const canvas = canvasRef.current;
        const vp = canvas?.parentElement;
        if (!canvas || !vp) return;
        const els = (Array.from(canvas.querySelectorAll('.w3f-window, .w3f-window-group')) as HTMLElement[])
            .filter((e) => e.offsetWidth > 0 && !e.parentElement?.closest('.w3f-window'));
        const v = fitView(els.map((e) => relPos(e, canvas)), vp.clientWidth, vp.clientHeight, minZoom, maxZoom);
        if (v) setView(v);
    }, [minZoom, maxZoom, setView]);

    const onViewChangeRef = useRef(onViewChange);
    useEffect(() => { onViewChangeRef.current = onViewChange; }, [onViewChange]);
    const firstView = useRef(true);
    useEffect(() => {
        if (firstView.current) { firstView.current = false; return; }   // no al montar
        if (isPanning || !onViewChangeRef.current) return;
        const id = setTimeout(() => onViewChangeRef.current?.(
            { zoom: Math.round(zoom * 100) / 100, x: Math.round(pan.x), y: Math.round(pan.y) }), 400);
        return () => clearTimeout(id);
    }, [zoom, pan.x, pan.y, isPanning]);

    // ── Styles ──────────────────────────────────────────────────────────────
    const containerHeight = typeof height === 'number' ? `${height}px` : height;
    const cssCanvasWidth  = typeof canvasWidth  === 'number' ? `${canvasWidth}px`  : canvasWidth;
    const cssCanvasHeight = typeof canvasHeight === 'number' ? `${canvasHeight}px` : canvasHeight;

    const canvasStyle: React.CSSProperties = {
        position:        'absolute',
        top:             0,
        left:            0,
        width:           cssCanvasWidth,
        height:          cssCanvasHeight,
        transformOrigin: '0 0',
        transform:       `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`,
    };

    const viewportStyle: React.CSSProperties = { position: 'relative', flex: 1, overflow: 'hidden' };
    if (pannable) {
        canvasStyle.cursor = viewportStyle.cursor = isPanning ? 'grabbing' : 'grab';
    }

    // ── Children con z-index ─────────────────────────────────────────────────
    const mappedChildren = React.Children.map(children, (child) => {
        if (!React.isValidElement(child)) return child;
        // Un Fragment (p. ej. el de un For de w3f) solo acepta key y children: no se le pasan style / scale /
        // onFocus (React avisaba «Invalid prop style supplied to React.Fragment» en cada render).
        if (child.type === React.Fragment) return child;
        const key = child.key;
        if (!key) {
            console.warn('Desktop: Window sin "key" prop. El z-index management requiere keys únicas.');
            return child;
        }
        const zIndex = getWindowZIndex(windowOrder, String(key));
        return React.cloneElement(
            child as React.ReactElement<Record<string, unknown>>,
            {
                style: { ...(child.props as Record<string, unknown>).style as object, zIndex },
                scale: zoom,
                onFocus: () => {
                    handleWindowFocus(String(key));
                    const childProps = child.props as Record<string, unknown>;
                    if (typeof childProps.onFocus === 'function') childProps.onFocus();
                },
            },
        );
    });

    const showToolbar = showZoomControls;

    const toolbarBtnStyle: React.CSSProperties = {
        display:         'inline-flex',
        alignItems:      'center',
        justifyContent:  'center',
        minWidth:        28,
        height:          26,
        padding:         '0 6px',
        border:          'none',
        background:      'transparent',
        color:           'var(--w3f-desktop-tb-color, #94a3b8)',
        fontSize:        15,
        cursor:          'pointer',
        borderRadius:    5,
        fontSize:        18,
        lineHeight:      1,
        fontFamily:      'inherit',
        outline:         'none',
    };

    // ── Render ───────────────────────────────────────────────────────────────
    return (
        <div
            ref={setRef}
            className={buildDesktopClasses(className, unstyled, pannable, isPanning)}
            style={{
                display:       'flex',
                flexDirection: 'column',
                width:         '100%',
                height:        containerHeight,
                background,
                ...style,
            }}
        >
            {/* Viewport — área visible del canvas (flex: 1, overflow: hidden) */}
            <div
                className={DESKTOP_CLASSES.viewport}
                style={viewportStyle}
                onMouseDown={pannable ? handlePanStart : undefined}
            >
                {/* Canvas interno — se transforma con zoom + pan */}
                <div
                    ref={canvasRef}
                    className={DESKTOP_CLASSES.canvas}
                    style={canvasStyle}
                    {...{ [LINK_ROUTING_ATTR]: linkRouting }}   // las líneas de WindowGroup también lo siguen
                    {...{ [WINDOW_LAYOUT_ATTR]: windowLayout }}  // cada Window lo lee al abrirse / soltarse (B23)
                >
                    <svg
                        ref={linksRef}
                        className="w3f-desktop-links"
                        style={{ position: 'absolute', top: 0, left: 0, width: 1, height: 1, overflow: 'visible',
                                 pointerEvents: 'none', zIndex: 1 }}
                    />
                    {mappedChildren}
                    <svg
                        ref={badgesRef}
                        className="w3f-desktop-links-badges"
                        style={{ position: 'absolute', top: 0, left: 0, width: 1, height: 1, overflow: 'visible',
                                 pointerEvents: 'none', zIndex: 100000 }}
                    />
                </div>
            </div>

            {/* Toolbar inferior con Slider de zoom */}
            {showToolbar && (
                <div
                    className={DESKTOP_CLASSES.toolbar}
                    // la misma barra que la del zoom del tablero (Dashboard zoombar): un recuadro finito con borde
                    style={{
                        flexShrink:     0,
                        display:        'flex',
                        alignItems:     'center',
                        gap:            '6px',
                        margin:         '6px 8px',
                        padding:        '4px 10px',
                        borderRadius:   6,
                        background:     'var(--w3f-desktop-tb-bg, #0b1222)',
                        border:         '1px solid var(--w3f-desktop-tb-border, #334155)',
                        userSelect:     'none',
                    }}
                >
                    <button
                        type="button"
                        className={DESKTOP_CLASSES.toolbarLabel}
                        onClick={zoomOut}
                        title="Zoom out"
                        aria-label="Zoom out"
                        style={toolbarBtnStyle}
                    >
                        −
                    </button>

                    <div
                        className={DESKTOP_CLASSES.toolbarSlider}
                        style={{ flex: 1, minWidth: 80, maxWidth: 260, display: 'flex', alignItems: 'center' }}
                    >
                        <Slider
                            value={zoom}
                            min={minZoom}
                            max={maxZoom}
                            step={zoomStep}
                            showValue={false}
                            ariaLabel="Zoom"
                            onChange={setZoomLevel}
                        />
                    </div>

                    <button
                        type="button"
                        className={DESKTOP_CLASSES.toolbarLabel}
                        onClick={zoomIn}
                        title="Zoom in"
                        aria-label="Zoom in"
                        style={toolbarBtnStyle}
                    >
                        +
                    </button>

                    <button
                        type="button"
                        className={`${DESKTOP_CLASSES.toolbarLabel} w3f-desktop-toolbar-pct`}
                        onClick={resetZoom}
                        title="Restablecer zoom"
                        aria-label="Restablecer zoom"
                        style={{ ...toolbarBtnStyle, minWidth: 52, fontSize: 12, fontWeight: 600, opacity: 0.8 }}
                    >
                        {Math.round(zoom * 100)}%
                    </button>

                    {showFitAll && (
                        <button
                            type="button"
                            className={`${DESKTOP_CLASSES.toolbarLabel} w3f-desktop-toolbar-fit`}
                            onClick={fitAll}
                            title="Ver todo el proyecto: que entren todas las ventanas"
                            aria-label="Ver todo"
                            style={{ ...toolbarBtnStyle, fontSize: 12, fontWeight: 600 }}
                        >
                            Ver todo
                        </button>
                    )}
                </div>
            )}
        </div>
    );
});

Desktop.displayName = 'Desktop';

export { Desktop };
export default Desktop;
