import type { DashboardTileLayout } from './Dashboard.types';

const overlaps = (a: DashboardTileLayout, b: DashboardTileLayout) =>
    a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;

/** Una tarjeta dentro de la grilla: enteros, ancho y alto ≥ 1, sin salirse por los costados ni por arriba. */
export function clampTile(t: DashboardTileLayout, columns: number): DashboardTileLayout {
    const w = Math.max(1, Math.min(columns, Math.round(Number(t.w) || 1)));
    const h = Math.max(1, Math.round(Number(t.h) || 1));
    const x = Math.max(0, Math.min(columns - w, Math.round(Number(t.x) || 0)));
    const y = Math.max(0, Math.round(Number(t.y) || 0));
    return { ...t, x, y, w, h };
}

/**
 * Acomoda el layout sin tarjetas encimadas: la tarjeta `pinned` (la que se acaba de mover) queda donde se soltó; las
 * demás, en orden de arriba hacia abajo, bajan lo justo para no pisar a ninguna y después suben todo lo que pueden
 * (gravedad hacia arriba; con `gravity` false se quedan a su altura). Mismo orden que el de entrada. Con `pageRows` (formato PDF), una tarjeta que entra en una
 * página no queda cortada: si cruza el final de una página, empieza en la siguiente.
 */
export function resolveLayout(layout: DashboardTileLayout[], columns: number, pinned?: string,
    pageRows = 0, gravity = true): DashboardTileLayout[] {
    const items = layout.map((t) => clampTile(t, columns));
    const order = [...items].sort((a, b) =>
        (a.id === pinned ? -1 : b.id === pinned ? 1 : 0) || a.y - b.y || a.x - b.x);
    const placed: DashboardTileLayout[] = [];
    for (const t of order) {
        const cur = { ...t };
        const page = (c: DashboardTileLayout) => {   // no cortarla entre dos páginas
            if (pageRows > 0 && c.h <= pageRows && Math.floor(c.y / pageRows) !== Math.floor((c.y + c.h - 1) / pageRows)) {
                c.y = Math.ceil(c.y / pageRows) * pageRows;
            }
        };
        if (cur.id !== pinned && gravity) cur.y = 0;   // sube todo lo que puede, después baja hasta que no pise ninguna
        page(cur);
        for (;;) {
            const hit = placed.find((p) => overlaps(p, cur));
            if (!hit) break;
            cur.y = hit.y + hit.h;
            page(cur);
        }
        placed.push(cur);
    }
    const byId = new Map(placed.map((t) => [t.id, t]));
    return items.map((t) => byId.get(t.id)!);
}

/** Celdas que corresponden a un desplazamiento en px (ya sin el zoom), con el ancho de celda y la separación. */
export function pxToCells(px: number, cell: number, gap: number): number {
    const step = cell + gap;
    return step > 0 ? Math.round(px / step) || 0 : 0;   // sin -0
}

/** Filas que ocupa el layout (la tarjeta más baja). */
export function layoutRows(layout: DashboardTileLayout[]): number {
    return layout.reduce((m, t) => Math.max(m, t.y + t.h), 0);
}

export function sameLayout(a: DashboardTileLayout[], b: DashboardTileLayout[]): boolean {
    return a.length === b.length && a.every((t, i) =>
        t.id === b[i].id && t.x === b[i].x && t.y === b[i].y && t.w === b[i].w && t.h === b[i].h);
}
