'use client'

import React, { useId, useMemo } from 'react';
import { Group } from '@visx/group';
import { Area as VisxArea, AreaClosed, LinePath } from '@visx/shape';
import { curveMonotoneX, curveLinear } from '@visx/curve';
import type { AreaDatum, AreaInnerProps } from './Area.types';
import { AREA_DEFAULTS } from './Area.constants';
import { buildAreaClasses, toDate, formatTick } from './Area.utils';
import { useAreaAccessors, useAreaScales, useAreaColor, useAreaInteraction, useInnerDims } from './Area.hooks';
import { adaptScale, plotLeft, plotTop, xAxisLayout, yAxisLayout } from '../_base/axisLayout';   // 0026 X7
import { ChartAxis } from '../primitives/ChartAxis';
import { ChartPointLabels, dateTickFormat, formatLabel, labelIndices, lineDash } from '../primitives/ChartLineMarks';   // 0022 B53.1
import { ChartGrid } from '../primitives/ChartGrid';
import { ChartReferenceLines, overlayPoints } from '../primitives/ChartReferenceLines';
import { ChartSecondaryAxes } from '../primitives/ChartSecondaryAxes';   // VX9
import { ChartErrorBars, ChartErrorBand, scaleForErrors } from '../primitives/ChartErrorBars';   // VX8, VX9
import { ChartTooltip } from '../primitives/ChartTooltip';
import { BASE_CHART_CLASSES } from '../_base/constants';
import { ChartHeader } from '../_base/ChartHeader';
import { pickCurve } from '../primitives/ChartLineMarks';   // VX4

export const AreaInner: React.FC<AreaInnerProps> = (props) => {
    const {
        data, width, height, margin, className,
        unstyled = AREA_DEFAULTS.unstyled, bindId, ariaLabel, description, colorScheme, title, subtitle,
        getDate: gD, getValue: gV,
        curved = AREA_DEFAULTS.curved, fillOpacity = AREA_DEFAULTS.fillOpacity,
        showLine = AREA_DEFAULTS.showLine, strokeWidth = AREA_DEFAULTS.strokeWidth,
        showXAxis = AREA_DEFAULTS.showXAxis, showYAxis = AREA_DEFAULTS.showYAxis,
        showGrid = AREA_DEFAULTS.showGrid, showTooltip = AREA_DEFAULTS.showTooltip,
        yDomain, formatY, tickRotateX = 0, highlightIndex = null, onHover, onSelect,
        lineStyle, valueLabels = 'none', valueLabelSize = 11, xDateFormat,   // 0022 B53.1
    } = props;

    const { getDate, getValue } = useAreaAccessors(gD, gV);
    const dims = useInnerDims(width, height, margin, props);
    const { xScale: xScaleRaw, yScale: yScaleRaw } = useAreaScales(data, dims.innerWidth, dims.innerHeight, getDate, getValue, yDomain);
    const xScale = adaptScale(xScaleRaw, props, 'x');   // VX1: mínimo / máximo, log, al revés…
    const yScale = scaleForErrors(adaptScale(yScaleRaw, props, 'y'), data, getValue, props, 'y');   // VX1, VX8
    const color = useAreaColor(colorScheme);
    const { hoveredIndex, handleEnter, handleLeave, handleClick } = useAreaInteraction(onHover, onSelect);
    const classes = useMemo(() => buildAreaClasses(className, unstyled), [className, unstyled]);
    const yTickFormat = formatY ?? formatTick;
    const curve = pickCurve(curved, props.lineStep, curveMonotoneX);   // VX4: escalonada
    const clipId = `w3f-area-where-${useId().replace(/[^a-zA-Z0-9_-]/g, '')}`;   // VX9
    const { areaWhere = 'all', areaWhereValue } = props;

    if (data.length === 0) {
        return (<div className={classes}><svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Empty area chart'} /></div>);
    }

    return (
        <div className={classes} data-bind-id={bindId}>
            <ChartHeader title={title} subtitle={subtitle} />
            <div className={BASE_CHART_CLASSES.container} style={{ position: 'relative' }}>
                <svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Area chart'}>
                    {description && <desc>{description}</desc>}
                    <Group top={plotTop(dims, props)} left={plotLeft(dims, props)}>
                        {showGrid && <ChartGrid yScale={yScale} width={dims.innerWidth} height={dims.innerHeight} axis="rows" />}
                        <ChartErrorBand {...props} color={color} curve={curve} valueScale={(v: number) => yScale(v)}
                            items={data.map((d) => ({ at: xScale(toDate(getDate(d))) ?? 0, row: d, value: getValue(d) }))} />

                        {areaWhere !== 'all' && areaWhereValue != null && Number.isFinite(areaWhereValue) ? (() => {
                            // VX9 (matplotlib fill_between where): el área entre la línea y el valor, solo arriba o solo abajo
                            const ty = Math.max(0, Math.min(dims.innerHeight, yScale(areaWhereValue) ?? 0));
                            const up = areaWhere === 'above';
                            return (
                                <g className="w3f-chart-area-where">
                                    <defs><clipPath id={clipId}><rect x={0} y={up ? 0 : ty} width={dims.innerWidth}
                                        height={up ? ty : Math.max(0, dims.innerHeight - ty)} /></clipPath></defs>
                                    <VisxArea data={[...data]} x={(d) => xScale(toDate(getDate(d))) ?? 0} y0={() => ty}
                                        y1={(d) => yScale(getValue(d)) ?? 0} fill={color} fillOpacity={fillOpacity} curve={curve}
                                        clipPath={`url(#${clipId})`} />
                                    <line x1={0} x2={dims.innerWidth} y1={ty} y2={ty} stroke={color} strokeOpacity={0.5} strokeDasharray="4 3" />
                                </g>
                            );
                        })() : <AreaClosed
                            data={[...data]}
                            x={(d) => xScale(toDate(getDate(d))) ?? 0}
                            y={(d) => yScale(getValue(d)) ?? 0}
                            yScale={yScale}
                            fill={color}
                            fillOpacity={fillOpacity}
                            curve={curve}
                        />}

                        {showLine && (
                            <LinePath
                                data={[...data]}
                                x={(d) => xScale(toDate(getDate(d))) ?? 0}
                                y={(d) => yScale(getValue(d)) ?? 0}
                                stroke={color}
                                strokeWidth={strokeWidth}
                                {...lineDash(lineStyle, strokeWidth)}
                                curve={curve}
                            />
                        )}
                        <ChartPointLabels size={valueLabelSize} labels={labelIndices(valueLabels, data.map(getValue)).map((i) => ({
                            x: xScale(toDate(getDate(data[i]))) ?? 0, y: yScale(getValue(data[i])) ?? 0,
                            text: formatLabel(getValue(data[i]), formatY) }))} />

                        {/* Hover targets */}
                        {data.map((d, i) => (
                            <circle
                                key={i}
                                cx={xScale(toDate(getDate(d))) ?? 0}
                                cy={yScale(getValue(d)) ?? 0}
                                r={8} fill="transparent"
                                onMouseEnter={() => handleEnter(d, i)}
                                onMouseLeave={handleLeave}
                                onClick={onSelect ? () => handleClick(d, i) : undefined}
                                style={{ cursor: onSelect ? 'pointer' : undefined }}
                            />
                        ))}

                        {hoveredIndex != null && (
                            <circle
                                cx={xScale(toDate(getDate(data[hoveredIndex]))) ?? 0}
                                cy={yScale(getValue(data[hoveredIndex])) ?? 0}
                                r={5} fill={color} stroke="var(--w3f-chart-mark-outline, #fff)" strokeWidth={2} pointerEvents="none"
                            />
                        )}

                        {showXAxis && <ChartAxis scale={xScale} {...xAxisLayout(dims, props, tickRotateX)} tickFormat={dateTickFormat(xDateFormat)} />}
                        {showYAxis && <ChartAxis scale={yScale} {...yAxisLayout(dims, props)} tickFormat={yTickFormat} />}

                        {/* Punto resaltado externamente (ej. fila seleccionada en tabla) */}
                        {highlightIndex != null && data[highlightIndex] != null && (() => {
                            const d = data[highlightIndex];
                            const cx = xScale(toDate(getDate(d))) ?? 0;
                            const cy = yScale(getValue(d)) ?? 0;
                            return (
                                <g>
                                    <circle cx={cx} cy={cy} r={12} fill={color} opacity={0.2} pointerEvents="none" />
                                    <circle cx={cx} cy={cy} r={6} fill={color} stroke="var(--w3f-chart-mark-outline, #fff)" strokeWidth={2.5} pointerEvents="none" />
                                    <line x1={cx} y1={0} x2={cx} y2={dims.innerHeight} stroke={color} strokeWidth={1} strokeDasharray="4 3" opacity={0.6} pointerEvents="none" />
                                </g>
                            );
                        })()}
                        <ChartErrorBars {...props} valueScale={(v: number) => yScale(v)}
                            items={data.map((d) => ({ at: xScale(toDate(getDate(d))) ?? 0, row: d, value: getValue(d) }))} />
                        <ChartSecondaryAxes {...props} xScale={xScale} yScale={yScale} width={dims.innerWidth} height={dims.innerHeight} />
                        <ChartReferenceLines lines={props.referenceLines} bands={props.referenceBands} annotation={props.annotation}
                            points={overlayPoints(data)} xScale={xScale}
                            yScale={(v: number) => yScale(v)} width={dims.innerWidth} height={dims.innerHeight} />
                    </Group>
                </svg>

                {showTooltip && hoveredIndex != null && (() => {
                    const d = data[hoveredIndex];
                    const date = toDate(getDate(d));
                    return (
                        <ChartTooltip left={(xScale(date) ?? 0) + plotLeft(dims, props)} top={(yScale(getValue(d)) ?? 0) + plotTop(dims, props)} visible offsetY={-12}>
                            {`${date.toLocaleDateString()}: ${getValue(d).toLocaleString()}`}
                        </ChartTooltip>
                    );
                })()}
            </div>
        </div>
    );
};

AreaInner.displayName = 'AreaInner';
export default AreaInner;
