'use client'

import React from 'react';

/**
 * FL15 (w3f-data-analysis): el número dentro de cada tramo de una barra apilada (el % del total de la barra o el
 * valor) y las barras «atenuadas» (por ejemplo los años anteriores, con el color más apagado).
 */
export type ChartSegmentLabelMode = 'none' | 'percent' | 'value';

export interface ChartBarExtrasProps {
    /** Número dentro de cada tramo: 'percent' = % del total de la barra, 'value' = el valor. Por defecto 'none'. */
    segmentLabels?: ChartSegmentLabelMode;
    /** No se escribe si el tramo es menos que este % del total de la barra (por defecto 4). */
    segmentLabelMin?: number;
    /** Decimales del porcentaje (por defecto 1). */
    segmentLabelDecimals?: number;
    /** Tamaño de letra del número (px, por defecto 11). */
    segmentLabelSize?: number;
    /** Nombres de las barras que van atenuadas (más transparentes). */
    mutedBars?: readonly string[];
    /** Opacidad de las barras atenuadas (0–1, por defecto 0.45). */
    mutedOpacity?: number;
}

const fmt = (n: number, decimals: number) =>
    n.toLocaleString('es-AR', { minimumFractionDigits: decimals, maximumFractionDigits: decimals });

/** El texto del tramo, o '' si no va (modo 'none', tramo vacío o más chico que `min` % del total). */
export function segmentText(value: number, total: number, mode: ChartSegmentLabelMode = 'none', min = 4,
                            decimals = 1): string {
    if (mode === 'none' || !Number.isFinite(value) || value === 0 || !total) return '';
    const pct = (value / total) * 100;
    if (Math.abs(pct) < min) return '';
    return mode === 'percent' ? `${fmt(pct, decimals)} %` : fmt(value, Number.isInteger(value) ? 0 : decimals);
}

/** La opacidad de una barra según `mutedBars` (1 si no está). */
export const barOpacity = (label: string, muted?: readonly string[], opacity = 0.45): number =>
    muted && muted.some((m) => String(m).trim() === String(label).trim()) ? opacity : 1;

export interface ChartSegmentLabelProps {
    x: number; y: number; width: number; height: number;
    text: string;
    size?: number;
    /** El color del tramo: sobre uno claro el número va oscuro (si no, blanco; un CSS var: blanco). */
    fill?: string;
}

/** Oscuro sobre un fondo claro, blanco sobre uno oscuro (#rgb, #rrggbb, rgb(…); lo demás: blanco). */
export function labelColor(fill?: string): string {
    const f = String(fill ?? '').trim();
    let rgb: number[] | null = null;
    const hex = f.match(/^#([0-9a-f]{3}|[0-9a-f]{6})([0-9a-f]{2})?$/i);
    if (hex) {
        const h = hex[1].length === 3 ? hex[1].split('').map((c) => c + c).join('') : hex[1];
        rgb = [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16));
    } else {
        const m = f.match(/^rgba?\(([^)]+)\)/i);
        if (m) rgb = m[1].split(',').slice(0, 3).map((v) => parseFloat(v));
    }
    if (!rgb || rgb.some((v) => Number.isNaN(v))) return 'var(--w3f-chart-segment-label-color, #fff)';
    const lum = (0.299 * rgb[0] + 0.587 * rgb[1] + 0.114 * rgb[2]) / 255;
    return lum > 0.6 ? 'var(--w3f-chart-segment-label-dark, #1f2937)' : 'var(--w3f-chart-segment-label-color, #fff)';
}

/** El número centrado en el rectángulo del tramo (si no entra, no se dibuja). */
export const ChartSegmentLabel: React.FC<ChartSegmentLabelProps> = ({ x, y, width, height, text, size = 11, fill }) => {
    if (!text || height < size + 2 || width < size * 0.6 * text.length) return null;
    return (
        <text x={x + width / 2} y={y + height / 2} textAnchor="middle" dominantBaseline="central"
            className="w3f-chart-segment-label" pointerEvents="none"
            style={{ fontSize: size, fill: labelColor(fill), fontWeight: 600 }}>
            {text}
        </text>
    );
};

export default ChartSegmentLabel;
