'use client'

import React from 'react';
import type { ChartReferenceLine, ChartReferenceBand, ChartAnnotation } from '../../_base/types';
import { parseDate } from '../../_base/utils';

/** A point of the data, in the chart's own units (x = category, date or number). */
export type ChartOverlayPoint = { x: unknown; y: number };

export interface ChartReferenceLinesProps {
    /** Reference lines (objective, average, threshold…): horizontal, or vertical with `axis: 'x'`. */
    lines?: readonly ChartReferenceLine[];
    /** Reference bands (matplotlib axhspan / axvspan): the zone between two values. */
    bands?: readonly ChartReferenceBand[];
    /** A note on one data point, with an optional arrow (matplotlib annotate). */
    annotation?: ChartAnnotation;
    /** The chart's points (for the annotation): see `overlayPoints`. */
    points?: readonly ChartOverlayPoint[];
    /** The chart's Y scale (value → px inside the plot group). */
    yScale: (value: number) => number | undefined;
    /** The chart's X scale (category / date / number → px). Needed for vertical lines, bands and the annotation. */
    xScale?: any;
    /** Plot width in px (inner width). */
    width: number;
    /** Plot height in px (inner height). Needed for vertical lines and bands. */
    height?: number;
}

export const REFERENCE_LINE_CLASS = 'w3f-chart-reference-line';
export const REFERENCE_BAND_CLASS = 'w3f-chart-reference-band';
export const ANNOTATION_CLASS = 'w3f-chart-annotation';

const LABEL_SIZE = 'var(--w3f-chart-axis-tick-label-size, 11px)';

/**
 * Where a value of the X axis goes, whatever the scale: a category (band scale: the middle of its band), a date
 * (time scale) or a number. `undefined` when the value is not on the axis.
 */
export function xPosition(xScale: any, v: unknown): number | undefined {
    if (!xScale || v == null || v === '') return undefined;
    if (typeof xScale.bandwidth === 'function') {
        const hit = (xScale.domain() as unknown[]).find((d) => String(d) === String(v));
        if (hit === undefined) return undefined;
        return (xScale(hit) ?? 0) + xScale.bandwidth() / 2;
    }
    const dom = xScale.domain() as unknown[];
    if (dom.length && dom[0] instanceof Date) {
        const d = parseDate(v as string);
        return Number.isNaN(d.getTime()) ? undefined : xScale(d);
    }
    const n = Number(v);
    return Number.isFinite(n) ? xScale(n) : undefined;
}

/**
 * The points of a chart's data, for the annotation: {label, value} (bars), {date, value} (lines, areas),
 * {date, close} (candles), {date, value0} (threshold), {x, y} (scatter), series with `data` (multi-line) and
 * rows of several keys (grouped / stacked bars: the largest or the sum).
 */
export function overlayPoints(data: readonly any[] | undefined, keys?: readonly string[], stacked = false): ChartOverlayPoint[] {
    const out: ChartOverlayPoint[] = [];
    for (const d of data ?? []) {
        if (d == null || typeof d !== 'object') continue;
        if (Array.isArray(d.data)) { out.push(...overlayPoints(d.data)); continue; }
        if ('x' in d && 'y' in d) out.push({ x: d.x, y: Number(d.y) });
        else if ('date' in d && 'value' in d) out.push({ x: d.date, y: Number(d.value) });
        else if ('date' in d && 'close' in d) out.push({ x: d.date, y: Number(d.close) });
        else if ('date' in d && 'value0' in d) out.push({ x: d.date, y: Number(d.value0) });
        else if ('label' in d && 'value' in d) out.push({ x: d.label, y: Number(d.value) });
        else if ('label' in d && keys && keys.length) {
            const vs = keys.map((k) => Number(d[k])).filter(Number.isFinite);
            if (vs.length) out.push({ x: d.label, y: stacked ? vs.reduce((s, v) => s + v, 0) : Math.max(...vs) });
        }
    }
    return out.filter((p) => Number.isFinite(p.y));
}

/** The waterfall's points: each bar ends at the running total (a total bar, at its own value). */
export function waterfallPoints(data: readonly { label: string; value: number; isTotal?: boolean }[] | undefined): ChartOverlayPoint[] {
    let run = 0;
    return (data ?? []).map((d) => {
        run = d.isTotal ? Number(d.value) : run + Number(d.value);
        return { x: d.label, y: run };
    });
}

/** The point the annotation points at: the largest, the smallest, the first, the last or the one of a given X. */
export function annotatedPoint(points: readonly ChartOverlayPoint[], at: string): ChartOverlayPoint | undefined {
    if (!points.length) return undefined;
    if (at === 'max') return points.reduce((a, b) => (b.y > a.y ? b : a));
    if (at === 'min') return points.reduce((a, b) => (b.y < a.y ? b : a));
    if (at === 'first') return points[0];
    if (at === 'last') return points[points.length - 1];
    const s = at.startsWith('x:') ? at.slice(2) : at;
    return points.find((p) => String(p.x) === s
        || ((p.x instanceof Date || typeof p.x === 'string') && parseDate(p.x as string).getTime() === parseDate(s).getTime()));
}

const fmt = (v: number) => v.toLocaleString('es-AR', { maximumFractionDigits: Math.abs(v) >= 1000 ? 0 : 2 });

/**
 * W3F ChartReferenceLines — reference lines, bands and an annotation over the plot (0022 M4.6.5; VX7: matplotlib
 * axhline xmin / xmax, axvline, axhspan, axvspan and annotate).
 *
 * Drawn inside the plot group (after the marks, so they stay on top; bands are translucent). Colors come from
 * each item or from `--w3f-chart-reference-color`.
 */
export const ChartReferenceLines: React.FC<ChartReferenceLinesProps> = ({
    lines, bands, annotation, points, yScale, xScale, width, height = 0,
}) => {
    const hasLines = !!lines && lines.length > 0;
    const hasBands = !!bands && bands.length > 0;
    if (!hasLines && !hasBands && !annotation) return null;
    const yAt = (v: unknown) => {
        const n = Number(v);
        const y = v === '' || v == null || !Number.isFinite(n) ? undefined : yScale(n);
        return y != null && Number.isFinite(y) ? y : undefined;
    };
    const xAt = (v: unknown) => {
        const x = xPosition(xScale, v);
        return x != null && Number.isFinite(x) ? x : undefined;
    };

    const ann = (() => {
        if (!annotation) return null;
        const p = annotatedPoint(points ?? [], annotation.at || 'max');
        if (!p) return null;
        const px = xAt(p.x);
        const py = yAt(p.y);
        if (px == null || py == null) return null;
        const dist = annotation.distance ?? 36;
        const dir = annotation.direction ?? 'up';
        const dx = dir === 'left' ? -dist : dir === 'right' ? dist : 0;
        const dy = dir === 'up' ? -dist : dir === 'down' ? dist : 0;
        const tx = Math.max(0, Math.min(width, px + dx));
        const ty = Math.max(10, height ? Math.min(height, py + dy) : py + dy);
        const color = annotation.color || 'var(--w3f-chart-reference-color, #f43f5e)';
        const text = annotation.text ? annotation.text : fmt(p.y);
        const anchor = dir === 'left' ? 'end' : dir === 'right' ? 'start' : 'middle';
        // la flecha va del texto al punto y termina un poco antes, con la punta hacia el punto
        const len = Math.hypot(px - tx, py - ty) || 1;
        const ux = (px - tx) / len, uy = (py - ty) / len;
        const sx = tx + ux * 8, sy = ty + uy * 8;
        const ex = px - ux * 4, ey = py - uy * 4;
        const head = 6;
        return (
            <g className={ANNOTATION_CLASS}>
                {annotation.arrow !== false && len > 14 && (
                    <>
                        <line x1={sx} y1={sy} x2={ex} y2={ey} stroke={color} strokeWidth={1.5} />
                        <path d={`M${ex},${ey}L${ex - ux * head - uy * head * 0.5},${ey - uy * head + ux * head * 0.5}`
                            + `L${ex - ux * head + uy * head * 0.5},${ey - uy * head - ux * head * 0.5}Z`} fill={color} />
                    </>
                )}
                <text x={tx} y={dir === 'down' ? ty + 10 : ty} textAnchor={anchor}
                    dominantBaseline={dir === 'left' || dir === 'right' ? 'middle' : 'auto'}
                    fill={color} fontSize={LABEL_SIZE} fontWeight={700}>{text}</text>
            </g>
        );
    })();

    return (
        <g className={`${REFERENCE_LINE_CLASS}s`} pointerEvents="none">
            {hasBands && bands!.map((b, i) => {
                const color = b.color || 'var(--w3f-chart-reference-color, #f43f5e)';
                const op = b.opacity ?? 0.15;
                if (b.axis === 'x') {
                    const a = xAt(b.from), c = xAt(b.to);
                    if (a == null || c == null) return null;
                    const x0 = Math.min(a, c), w = Math.abs(c - a) || 2;
                    return (
                        <g key={`b${i}`} className={REFERENCE_BAND_CLASS}>
                            <rect x={x0} y={0} width={w} height={height} fill={color} fillOpacity={op} />
                            {b.label && <text x={x0 + w / 2} y={12} textAnchor="middle" fill={color} fontSize={LABEL_SIZE} fontWeight={600}>{b.label}</text>}
                        </g>
                    );
                }
                const a = yAt(b.from), c = yAt(b.to);
                if (a == null || c == null) return null;
                const y0 = Math.min(a, c), h = Math.abs(c - a) || 2;
                return (
                    <g key={`b${i}`} className={REFERENCE_BAND_CLASS}>
                        <rect x={0} y={y0} width={width} height={h} fill={color} fillOpacity={op} />
                        {b.label && <text x={4} y={y0 + 12} fill={color} fontSize={LABEL_SIZE} fontWeight={600}>{b.label}</text>}
                    </g>
                );
            })}
            {hasLines && lines!.map((line, i) => {
                const color = line.color || 'var(--w3f-chart-reference-color, #f43f5e)';
                const sw = line.width ?? 1.5;
                const dash = line.dash ?? '6 4';
                const s0 = Math.max(0, Math.min(1, line.start ?? 0));
                const s1 = Math.max(s0, Math.min(1, line.end ?? 1));
                if (line.axis === 'x') {
                    const x = xAt(line.value);
                    if (x == null) return null;
                    // matplotlib axvline ymin / ymax: en fracciones del alto, desde abajo
                    const y1 = height * (1 - s0), y2 = height * (1 - s1);
                    return (
                        <g key={i} className={REFERENCE_LINE_CLASS}>
                            <line x1={x} x2={x} y1={y1} y2={y2} stroke={color} strokeWidth={sw} strokeDasharray={dash} />
                            {line.label && <text x={x + 4} y={y2 + 12} fill={color} fontSize={LABEL_SIZE} fontWeight={600}>{line.label}</text>}
                        </g>
                    );
                }
                const y = yAt(line.value);
                if (y == null) return null;
                const x1 = width * s0, x2 = width * s1;
                return (
                    <g key={i} className={REFERENCE_LINE_CLASS}>
                        <line x1={x1} x2={x2} y1={y} y2={y} stroke={color} strokeWidth={sw} strokeDasharray={dash} />
                        {line.label && (
                            <text x={x2 - 4} y={y - 4} textAnchor="end" fill={color} fontSize={LABEL_SIZE} fontWeight={600}>
                                {line.label}
                            </text>
                        )}
                    </g>
                );
            })}
            {ann}
        </g>
    );
};

ChartReferenceLines.displayName = 'ChartReferenceLines';

export default ChartReferenceLines;
