'use client'

import React, { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import type { DashboardPageBackground, DashboardProps, DashboardTileLayout, DashboardTileProps } from './Dashboard.types';
import Slider from '../../INPUTS/Slider/Slider';
import { DASHBOARD_CLASSES as C, DASHBOARD_DEFAULTS as D, FULLSCREEN_BAR, FULLSCREEN_PAD, RULER_GAP, RULER_SIZE,
    ZOOM_MAX, ZOOM_MIN, ZOOM_STEP } from './Dashboard.constants';
import { layoutRows, pxToCells, resolveLayout, sameLayout } from './Dashboard.utils';
import { snapshotHtml } from './Dashboard.snapshot';

/** Marca el contenido de una tarjeta del Dashboard (su lugar sale de `layout` por `tileId`). */
export const DashboardTile: React.FC<DashboardTileProps> = ({ children }) => <>{children}</>;

/** Los DashboardTile de `children`, también dentro de Fragment (así los arma un For de w3f) o de arreglos. */
function collectTiles(children: React.ReactNode, out: Map<string, React.ReactNode>) {
    React.Children.forEach(children, (child) => {
        if (!React.isValidElement(child)) return;
        const props = child.props as { tileId?: string; children?: React.ReactNode };
        if (props.tileId != null) out.set(String(props.tileId), child);
        else if (child.type === React.Fragment) collectTiles(props.children, out);
    });
}

interface Drag {
    id: string;
    mode: 'move' | 'resize';
    start: { x: number; y: number };
    origin: DashboardTileLayout;
}

/** Lo que se dibuja durante un arrastre: la tarjeta sigue al mouse (lo que le falta o le sobra respecto de su celda,
 *  en px sin zoom) y el paso de la grilla (para las reglas). */
interface Live {
    id: string;
    mode: Drag['mode'];
    ex: number;
    ey: number;
    stepX: number;
    stepY: number;
}

/** Regla en mm: marcas cada mm, más largas cada 5 y número cada 10. `pagePx` > 0: vuelve a empezar en cada página. */
function Ruler({ side, lengthPx, pxPerMm, offsetMm, pagePx, mark }: {
    side: 'top' | 'left'; lengthPx: number; pxPerMm: number; offsetMm: number; pagePx: number;
    mark?: { from: number; to: number } | null;
}) {
    const ticks: React.ReactNode[] = [];
    const span = pagePx > 0 ? pagePx : lengthPx;
    const pages = span > 0 ? Math.max(1, Math.ceil(lengthPx / span - 1e-6)) : 0;
    for (let p = 0; p < pages; p++) {
        const base = p * span;
        const mmCount = Math.floor(Math.min(span, lengthPx - base) / pxPerMm + 1e-6);
        for (let k = 0; k <= mmCount; k++) {
            const mm = offsetMm + k;
            const pos = base + k * pxPerMm;
            const len = mm % 10 === 0 ? RULER_SIZE * 0.55 : mm % 5 === 0 ? RULER_SIZE * 0.35 : RULER_SIZE * 0.2;
            ticks.push(side === 'top'
                ? <line key={`${p}-${k}`} x1={pos} x2={pos} y1={RULER_SIZE} y2={RULER_SIZE - len} />
                : <line key={`${p}-${k}`} y1={pos} y2={pos} x1={RULER_SIZE} x2={RULER_SIZE - len} />);
            if (mm % 10 === 0 && k > 0 && k < mmCount) {
                ticks.push(side === 'top'
                    ? <text key={`t${p}-${k}`} x={pos + 2} y={8}>{mm}</text>
                    : <text key={`t${p}-${k}`} x={8} y={pos + 2} textAnchor="end"
                        transform={`rotate(-90 8 ${pos + 2})`}>{mm}</text>);
            }
        }
    }
    const top = side === 'top';
    return (
        <svg className={`${C.ruler} ${top ? C.rulerTop : C.rulerLeft}`} aria-hidden
            width={top ? lengthPx : RULER_SIZE} height={top ? RULER_SIZE : lengthPx}>
            {mark && (top
                ? <rect className={C.rulerMark} x={mark.from} y={0} width={Math.max(1, mark.to - mark.from)}
                    height={RULER_SIZE} />
                : <rect className={C.rulerMark} x={0} y={mark.from} width={RULER_SIZE}
                    height={Math.max(1, mark.to - mark.from)} />)}
            {ticks}
        </svg>
    );
}

/** El estilo CSS de una capa de fondo según su ajuste (0026 X2). */
function backgroundStyle(bg: DashboardPageBackground, page = 1): React.CSSProperties {
    const fit = bg.fit ?? 'cover';
    const urls = bg.urls && bg.urls.length ? bg.urls : [bg.url];
    const url = urls[Math.min(page - 1, urls.length - 1)];
    const size = fit === 'cover' ? 'cover' : fit === 'contain' ? 'contain' : fit === 'stretch' ? '100% 100%' : 'auto';
    return {
        backgroundImage: `url("${url.replace(/"/g, '%22')}")`,
        backgroundSize: size,
        backgroundRepeat: fit === 'tile' ? 'repeat' : 'no-repeat',
        backgroundPosition: fit === 'tile' ? 'top left' : 'center',
        opacity: Math.max(0, Math.min(1, bg.opacity ?? 1)),
    };
}

/** El elemento con scroll más cercano que contiene a `el` (para el zoom «ajustar a la ventana»). */
function scrollerOf(el: HTMLElement | null): HTMLElement | null {
    let p = el?.parentElement ?? null;
    while (p && typeof getComputedStyle === 'function') {
        const cs = getComputedStyle(p);
        if (/(auto|scroll)/.test(cs.overflowY) || /(auto|scroll)/.test(cs.overflowX) || /(auto|scroll)/.test(cs.overflow)) return p;
        p = p.parentElement;
    }
    return null;
}

/**
 * Dashboard — tarjetas en una grilla que se mueven (arrastrando su barra) y cambian de tamaño (esquina de abajo a la
 * derecha). Al soltar, el layout se acomoda sin tarjetas encimadas y se avisa con `onLayoutChange`. Funciona con el
 * zoom del Desktop (mide la escala de la grilla). Con `fullscreen` se dibuja en toda la pantalla (portal a body).
 *
 * @example
 * <Dashboard layout={[{ id: 'a', x: 0, y: 0, w: 6, h: 4, title: 'Ventas' }]} onLayoutChange={guardar}>
 *   <DashboardTile tileId="a"><Bar data={…} /></DashboardTile>
 * </Dashboard>
 */
export const Dashboard: React.FC<DashboardProps> = ({
    layout = [],
    columns = D.columns,
    rowHeight = D.rowHeight,
    gap = D.gap,
    tileInset = D.tileInset,
    gravity = D.gravity,
    rulerMm = D.rulerMm,
    rulerOffsetMm = D.rulerOffsetMm,
    zoom = D.zoom,
    pageWidth = D.pageWidth,
    zoomControls = D.zoomControls,
    onZoomChange,
    editable = D.editable,
    fullscreen = D.fullscreen,
    fullscreenScreen = false,
    fullscreenTitle = D.fullscreenTitle,
    fullscreenPlaceholder = D.fullscreenPlaceholder,
    emptyText = D.emptyText,
    onLayoutChange,
    onRemove,
    selectedId = null,
    onSelect,
    onExitFullscreen,
    pageRows = 0,
    pageBackground = null,
    snapshotRequest,
    snapshotTitle,
    snapshotBackground,
    snapshotPageCss,
    onSnapshot,
    children,
    className = '',
    style,
}) => {
    const fromProps = useMemo(() => resolveLayout(Array.isArray(layout) ? layout : [], columns, undefined, pageRows,
        gravity),
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [JSON.stringify(layout), columns, pageRows, gravity]);
    const [items, setItems] = useState<DashboardTileLayout[]>(fromProps);
    useEffect(() => { setItems(fromProps); }, [fromProps]);

    const gridRef = useRef<HTMLDivElement | null>(null);
    const dragRef = useRef<Drag | null>(null);
    const [active, setActive] = useState<string | null>(null);
    const [live, setLive] = useState<Live | null>(null);

    // 0022 B45.1: elegir una tarjeta (clic) para ver sus propiedades; el vacío o Esc la sueltan
    const selectRef = useRef(onSelect);
    selectRef.current = onSelect;
    const selectedRef = useRef(selectedId);
    selectedRef.current = selectedId;
    const select = (id: string | null, el?: HTMLElement | null) => {
        if (!editable || !selectRef.current || id === selectedRef.current) return;
        if (id === null || !el) { selectRef.current(id); return; }
        const r = el.getBoundingClientRect();
        selectRef.current(id, { left: r.left, top: r.top, right: r.right, bottom: r.bottom });
    };
    useEffect(() => {
        if (!editable || !onSelect || typeof window === 'undefined') return undefined;
        const onKey = (e: KeyboardEvent) => {
            const tag = (e.target as HTMLElement | null)?.tagName || '';
            if (e.key === 'Escape' && selectedRef.current && !/INPUT|TEXTAREA|SELECT/.test(tag)) selectRef.current?.(null);
        };
        window.addEventListener('keydown', onKey);
        return () => window.removeEventListener('keydown', onKey);
    }, [editable, onSelect]);

    // ── pantalla completa: Esc sale; el alto se reparte entre las filas ──
    const [viewH, setViewH] = useState(() => (typeof window !== 'undefined' ? window.innerHeight : 800));
    useEffect(() => {
        if (!fullscreen || typeof window === 'undefined') return;
        const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') onExitFullscreen?.(); };
        const onResize = () => setViewH(window.innerHeight);
        window.addEventListener('keydown', onKey);
        window.addEventListener('resize', onResize);
        onResize();
        return () => { window.removeEventListener('keydown', onKey); window.removeEventListener('resize', onResize); };
    }, [fullscreen, onExitFullscreen]);
    // pantalla completa del navegador: se pide al entrar; si se sale con Esc (el navegador se queda con la tecla),
    // `fullscreenchange` avisa; al dejar de presentar, se sale
    const exitRef = useRef(onExitFullscreen);
    exitRef.current = onExitFullscreen;
    useEffect(() => {
        if (!fullscreen || !fullscreenScreen || typeof document === 'undefined') return;
        const root = document.documentElement;
        let entered = false;
        const onChange = () => {
            if (document.fullscreenElement) entered = true;
            else if (entered) exitRef.current?.();
        };
        document.addEventListener('fullscreenchange', onChange);
        if (!document.fullscreenElement && typeof root.requestFullscreen === 'function') {
            root.requestFullscreen().catch(() => { /* sin permiso: queda en toda la ventana */ });
        }
        return () => {
            document.removeEventListener('fullscreenchange', onChange);
            if (document.fullscreenElement && typeof document.exitFullscreen === 'function') {
                document.exitFullscreen().catch(() => { /* ya había salido */ });
            }
        };
    }, [fullscreen, fullscreenScreen]);
    const rows = layoutRows(items);
    const rowH = fullscreen && rows > 0
        ? Math.max(rowHeight, Math.floor((viewH - FULLSCREEN_BAR - 2 * FULLSCREEN_PAD - gap * (rows - 1)) / rows))
        : rowHeight;

    // ── mover / cambiar tamaño ──
    const startDrag = useCallback((e: React.MouseEvent, id: string, mode: Drag['mode']) => {
        if (!editable || e.button !== 0) return;
        const origin = items.find((t) => t.id === id);
        if (!origin) return;
        e.preventDefault();
        e.stopPropagation();   // ni la ventana ni el escritorio se arrastran
        dragRef.current = { id, mode, start: { x: e.clientX, y: e.clientY }, origin };
        setActive(id);
        const base = items;
        let last = base;

        const onMove = (ev: MouseEvent) => {
            const d = dragRef.current;
            const grid = gridRef.current;
            if (!d || !grid) return;
            const width = grid.offsetWidth || grid.getBoundingClientRect().width;
            const rect = grid.getBoundingClientRect();
            const scale = width > 0 && rect.width > 0 ? rect.width / width : 1;   // zoom del Desktop
            const cell = (width - gap * (columns - 1)) / columns;
            const px = (ev.clientX - d.start.x) / scale;
            const py = (ev.clientY - d.start.y) / scale;
            const dx = pxToCells(px, cell, gap);
            const dy = pxToCells(py, rowH, gap);
            const o = d.origin;
            const moved = d.mode === 'move'
                ? { ...o, x: o.x + dx, y: o.y + dy }
                : { ...o, w: o.w + dx, h: o.h + dy };
            const next = resolveLayout(base.map((t) => (t.id === d.id ? moved : t)), columns, d.id, pageRows, gravity);
            if (!sameLayout(next, last)) {
                last = next;
                setItems(next);
            }
            // la tarjeta sigue al mouse: lo que falta desde la celda donde va a quedar (la que ya está en el layout)
            const at = next.find((t) => t.id === d.id) ?? o;
            const stepX = cell + gap;
            const stepY = rowH + gap;
            setLive(d.mode === 'move'
                ? { id: d.id, mode: d.mode, ex: px - (at.x - o.x) * stepX, ey: py - (at.y - o.y) * stepY, stepX, stepY }
                : { id: d.id, mode: d.mode, ex: px - (at.w - o.w) * stepX, ey: py - (at.h - o.h) * stepY, stepX, stepY });
        };
        const onUp = () => {
            document.removeEventListener('mousemove', onMove);
            document.removeEventListener('mouseup', onUp);
            dragRef.current = null;
            setActive(null);
            setLive(null);
            if (!sameLayout(last, base)) onLayoutChange?.(last);
        };
        document.addEventListener('mousemove', onMove);
        document.addEventListener('mouseup', onUp);
    }, [editable, items, gap, columns, rowH, pageRows, gravity, onLayoutChange]);

    // ── copia para exportar: cada snapshotRequest nuevo (no el que había al montar) ──
    const rootRef = useRef<HTMLDivElement | null>(null);
    const seenRequest = useRef(snapshotRequest);
    // lo último de cada prop en refs: el callback cambia en cada render y un render nuevo no tiene que perder el pedido
    const snap = useRef({ onSnapshot, snapshotTitle, snapshotBackground, snapshotPageCss });
    snap.current = { onSnapshot, snapshotTitle, snapshotBackground, snapshotPageCss };
    useEffect(() => {
        if (snapshotRequest === seenRequest.current) return;
        seenRequest.current = snapshotRequest;
        if (!snapshotRequest) return;
        const req = snapshotRequest;
        // un cuadro después: los gráficos ya midieron su tamaño (sin cancelar: un render en el medio no lo pierde)
        requestAnimationFrame(() => {
            const el = gridRef.current ?? rootRef.current;
            const o = snap.current;
            if (!el || !o.onSnapshot) return;
            o.onSnapshot(snapshotHtml(el, { title: o.snapshotTitle, background: o.snapshotBackground,
                pageCss: o.snapshotPageCss }), req);
        });
    }, [snapshotRequest]);

    // ── tarjetas: cada hijo DashboardTile va al lugar de su tileId ──
    const content = new Map<string, React.ReactNode>();
    collectTiles(children, content);
    // formato PDF: una línea al final de cada página (al menos la primera, para ver su tamaño)
    const pages = pageRows > 0 ? Math.max(1, Math.ceil(rows / pageRows)) : 0;
    const breaks = Array.from({ length: pages }, (_, k) => k + 1);

    // ── reglas (PDF): el tamaño del lienzo, medido sin el zoom ──
    const rulers = rulerMm > 0 && !fullscreen && items.length > 0;
    const [box, setBox] = useState({ w: 0, h: 0 });
    useLayoutEffect(() => {
        if (!rulers) return undefined;
        const el = gridRef.current;
        if (!el) return undefined;
        const measure = () => setBox((b) => (b.w === el.offsetWidth && b.h === el.offsetHeight
            ? b : { w: el.offsetWidth, h: el.offsetHeight }));
        measure();
        if (typeof ResizeObserver === 'undefined') return undefined;
        const ro = new ResizeObserver(measure);
        ro.observe(el);
        return () => ro.disconnect();
    }, [rulers, items, rowH]);
    const pagePx = pageRows > 0 ? pageRows * (rowH + gap) : 0;
    // ── zoom (0022 B41): CSS zoom en la raíz (las reglas y el arrastre lo siguen); 'fit' = el ancho de la ventana ──
    const rulerPx = rulers ? RULER_SIZE + RULER_GAP : 0;
    const [fitZoom, setFitZoom] = useState(1);
    const zoomRef = useRef(onZoomChange);
    zoomRef.current = onZoomChange;
    useLayoutEffect(() => {
        if (zoom !== 'fit' || fullscreen) return undefined;
        const root = rootRef.current;
        const scroller = scrollerOf(root);
        if (!root || !scroller) return undefined;
        const measure = () => {
            const cs = getComputedStyle(scroller);
            const avail = scroller.clientWidth - (parseFloat(cs.paddingLeft) || 0) - (parseFloat(cs.paddingRight) || 0);
            const natural = (pageWidth > 0 ? pageWidth : 0) + rulerPx;
            const z = pageWidth > 0 && avail > 0 && natural > 0
                ? Math.min(ZOOM_MAX, Math.max(ZOOM_MIN, Math.floor((avail / natural) * 100) / 100)) : 1;
            setFitZoom((prev) => {
                if (prev !== z) zoomRef.current?.(z, 'fit');
                return z;
            });
        };
        measure();
        if (typeof ResizeObserver === 'undefined') return undefined;
        const ro = new ResizeObserver(measure);
        ro.observe(scroller);
        return () => ro.disconnect();
    }, [zoom, fullscreen, pageWidth, rulerPx]);
    const z = fullscreen ? 1 : zoom === 'fit' ? fitZoom
        : Math.min(ZOOM_MAX, Math.max(ZOOM_MIN, Number.isFinite(Number(zoom)) && Number(zoom) > 0 ? Number(zoom) : 1));
    // 0026 X1: la barra de zoom (−, deslizador, +, %, Ajustar) y Ctrl + rueda sobre la hoja: avisan con source 'user'
    const userZoom = useCallback((next: number | 'fit') => {
        const v = next === 'fit' ? 'fit' : Math.round(Math.min(ZOOM_MAX, Math.max(ZOOM_MIN, next)) * 100) / 100;
        zoomRef.current?.(v, 'user');
    }, []);
    const onWheel = useCallback((e: React.WheelEvent) => {
        if (!zoomControls || !e.ctrlKey) return;
        e.preventDefault();
        userZoom(z + (e.deltaY < 0 ? ZOOM_STEP : -ZOOM_STEP));
    }, [zoomControls, z, userZoom]);
    // durante un arrastre: dónde va a quedar la tarjeta, marcado en las reglas y en mm
    const liveTile = live ? items.find((t) => t.id === live.id) : undefined;
    const mark = rulers && live && liveTile ? (() => {
        const x0 = liveTile.x * live.stepX + tileInset;
        const y0 = liveTile.y * live.stepY + tileInset;
        const w = liveTile.w * live.stepX - gap - 2 * tileInset;
        const h = liveTile.h * live.stepY - gap - 2 * tileInset;
        const yPage = pagePx > 0 ? y0 % pagePx : y0;
        const mm = (v: number) => Math.round(v / rulerMm);
        return {
            top: { from: x0, to: x0 + w },
            left: { from: y0, to: y0 + h },
            text: `x ${mm(x0) + rulerOffsetMm} mm · y ${mm(yPage) + rulerOffsetMm} mm · ${mm(w)} × ${mm(h)} mm`
                + (pagePx > 0 ? ` · página ${Math.floor(y0 / pagePx) + 1}` : ''),
        };
    })() : null;

    const grid = items.length === 0 ? (
        <div className={C.empty}>{emptyText}</div>
    ) : (
        <div
            ref={gridRef}
            className={C.grid}
            onClick={(e) => { if (!(e.target as HTMLElement).closest(`.${C.tile}`)) select(null); }}
            style={{
                gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`,
                gridAutoRows: `${rowH}px`,
                gap: `${gap}px`,
                ...(pages ? { minHeight: `${pages * pageRows * (rowH + gap) - gap}px` } : {}),   // sin pasarse a otra hoja
            }}
        >
            {pageBackground?.url && (pages ? breaks : [1]).map((k) => (   // 0026 X2: una capa por página (Web: una)
                ((pageBackground.pages ?? 'all') === 'all' || k === 1) && (
                    <div key={`bg${k}`} className={C.pageBg} aria-hidden data-page={k}
                        style={{ ...backgroundStyle(pageBackground, k),
                            ...(pages ? { top: `${(k - 1) * pageRows * (rowH + gap)}px`,
                                height: `${pageRows * (rowH + gap) - gap}px` } : { top: 0, bottom: 0 }) }} />
                )
            ))}
            {breaks.map((k) => (
                <div key={`pb${k}`} className={C.pageBreak} aria-hidden
                    style={{ top: `${k * pageRows * (rowH + gap) - gap / 2}px` }}>
                    <span>fin de la página {k}</span>
                </div>
            ))}
            {live && liveTile && (
                <div className={C.drop} aria-hidden
                    style={{ gridColumn: `${liveTile.x + 1} / span ${liveTile.w}`,
                        gridRow: `${liveTile.y + 1} / span ${liveTile.h}`, margin: `${tileInset}px` }} />
            )}
            {items.map((t) => {
                const following = live && live.id === t.id ? live : null;
                const place: React.CSSProperties = {
                    gridColumn: `${t.x + 1} / span ${t.w}`, gridRow: `${t.y + 1} / span ${t.h}`,
                    ...(tileInset ? { margin: `${tileInset}px` } : {}),
                };
                if (following?.mode === 'move') {
                    place.transform = `translate(${following.ex}px, ${following.ey}px)`;
                } else if (following?.mode === 'resize') {   // el ancho y el alto, con los px que siguen al mouse
                    place.width = `calc(100% - ${2 * tileInset}px + ${following.ex}px)`;
                    place.height = `calc(100% - ${2 * tileInset}px + ${following.ey}px)`;
                    place.minWidth = '24px';
                    place.minHeight = '24px';
                    place.alignSelf = 'start';
                    place.justifySelf = 'start';
                }
                return (
                <div
                    key={t.id}
                    className={`${C.tile}${active === t.id ? ` ${C.tileActive}` : ''}${selectedId === t.id ? ` ${C.tileSelected}` : ''}${t.hideBorder ? ` ${C.tileBorderless}` : ''}`}
                    data-tile-id={t.id}
                    style={t.radius != null ? { ...place, borderRadius: `${t.radius}px` } : place}   /* 0022 B51 */
                    onClickCapture={(e) => select(t.id, e.currentTarget)}
                >
                    {!(t.hideTitle && !editable) && (
                    <div className={t.hideTitle ? `${C.head} w3f-dashboard-tile-head--bare` : C.head}
                        onMouseDown={(e) => startDrag(e, t.id, 'move')}
                        style={{ cursor: editable ? 'move' : 'default',
                                 ...(t.headBackground ? { background: t.headBackground } : {}) }}>
                        {!t.hideTitle && <span className={C.title}
                            style={t.titleStyle ? { flex: 1, ...t.titleStyle } : undefined}>{t.title ?? t.id}</span>}
                        {editable && onRemove && (
                            <button type="button" className={C.remove} aria-label={`Sacar ${t.title ?? t.id}`}
                                onMouseDown={(e) => e.stopPropagation()}
                                onClick={() => onRemove(t.id)}>×</button>
                        )}
                    </div>
                    )}
                    <div className={C.body}>{content.get(t.id) ?? null}</div>
                    {editable && (
                        <div className={C.resize} aria-label="Cambiar tamaño"
                            onMouseDown={(e) => startDrag(e, t.id, 'resize')} />
                    )}
                </div>
                );
            })}
        </div>
    );
    // las reglas en su fila y su columna, fijas al hacer scroll (como en Word): quedan siempre arriba y a la
    // izquierda de lo que se ve, mostrando los mm de esa parte de la hoja
    const ruled = rulers ? (
        <div className={C.ruled} style={{ gridTemplateColumns: `${rulerPx}px minmax(0, 1fr)`,
            gridTemplateRows: `${rulerPx}px auto` }}>
            <div className={C.rulerCorner} aria-hidden />
            <div className={C.rulerWrapTop}>
                <Ruler side="top" lengthPx={box.w} pxPerMm={rulerMm} offsetMm={rulerOffsetMm} pagePx={0}
                    mark={mark?.top} />
                {mark && <div className={C.rulerInfo}>{mark.text}</div>}
            </div>
            <div className={C.rulerWrapLeft}>
                <Ruler side="left" lengthPx={box.h} pxPerMm={rulerMm} offsetMm={rulerOffsetMm} pagePx={pagePx}
                    mark={mark?.left} />
            </div>
            <div className={C.page}>{grid}</div>
        </div>
    ) : <div className={C.page}>{grid}</div>;

    const rootCls = [C.root, className].filter(Boolean).join(' ');
    // el zoom va en un envoltorio con el ancho de la hoja (centrado): la barra de zoom queda afuera, sin escalar
    const zoomedStyle: React.CSSProperties = {
        ...(pageWidth > 0 && !fullscreen ? { width: `${pageWidth + rulerPx}px`, margin: '0 auto' } : {}),
        ...(z !== 1 ? { zoom: z } : {}),
    };
    const zoomBar = zoomControls && !fullscreen ? (
        <div className={C.zoomBar} role="toolbar" aria-label="Zoom de la hoja">
            <button type="button" className={C.zoomBtn} aria-label="Alejar" title="Alejar"
                onClick={() => userZoom(z - ZOOM_STEP)}>−</button>
            <div className={C.zoomSlider}>
                <Slider value={z} min={ZOOM_MIN} max={ZOOM_MAX} step={0.01} showValue={false} ariaLabel="Zoom" onChange={userZoom} />
            </div>
            <button type="button" className={C.zoomBtn} aria-label="Acercar" title="Acercar"
                onClick={() => userZoom(z + ZOOM_STEP)}>+</button>
            <button type="button" className={`${C.zoomBtn} ${C.zoomPct}`} aria-label="Tamaño real" title="Tamaño real (100 %)"
                onClick={() => userZoom(1)}>{Math.round(z * 100)}%</button>
            <button type="button" className={C.zoomBtn} aria-label="Ajustar a la ventana" title="Ajustar a la ventana"
                onClick={() => userZoom('fit')}>Ajustar</button>
        </div>
    ) : null;
    if (fullscreen && typeof document !== 'undefined') {
        return (
            <div className={rootCls} style={style}>
                <div className={C.placeholder}>{fullscreenPlaceholder}</div>
                {createPortal(
                    <div className={`${C.root} ${C.fullscreen}`} role="dialog" aria-label={fullscreenTitle || 'Tablero'}
                        style={{ ...style, padding: `0 ${FULLSCREEN_PAD}px ${FULLSCREEN_PAD}px` }}>
                        <div className={C.fullscreenBar} style={{ height: `${FULLSCREEN_BAR}px` }}>
                            <span>{fullscreenTitle}</span>
                            <button type="button" className={C.fullscreenExit} onClick={() => onExitFullscreen?.()}>
                                Salir (Esc)
                            </button>
                        </div>
                        {grid}
                    </div>,
                    document.body,
                )}
            </div>
        );
    }
    // con la barra, la raíz es una columna que llena el alto de su contenedor: la hoja ocupa lo que sobra y la
    // barra queda siempre al pie (y, con scroll, fija abajo)
    const cls = zoomBar ? `${rootCls} ${C.rootZoomBar}` : rootCls;
    return (
        <div ref={rootRef} className={cls} style={style} data-zoom={z} onWheel={onWheel}>
            <div className={C.zoomed} style={zoomedStyle}>{ruled}</div>
            {zoomBar}
        </div>
    );
};

export default Dashboard;
