import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { ChartMargin, ColorSchemeName, InnerDims } from './types';
import { buildColorScale, computeInnerDims, resolveColorScheme } from './utils';
import { DEFAULT_CHART_HEIGHT, DEFAULT_CHART_MARGIN, DEFAULT_CHART_WIDTH } from './constants';

/** 0022 B47 (w3f-data-analysis): un gráfico dentro de una caja con esta clase usa todo el alto que la caja le deja
 *  (descontando la leyenda, los títulos de los ejes y lo demás que haya adentro): nunca desborda ni deja barra de
 *  desplazamiento (las tarjetas del tablero). Sin la clase, el alto es el de siempre (`height` o 300). */
export const CHART_FILL_CLASS = 'w3f-chart-fill';

/** El alto de lo que hay adentro de la caja (sus hijos, los espacios entre ellos y su relleno), en px de layout. */
function contentHeight(box: HTMLElement): number {
    const cs = getComputedStyle(box);
    const kids = Array.from(box.children) as HTMLElement[];
    const gap = parseFloat(cs.rowGap || '0') || 0;
    const sum = kids.reduce((h, k) => h + k.offsetHeight, 0) + gap * Math.max(0, kids.length - 1);
    return sum + (parseFloat(cs.paddingTop) || 0) + (parseFloat(cs.paddingBottom) || 0);
}

/**
 * Observe a ref'd element's box and return its current width.
 * Falls back to an explicit `propWidth` if provided.
 * The height is either `propHeight` or `defaultHeight` — charts are
 * normally width-responsive and height-fixed.
 */
export function useChartDimensions(
    containerRef: React.RefObject<HTMLDivElement | null>,
    propWidth?: number,
    propHeight?: number,
    defaultWidth: number = DEFAULT_CHART_WIDTH,
    defaultHeight: number = DEFAULT_CHART_HEIGHT,
) {
    const [dims, setDims] = useState(() => ({
        width: propWidth ?? defaultWidth,
        height: propHeight ?? defaultHeight,
    }));
    const heightRef = useRef(dims.height);
    heightRef.current = dims.height;
    const fillRef = useRef<HTMLElement | null>(null);
    const mutationRef = useRef<MutationObserver | null>(null);
    const recomputeRef = useRef<() => void>(() => {});

    const plotRef = useRef<Element | null>(null);
    const observerRef = useRef<ResizeObserver | null>(null);

    const recompute = useCallback(() => {
        if (propWidth && propHeight) return;
        const el = containerRef.current;
        if (!el) return;
        // The plot container inside the chart (.w3f-chart > .w3f-chart__container): with the legend beside the
        // plot (legend position by CSS variables) it is narrower than the wrapper — measure that one (0022 B24)
        const plot = el.querySelector(':scope > .w3f-chart > .w3f-chart__container');
        if (plot !== plotRef.current) {
            if (plotRef.current) observerRef.current?.unobserve(plotRef.current);
            if (plot) observerRef.current?.observe(plot);
            plotRef.current = plot;
        }
        const target = plot && plot.clientWidth > 0 ? plot : el;
        // clientWidth: el ancho de layout, sin el zoom de un contenedor con transform: scale (el Desktop a 70 %).
        // getBoundingClientRect venía achicado y el gráfico usaba solo esa parte del ancho
        const w = target.clientWidth || el.clientWidth || el.getBoundingClientRect().width;
        // 0022 B47: dentro de una caja «llenar», el alto que sobra (o falta) en la caja se suma al del dibujo
        const fill = el.closest(`.${CHART_FILL_CLASS}`) as HTMLElement | null;
        if (fill !== fillRef.current) {
            if (fillRef.current) observerRef.current?.unobserve(fillRef.current);
            if (fill) observerRef.current?.observe(fill);
            fillRef.current = fill;
            // 0022 B48: si aparece o cambia algo adentro de la caja (un subtítulo, una nota), se vuelve a medir
            mutationRef.current?.disconnect();
            if (fill && typeof MutationObserver !== 'undefined') {
                mutationRef.current = new MutationObserver(() => recomputeRef.current());
                mutationRef.current.observe(fill, { childList: true, subtree: true, characterData: true });
            }
        }
        if (fill) for (const k of Array.from(fill.children)) observerRef.current?.observe(k);
        let h = propHeight ?? defaultHeight;
        if (fill && fill.clientHeight > 0) {
            const extra = fill.clientHeight - contentHeight(fill);
            h = Math.abs(extra) < 2 ? heightRef.current : Math.max(60, Math.floor(heightRef.current + extra));
        }
        setDims((prev) => {
            const next = { width: propWidth ?? Math.max(w, 100), height: h };
            return prev.width === next.width && prev.height === next.height ? prev : next;
        });
    }, [propWidth, propHeight, defaultHeight, containerRef]);
    recomputeRef.current = recompute;

    useEffect(() => {
        if (propWidth && propHeight) {
            setDims({ width: propWidth, height: propHeight });
            return;
        }
        const el = containerRef.current;
        if (!el || typeof ResizeObserver === 'undefined') {
            recompute();
            return;
        }
        const ro = new ResizeObserver(recompute);
        observerRef.current = ro;
        recompute();
        ro.observe(el);
        if (plotRef.current) ro.observe(plotRef.current);
        if (fillRef.current) ro.observe(fillRef.current);
        return () => {
            ro.disconnect();
            observerRef.current = null;
            plotRef.current = null;
            fillRef.current = null;
            mutationRef.current?.disconnect();
            mutationRef.current = null;
        };
    }, [propWidth, propHeight, recompute, containerRef]);

    return dims;
}

/**
 * Memoize the `InnerDims` (outer size minus margin) for a chart.
 */
export function useInnerDims(
    width: number,
    height: number,
    margin: ChartMargin | undefined,
    axis?: { xLabelRotate?: number; plotAspect?: number; secondaryYFactor?: number; secondaryXFactor?: number;
        twinSeries?: string; labelWrap?: boolean },
): InnerDims {
    // 0026 X7: con los rótulos del eje X girados, más lugar abajo para que entren (hasta 50 px más)
    const rot = axis?.xLabelRotate ?? 0;
    const aspect = axis?.plotAspect ?? 0;   // VX1: alto / ancho del área del dibujo
    return useMemo(() => {
        const m = margin ?? DEFAULT_CHART_MARGIN;
        // con los rótulos partidos en renglones (VX5 labelWrap), lugar para dos renglones más (si no, se cortan)
        const extra = (rot ? Math.round(Math.abs(Math.sin((rot * Math.PI) / 180)) * 50) : 0) + (axis?.labelWrap ? 28 : 0);
        // VX9: lugar para el eje de la derecha (secundario o el de la serie con su propio eje) y el de arriba
        const right = axis?.secondaryYFactor || axis?.twinSeries ? Math.max(m.right, 56) : m.right;
        const top = axis?.secondaryXFactor ? Math.max(m.top, 40) : m.top;
        const mm = right !== m.right || top !== m.top ? { ...m, right, top } : m;
        const d = computeInnerDims(width, height, extra ? { ...mm, bottom: mm.bottom + extra } : mm);
        if (aspect > 0 && d.innerWidth > 0 && d.innerHeight > 0) {
            if (d.innerWidth * aspect <= d.innerHeight) d.innerHeight = d.innerWidth * aspect;
            else d.innerWidth = d.innerHeight / aspect;
        }
        return d;
    }, [width, height, margin, rot, aspect, axis?.secondaryYFactor, axis?.secondaryXFactor, axis?.twinSeries, axis?.labelWrap]);
}

/**
 * Returns a color scale that maps an ordered list of keys to a palette.
 */
export function useColorScale<T extends string>(
    keys: readonly T[],
    scheme: ColorSchemeName | readonly string[] | undefined,
) {
    return useMemo(() => {
        const palette = resolveColorScheme(scheme);
        return buildColorScale<T>(keys, palette);
    }, [keys, scheme]);
}

/**
 * Tiny state machine for hover index tracking — re-used by most charts.
 */
export function useHoveredIndex() {
    const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
    const enter = useCallback((i: number) => setHoveredIndex(i), []);
    const leave = useCallback(() => setHoveredIndex(null), []);
    return { hoveredIndex, enter, leave };
}

/**
 * Stable ref factory that exposes the same ref API as `forwardRef`
 * without pulling `forwardRef` into every chart.
 */
export function useMergedRef<T>(
    externalRef: React.Ref<T> | undefined,
): React.RefObject<T | null> {
    const internalRef = useRef<T | null>(null);
    useEffect(() => {
        if (!externalRef) return;
        if (typeof externalRef === 'function') {
            externalRef(internalRef.current);
        } else {
            (externalRef as React.MutableRefObject<T | null>).current = internalRef.current;
        }
    }, [externalRef]);
    return internalRef;
}
