'use client'

import React, { useMemo } from 'react';
import { Group } from '@visx/group';
import { Bar as VisxBar } from '@visx/shape';
import type { BarDatum, BarInnerProps } from './Bar.types';
import { BAR_DEFAULTS } from './Bar.constants';
import { buildBarClasses, buildTooltipContent, formatTick } from './Bar.utils';
import {
    useBarAccessors,
    useBarScales,
    useBarColors,
    useBarInteraction,
    useInnerDims,
} from './Bar.hooks';
import { adaptScale, plotLeft, plotTop, wrapWords, xAxisLayout, yAxisLayout } from '../_base/axisLayout';   // 0026 X7
import { ChartAxis } from '../primitives/ChartAxis';
import { ChartGrid } from '../primitives/ChartGrid';
import { ChartReferenceLines, overlayPoints } from '../primitives/ChartReferenceLines';
import { ChartSecondaryAxes } from '../primitives/ChartSecondaryAxes';   // VX9
import { ChartErrorBars, scaleForErrors } from '../primitives/ChartErrorBars';   // VX8
import { ChartTooltip } from '../primitives/ChartTooltip';
import { barOpacity } from '../primitives/ChartSegmentLabel';   // FL15: barras atenuadas
import { ChartTooltipMini } from '../primitives/ChartTooltipMini';   // 0022 PB12.4
import { ChartLegend } from '../primitives/ChartLegend';
import { ChartHeader } from '../_base/ChartHeader';
import { BASE_CHART_CLASSES } from '../_base/constants';
import { ChartMarkDecorLayer } from '../primitives/ChartMarkDecor';   // VX3

/**
 * BarInner — the core bar chart renderer with fixed width/height.
 *
 * Use this directly when you control dimensions, or wrap with `<Bar>`
 * for responsive behavior.
 */
export const BarInner: React.FC<BarInnerProps> = (props) => {
    const {
        data,
        width,
        height,
        margin,
        className,
        unstyled = BAR_DEFAULTS.unstyled,
        bindId,
        ariaLabel,
        description,
        colorScheme,
        title,
        subtitle,
        titleSize,
        titleColor,
        subtitleSize,
        subtitleColor,
        titleAlign,
        subtitleAlign,
        titleBold,
        titleItalic,
        titleUnderline,
        subtitleBold,
        subtitleItalic,
        subtitleUnderline,
        categoryLabelSize = 10,
        valueLabelSize = 10,
        axisFontSize,
        getLabel: getLabelProp,
        getValue: getValueProp,
        showXAxis = BAR_DEFAULTS.showXAxis,
        showYAxis = BAR_DEFAULTS.showYAxis,
        showGrid = BAR_DEFAULTS.showGrid,
        showTooltip = BAR_DEFAULTS.showTooltip,
        showLegend = BAR_DEFAULTS.showLegend,
        padding = BAR_DEFAULTS.padding,
        barRadius = BAR_DEFAULTS.barRadius,
        yDomain,
        barLabels = 'none',
        barLabelPosition = 'top',
        formatY,
        highlightIndex = null,
        onHover,
        onSelect,
        mutedBars, mutedOpacity = 0.45,   // FL15
    } = props;

    const { getLabel, getValue } = useBarAccessors(getLabelProp, getValueProp);
    const dims = useInnerDims(width, height, margin, props);
    const { xScale: xScaleRaw, yScale: yScaleRaw } = useBarScales(
        data,
        dims.innerWidth,
        dims.innerHeight,
        getLabel,
        getValue,
        padding,
        yDomain,
    );
    const xScale = adaptScale(xScaleRaw, props, 'x');   // VX1: mínimo / máximo, log, al revés…
    const yScale = scaleForErrors(adaptScale(yScaleRaw, props, 'y'), data, getValue, props, 'y');   // VX1, VX8
    const colors = useBarColors(data, getLabel, colorScheme);
    const { hoveredIndex, handleEnter, handleLeave, handleClick } = useBarInteraction(
        onHover,
        onSelect,
    );

    const classes = useMemo(() => buildBarClasses(className, unstyled), [className, unstyled]);
    const yTickFormat = formatY ?? formatTick;
    const total = useMemo(() => data.reduce((s, d) => s + getValue(d), 0), [data, getValue]);

    const legendItems = useMemo(
        () => showLegend ? data.map((d, i) => ({ id: String(getLabel(d)), label: String(getLabel(d)), color: colors[i] })) : [],
        [showLegend, data, getLabel, colors],
    );

    // Empty data guard
    if (data.length === 0) {
        return (
            <div className={classes}>
                <svg
                    width={width}
                    height={height}
                    className={BASE_CHART_CLASSES.svg}
                    role="img"
                    aria-label={ariaLabel ?? 'Empty bar chart'}
                />
            </div>
        );
    }

    return (
        <div className={classes} data-bind-id={bindId}>
            <ChartHeader
                title={title} subtitle={subtitle}
                titleStyle={titleSize || titleColor || titleAlign || titleBold || titleItalic || titleUnderline ? {
                    fontSize: titleSize,
                    color: titleColor,
                    textAlign: titleAlign,
                    fontWeight: titleBold ? 700 : undefined,
                    fontStyle: titleItalic ? 'italic' : undefined,
                    textDecoration: titleUnderline ? 'underline' : undefined,
                } : undefined}
                subtitleStyle={subtitleSize || subtitleColor || subtitleAlign || subtitleBold || subtitleItalic || subtitleUnderline ? {
                    fontSize: subtitleSize,
                    color: subtitleColor,
                    textAlign: subtitleAlign,
                    fontWeight: subtitleBold ? 700 : undefined,
                    fontStyle: subtitleItalic ? 'italic' : undefined,
                    textDecoration: subtitleUnderline ? 'underline' : undefined,
                } : undefined}
            />
            <div className={BASE_CHART_CLASSES.container} style={{ position: 'relative' }}>
                <svg
                    width={width}
                    height={height}
                    className={BASE_CHART_CLASSES.svg}
                    role="img"
                    aria-label={ariaLabel ?? 'Bar chart'}
                >
                    {description && (
                        <desc>{description}</desc>
                    )}
                    <Group top={plotTop(dims, props)} left={plotLeft(dims, props)}>
                        {/* Grid */}
                        {showGrid && (
                            <ChartGrid
                                yScale={yScale}
                                width={dims.innerWidth}
                                height={dims.innerHeight}
                                axis="rows"
                            />
                        )}

                        {/* Bars */}
                        {data.map((d, i) => {
                            const label = String(getLabel(d));
                            const value = getValue(d);
                            const bw = xScale.bandwidth();
                            const barX = xScale(label) ?? 0;
                            const yBase = (yScale.range() as number[])[0];   // VX3: la base (con el eje al revés, arriba)
                            const yVal = yScale(value) ?? yBase;
                            const barY = Math.min(yBase, yVal);
                            const barHeight = Math.abs(yBase - yVal);

                            return (
                                <VisxBar
                                    key={label}
                                    x={barX}
                                    y={barY}
                                    width={bw}
                                    height={Math.max(barHeight, 0)}
                                    fill={colors[i]}
                                    opacity={(
                                        highlightIndex != null
                                            ? (highlightIndex === i ? 1 : 0.3)
                                            : hoveredIndex != null && hoveredIndex !== i ? 0.5 : 1
                                    ) * barOpacity(label, mutedBars, mutedOpacity)}
                                    stroke={highlightIndex === i ? 'var(--w3f-chart-mark-outline, #fff)' : undefined}
                                    strokeWidth={highlightIndex === i ? 2 : undefined}
                                    rx={barRadius}
                                    onMouseEnter={() => handleEnter(d, i)}
                                    onMouseLeave={handleLeave}
                                    onClick={onSelect ? () => handleClick(d, i) : undefined}
                                    style={{ cursor: onSelect ? 'pointer' : undefined, transition: 'opacity 120ms ease-out' }}
                                />
                            );
                        })}

                        {/* Bar value labels */}
                        {barLabels !== 'none' && data.map((d, i) => {
                            const value = getValue(d);
                            const labelText = barLabels === 'percent'
                                ? `${total > 0 ? ((value / total) * 100).toFixed(1) : 0}%`
                                : value.toLocaleString();
                            const bw = xScale.bandwidth();
                            const barX = xScale(String(getLabel(d))) ?? 0;
                            const barY = yScale(value) ?? 0;
                            return (
                                <text
                                    key={`lbl-${i}`}
                                    x={barX + bw / 2}
                                    y={barLabelPosition === 'inside' ? barY + valueLabelSize + 4
                                        : barLabelPosition === 'center' ? (barY + dims.innerHeight) / 2 + valueLabelSize / 3
                                        : barLabelPosition === 'base' ? dims.innerHeight - 4 : barY - 4}
                                    textAnchor="middle"
                                    fontSize={valueLabelSize}
                                    fontFamily="var(--w3f-chart-label-font, inherit)"
                                    style={{ fill: 'var(--w3f-chart-bar-value-color, var(--w3f-chart-axis-tick-label-color, #6b7280))', userSelect: 'none' }}
                                >
                                    {labelText}
                                </text>
                            );
                        })}

                        {/* Category labels — always rendered for reliable visibility */}
                        {props.xLabels !== 'none' && data.map((d, i) => {
                            const label = String(getLabel(d));
                            const bw = xScale.bandwidth();
                            const barX = xScale(label) ?? 0;
                            const ly = props.xLabels === 'top' ? -6 : dims.innerHeight + categoryLabelSize + 4;   // 0026 X7
                            const rot = props.xLabelRotate ?? 0;
                            return (
                                <text
                                    key={`cat-${i}`}
                                    x={barX + bw / 2}
                                    y={ly}
                                    transform={rot ? `rotate(${rot}, ${barX + bw / 2}, ${ly})` : undefined}
                                    textAnchor={rot ? 'end' : 'middle'}
                                    className="w3f-chart-category-label"
                                    fontSize={categoryLabelSize}
                                    fontFamily="var(--w3f-chart-label-font, inherit)"
                                    fill="var(--w3f-chart-category-label-color, var(--w3f-chart-value-label-color, #888899))"
                                >
                                    {props.labelWrap && !rot   /* VX5: los nombres largos en renglones */
                                        ? wrapWords(label, Math.max(bw - 2, 20), categoryLabelSize).map((l, k) => (
                                            <tspan key={k} x={barX + bw / 2} dy={k === 0 ? 0 : categoryLabelSize * 1.1}>{l}</tspan>))
                                        : label}
                                </text>
                            );
                        })}

                        {/* Axes — ChartAxis labels suppressed since we render our own */}
                        {showXAxis && (
                            <ChartAxis
                                scale={xScale}
                                {...xAxisLayout(dims, props)}
                                hideTickLabels
                            />
                        )}
                        {showYAxis && (
                            <ChartAxis
                                scale={yScale}
                                {...yAxisLayout(dims, props)}
                                tickFormat={yTickFormat}
                                tickFontSize={axisFontSize}
                            />
                        )}
                        <ChartErrorBars {...props} valueScale={(v: number) => yScale(v)}
                            items={data.map((d) => ({ at: (xScale(String(getLabel(d))) ?? 0) + xScale.bandwidth() / 2, row: d, value: getValue(d) }))} />
                        <ChartSecondaryAxes {...props} xScale={xScale} yScale={yScale} width={dims.innerWidth} height={dims.innerHeight} />
                        <ChartReferenceLines lines={props.referenceLines} bands={props.referenceBands} annotation={props.annotation}
                            points={overlayPoints(data)} xScale={xScale}
                            yScale={(v: number) => yScale(v)} width={dims.innerWidth} height={dims.innerHeight} />
                    </Group>
                    <ChartMarkDecorLayer {...props} />   {/* VX3: trama, hueco, borde de dos colores */}
                </svg>

                {/* Tooltip */}
                {showTooltip && hoveredIndex != null && (
                    <ChartTooltip
                        left={(xScale(String(getLabel(data[hoveredIndex]))) ?? 0) + xScale.bandwidth() / 2 + plotLeft(dims, props)}
                        top={(yScale(getValue(data[hoveredIndex])) ?? 0) + plotTop(dims, props)}
                        visible
                        offsetY={-8}
                    >
                        {buildTooltipContent(data[hoveredIndex], getLabel, getValue)}
                        {props.tooltipCharts?.[String(getLabel(data[hoveredIndex]))] && (   /* 0022 PB12.4 */
                            <ChartTooltipMini points={props.tooltipCharts[String(getLabel(data[hoveredIndex]))]}
                                kind={props.tooltipChartKind} title={props.tooltipChartTitle} />
                        )}
                    </ChartTooltip>
                )}
            </div>

            {showLegend && legendItems.length > 0 && (
                <ChartLegend items={legendItems} direction="horizontal" />
            )}
        </div>
    );
};

BarInner.displayName = 'BarInner';

export default BarInner;
