'use client'

import React, { useMemo } from 'react';
import { Group } from '@visx/group';
import { Bar as VisxBar } from '@visx/shape';
import type { HistogramInnerProps } from './Histogram.types';
import { HISTOGRAM_DEFAULTS } from './Histogram.constants';
import { buildHistogramClasses, buildTooltipContent, formatTick } from './Histogram.utils';
import {
    useHistogramBins,
    useHistogramScales,
    useHistogramColor,
    useHistogramInteraction,
    useInnerDims,
} from './Histogram.hooks';
import { adaptScale, plotLeft, plotTop, xAxisLayout, yAxisLayout } from '../_base/axisLayout';   // 0026 X7
import { ChartAxis } from '../primitives/ChartAxis';
import { ChartGrid } from '../primitives/ChartGrid';
import { ChartReferenceLines } from '../primitives/ChartReferenceLines';
import { ChartSecondaryAxes } from '../primitives/ChartSecondaryAxes';   // VX9
import { ChartTooltip } from '../primitives/ChartTooltip';
import { BASE_CHART_CLASSES } from '../_base/constants';
import { ChartHeader } from '../_base/ChartHeader';
import { ChartMarkDecorLayer } from '../primitives/ChartMarkDecor';   // VX3
import { scaleLinear } from '@visx/scale';   // VX6

export const HistogramInner: React.FC<HistogramInnerProps> = (props) => {
    const {
        data, width, height, margin, className,
        unstyled = HISTOGRAM_DEFAULTS.unstyled, bindId, ariaLabel, description, colorScheme, title, subtitle,
        binCount = HISTOGRAM_DEFAULTS.binCount,
        showXAxis = HISTOGRAM_DEFAULTS.showXAxis, showYAxis = HISTOGRAM_DEFAULTS.showYAxis,
        showGrid = HISTOGRAM_DEFAULTS.showGrid, showTooltip = HISTOGRAM_DEFAULTS.showTooltip,
        barRadius = HISTOGRAM_DEFAULTS.barRadius,
        xDomain, formatX, formatY, onHover, onSelect, bins: givenBins,
        highlightIndex = null,
        // VX6 (lo que trae matplotlib en hist)
        histCumulative = false, histDensity = false, histRangeMin, histRangeMax, histType = 'bar',
        histOrientation = 'vertical',
    } = props;

    const rawBins = useHistogramBins(data, binCount, xDomain, givenBins);
    // VX6: el rango que se cuenta, la densidad (el área suma 1) y el acumulado (cada barra suma las anteriores)
    const bins = useMemo(() => {
        let b = rawBins.filter((x) => (histRangeMin == null || x.x1 > histRangeMin) && (histRangeMax == null || x.x0 < histRangeMax));
        const total = b.reduce((s, x) => s + x.count, 0) || 1;
        if (histCumulative) {
            let run = 0;
            b = b.map((x) => { run += x.count; return { ...x, count: histDensity ? run / total : run }; });
        } else if (histDensity) {
            b = b.map((x) => ({ ...x, count: x.count / (total * ((x.x1 - x.x0) || 1)) }));
        }
        return b;
    }, [rawBins, histRangeMin, histRangeMax, histCumulative, histDensity]);
    const dims = useInnerDims(width, height, margin, props);
    const H = histOrientation === 'horizontal';
    // escalas: los valores (bordes de los intervalos) y las cantidades; acostado, se intercambian
    const { valScale, cntScale } = useMemo(() => {
        const lo = bins.length ? bins[0].x0 : 0;
        const hi = bins.length ? bins[bins.length - 1].x1 : 1;
        const max = Math.max(0, ...bins.map((x) => x.count)) || 1;
        return {
            valScale: scaleLinear<number>({ domain: [lo, hi], range: H ? [dims.innerHeight, 0] : [0, dims.innerWidth] }),
            cntScale: scaleLinear<number>({ domain: [0, max], range: H ? [0, dims.innerWidth] : [dims.innerHeight, 0], nice: true }),
        };
    }, [bins, dims.innerWidth, dims.innerHeight, H]);
    const xScale = adaptScale(H ? cntScale : valScale, props, 'x') as any;   // VX1: mínimo / máximo, log, al revés…
    const yScale = adaptScale(H ? valScale : cntScale, props, 'y') as any;   // VX1: mínimo / máximo, log, al revés…
    const val = H ? yScale : xScale;
    const cnt = H ? xScale : yScale;
    const fillColor = useHistogramColor(colorScheme);
    const { hoveredIndex, handleEnter, handleLeave, handleClick } = useHistogramInteraction(onHover, onSelect);

    const classes = useMemo(() => buildHistogramClasses(className, unstyled), [className, unstyled]);
    const xf = formatX ?? formatTick;
    const yf = formatY ?? formatTick;

    if (bins.length === 0) {
        return (
            <div className={classes}>
                <svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Empty histogram'} />
            </div>
        );
    }

    // el rectángulo de un intervalo: del borde x0 al x1 y de la base hasta su cantidad
    const cBase = (cnt.range() as number[])[0];
    const rectOf = (bin: { x0: number; x1: number; count: number }) => {
        const a = val(bin.x0) ?? 0, b = val(bin.x1) ?? 0, c = cnt(bin.count) ?? cBase;
        return H
            ? { x: Math.min(cBase, c), y: Math.min(a, b), width: Math.abs(c - cBase), height: Math.max(0, Math.abs(b - a) - 1) }
            : { x: Math.min(a, b), y: Math.min(cBase, c), width: Math.max(0, Math.abs(b - a) - 1), height: Math.abs(c - cBase) };
    };
    // VX6 (histtype step / stepfilled): el contorno escalonado de todos los intervalos
    const stepPath = () => {
        const p = (v: number, c: number) => (H ? `${c},${v}` : `${v},${c}`);
        let d = `M${p(val(bins[0].x0) ?? 0, cBase)}`;
        for (const b of bins) {
            const c = cnt(b.count) ?? cBase;
            d += ` L${p(val(b.x0) ?? 0, c)} L${p(val(b.x1) ?? 0, c)}`;
        }
        return d + ` L${p(val(bins[bins.length - 1].x1) ?? 0, cBase)}` + (histType === 'stepfilled' ? ' Z' : '');
    };

    return (
        <div className={classes} data-bind-id={bindId}>
            <ChartHeader title={title} subtitle={subtitle} />
            <div className={BASE_CHART_CLASSES.container} style={{ position: 'relative' }}>
                <svg width={width} height={height} className={BASE_CHART_CLASSES.svg} role="img" aria-label={ariaLabel ?? 'Histogram'}>
                    {description && <desc>{description}</desc>}
                    <Group top={plotTop(dims, props)} left={plotLeft(dims, props)}>
                        {showGrid && (H
                            ? <ChartGrid xScale={cnt} width={dims.innerWidth} height={dims.innerHeight} axis="columns" />
                            : <ChartGrid yScale={cnt} width={dims.innerWidth} height={dims.innerHeight} axis="rows" />)}

                        {histType !== 'bar' && (
                            <path d={stepPath()} className="w3f-chart-hist-step" fill={histType === 'stepfilled' ? fillColor : 'none'}
                                fillOpacity={0.8} stroke={fillColor} strokeWidth={2} pointerEvents="none" />
                        )}
                        {bins.map((bin, i) => {
                            const r = rectOf(bin);
                            const isHovered = hoveredIndex === i;
                            return (
                                <VisxBar
                                    key={i}
                                    {...r}
                                    fill={histType === 'bar' ? fillColor : 'transparent'}
                                    className={histType === 'bar' ? undefined : 'w3f-chart-hist-hit'}
                                    opacity={
                                        highlightIndex != null
                                            ? (highlightIndex === i ? 1 : 0.3)
                                            : hoveredIndex != null && !isHovered ? 0.4 : 0.8
                                    }
                                    stroke={highlightIndex === i ? 'var(--w3f-chart-mark-outline, #fff)' : undefined}
                                    strokeWidth={highlightIndex === i ? 2 : undefined}
                                    rx={barRadius}
                                    onMouseEnter={() => handleEnter(bin, i)}
                                    onMouseLeave={handleLeave}
                                    onClick={onSelect ? () => handleClick(bin, i) : undefined}
                                    style={{ cursor: highlightIndex === i ? 'pointer' : onSelect ? 'pointer' : undefined, transition: 'opacity 120ms ease-out' }}
                                />
                            );
                        })}

                        {showXAxis && <ChartAxis scale={xScale} {...xAxisLayout(dims, props)} tickFormat={H ? yf : xf} />}
                        {showYAxis && <ChartAxis scale={yScale} {...yAxisLayout(dims, props)} tickFormat={H ? xf : yf} />}
                        <ChartSecondaryAxes {...props} xScale={xScale} yScale={yScale} width={dims.innerWidth} height={dims.innerHeight} />
                        {!H && <ChartReferenceLines lines={props.referenceLines} bands={props.referenceBands} annotation={props.annotation}
                            points={[]} xScale={xScale}
                            yScale={(v: number) => yScale(v)} width={dims.innerWidth} height={dims.innerHeight} />}
                    </Group>
                    <ChartMarkDecorLayer {...props} />   {/* VX3: trama, hueco, borde de dos colores */}
                </svg>

                {showTooltip && hoveredIndex != null && (() => {
                    const bin = bins[hoveredIndex];
                    const r = rectOf(bin);
                    const cx = r.x + (H ? r.width : r.width / 2) + plotLeft(dims, props);
                    const cy = r.y + (H ? r.height / 2 : 0) + plotTop(dims, props);
                    return (
                        <ChartTooltip left={cx} top={cy} visible offsetY={-12}>
                            {buildTooltipContent(bin)}
                        </ChartTooltip>
                    );
                })()}
            </div>
        </div>
    );
};

HistogramInner.displayName = 'HistogramInner';
export default HistogramInner;
