'use client'

import React from 'react';
import { ChartAxis } from '../ChartAxis';

/**
 * VX9 (w3f-data-analysis): secondary axes, as matplotlib secondary_yaxis / secondary_xaxis: the same data read in
 * other units (value × factor + offset), on the right (Y) or on top (X). Only numeric axes (not categories nor dates).
 */
export interface ChartSecondaryAxesProps {
    /** Right axis: each value of the left axis × this factor (+ offset). Unset = no right axis. */
    secondaryYFactor?: number;
    secondaryYOffset?: number;
    /** Title of the right axis. */
    secondaryYLabel?: string;
    /** Top axis: each value of the bottom axis × this factor (+ offset). Unset = no top axis. */
    secondaryXFactor?: number;
    secondaryXOffset?: number;
    /** Title of the top axis. */
    secondaryXLabel?: string;
}

/** A copy of `scale` whose domain reads value × factor + offset (or null if it is not a numeric scale). */
export function convertedScale(scale: any, factor: number, offset = 0): any | null {
    if (!scale || typeof scale.copy !== 'function' || typeof scale.bandwidth === 'function') return null;
    const d = scale.domain() as unknown[];
    if (!d.length || typeof d[0] !== 'number' || !Number.isFinite(factor) || factor === 0) return null;
    return scale.copy().domain((d as number[]).map((v) => v * factor + offset));
}

const fmt = (v: number) => v.toLocaleString('es-AR', { maximumFractionDigits: 2 });

export const ChartSecondaryAxes: React.FC<ChartSecondaryAxesProps & { xScale?: any; yScale?: any; width: number; height: number }> = ({
    xScale, yScale, width, secondaryYFactor, secondaryYOffset = 0, secondaryYLabel,
    secondaryXFactor, secondaryXOffset = 0, secondaryXLabel,
}) => {
    const ys = secondaryYFactor ? convertedScale(yScale, secondaryYFactor, secondaryYOffset) : null;
    const xs = secondaryXFactor ? convertedScale(xScale, secondaryXFactor, secondaryXOffset) : null;
    if (!ys && !xs) return null;
    return (
        <g className="w3f-chart-secondary-axes">
            {ys && <ChartAxis scale={ys} orientation="right" left={width} tickFormat={fmt} label={secondaryYLabel || undefined}
                className="w3f-chart-axis--secondary" />}
            {xs && <ChartAxis scale={xs} orientation="top" top={0} tickFormat={fmt} label={secondaryXLabel || undefined}
                className="w3f-chart-axis--secondary" />}
        </g>
    );
};

ChartSecondaryAxes.displayName = 'ChartSecondaryAxes';

export default ChartSecondaryAxes;
