'use client'

import React, { useId, useLayoutEffect, useRef } from 'react';

/**
 * VX3 (w3f-data-analysis): lo que matplotlib le pone a barras, porciones y puntos y que un `fill` no alcanza:
 *
 * - `markHatch`: trama (rayado) ENCIMA del color de la marca (hatch), con su color y grosor (hatchcolor,
 *   hatch_linewidth). TM5: `'series'` = una trama distinta por serie (por color de la marca: para imprimir en blanco
 *   y negro); `markHatchSize` = la separación; `markHatchMode: 'solo'` = solo la trama, con las líneas del color de la
 *   serie sobre `markHatchBg` (papel), en lugar del relleno.
 * - TM6 `markIcon`: pictogramas, un ícono repetido dentro de la marca (persona, casa, moneda…), de `markIconSize`;
 *   `markIconMode: 'sobre'` (encima del color, de `markIconColor`) o `'solo'` (los íconos del color de la serie sobre
 *   `markHatchBg`, como un gráfico de pictogramas).
 * - `markFill: 'hollow'`: la marca hueca, con el contorno del color de su serie (fill=False).
 * - `markGapColor` con `markDash`: un borde punteado de dos colores (edgegapcolor): debajo, el borde entero del color
 *   del hueco; encima, los guiones del color del borde.
 *
 * `ChartMarkDecorLayer` va una vez dentro del <svg> de un gráfico: después de cada dibujo busca sus marcas
 * (`.visx-bar`, `.w3f-chart-slice`, `.w3f-chart-point`) y pone encima de cada una una copia decorada (sin eventos).
 * Los patrones se arman ahí mismo, uno por trama / ícono y color (así cada serie tiene el suyo). Sirve para todos los
 * gráficos sin tocar cómo dibuja cada uno, y queda en el DOM (también en el PDF).
 * El relleno tenue / hueco y el tipo de borde de la marca misma los ponen las variables CSS
 * `--w3f-chart-mark-fill-opacity` / `--w3f-chart-mark-dash` (Charts.structural.css).
 */
export type ChartMarkHatch =
    | 'none' | 'diagonal' | 'diagonal2' | 'vertical' | 'horizontal' | 'cross' | 'xcross' | 'dots' | 'series';

export type ChartMarkIcon =
    | 'none' | 'persona' | 'casa' | 'moneda' | 'auto' | 'arbol' | 'estrella' | 'corazon' | 'gota' | 'caja' | 'tilde';

export interface ChartMarkDecorProps {
    markHatch?: ChartMarkHatch;
    markHatchColor?: string;
    markHatchWidth?: number;
    /** TM5: lado de la baldosa de la trama (px): más chico = más apretada. */
    markHatchSize?: number;
    /** TM5: 'sobre' = encima del color de la marca; 'solo' = solo la trama (líneas del color de la serie). */
    markHatchMode?: 'sobre' | 'solo';
    /** TM5 / TM6: el fondo de las marcas en los modos «solo» (papel). */
    markHatchBg?: string;
    markIcon?: ChartMarkIcon;
    markIconSize?: number;
    markIconMode?: 'sobre' | 'solo';
    markIconColor?: string;
    markFill?: 'solid' | 'faint' | 'hollow';
    markDash?: 'solid' | 'dashed' | 'dotted';
    markGapColor?: string;
    markEdgeWidth?: number;
    /** VX5 (sketch_params): el trazo «dibujado a mano» de las marcas (0 = no; 1, 2, 3 = cada vez más). */
    markSketch?: number;
}

const DASH: Record<string, string> = { dashed: '6 4', dotted: '1.5 3' };
const MARKS = '.visx-bar, .w3f-chart-slice, .w3f-chart-point';
const SVG_NS = 'http://www.w3.org/2000/svg';
/** TM5: las tramas de «una por serie», en este orden (la serie n toma la n-ésima). */
export const SERIES_HATCHES: ChartMarkHatch[] = ['diagonal', 'dots', 'cross', 'vertical', 'xcross', 'horizontal', 'diagonal2'];

/** TM6: los íconos (24 × 24). */
export const ICON_PATHS: Record<string, string> = {
    persona: 'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zm0 2c-4.4 0-8 2.2-8 5v1h16v-1c0-2.8-3.6-5-8-5z',
    casa: 'M12 3 2 12h3v8h5v-5h4v5h5v-8h3z',
    moneda: 'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20zm1 5v1.1c1.5.3 2.5 1.2 2.6 2.4h-1.8c-.1-.6-.7-1-1.8-1-1 0-1.6.4-1.6 1 0 .5.5.8 1.9 1.1 2 .5 3.1 1.2 3.1 2.8 0 1.3-1 2.2-2.4 2.5V18h-2v-1.1c-1.6-.3-2.7-1.3-2.8-2.7h1.8c.1.8.8 1.2 2 1.2 1.1 0 1.7-.4 1.7-1.1 0-.6-.5-.9-2-1.2-1.9-.4-3-1.1-3-2.7 0-1.2.9-2.1 2.3-2.4V7z',
    auto: 'M5 11l1.6-4.6c.2-.5.7-.9 1.3-.9h8.2c.6 0 1.1.4 1.3.9L19 11v7h-2v-2H7v2H5zm2.5 3a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3zm9 0a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3zM7.2 10h9.6l-1-3H8.2z',
    arbol: 'M12 2 5 12h4l-4 6h6v4h2v-4h6l-4-6h4z',
    estrella: 'M12 2l3 7h7l-5.6 4.4 2.1 7.6L12 16.8 5.5 21l2.1-7.6L2 9h7z',
    corazon: 'M12 21s-8-5.2-8-11a4.5 4.5 0 0 1 8-2.8A4.5 4.5 0 0 1 20 10c0 5.8-8 11-8 11z',
    gota: 'M12 2s-7 8-7 13a7 7 0 0 0 14 0c0-5-7-13-7-13z',
    caja: 'M3 7l9-4 9 4v10l-9 4-9-4zm9 2L6 6.5v8.8l6 2.7zm1 0v9l6-2.7V6.5z',
    tilde: 'M9 16.2 4.8 12l-1.4 1.4L9 19 21 7l-1.4-1.4z',
};

const el = (tag: string, attrs: Record<string, string | number>) => {
    const e = document.createElementNS(SVG_NS, tag);
    for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, String(v));
    return e;
};

/** Las líneas de la trama en una baldosa de `s` × `s` (DOM). */
export function hatchShapes(h: ChartMarkHatch, color: string, w: number, s = 8): Element[] {
    const st = { stroke: color, 'stroke-width': w };
    const diag = () => el('line', { x1: 0, y1: s, x2: s, y2: 0, ...st });
    const diag2 = () => el('line', { x1: 0, y1: 0, x2: s, y2: s, ...st });
    const vert = () => el('line', { x1: s / 2, y1: 0, x2: s / 2, y2: s, ...st });
    const hor = () => el('line', { x1: 0, y1: s / 2, x2: s, y2: s / 2, ...st });
    if (h === 'diagonal') return [diag()];
    if (h === 'diagonal2') return [diag2()];
    if (h === 'vertical') return [vert()];
    if (h === 'horizontal') return [hor()];
    if (h === 'cross') return [vert(), hor()];
    if (h === 'xcross') return [diag(), diag2()];
    return [el('circle', { cx: s / 2, cy: s / 2, r: Math.max(0.8, w), fill: color })];
}

const copy = (mark: Element, attrs: Record<string, string>) => {
    const c = mark.cloneNode(false) as Element;
    c.removeAttribute('class');
    c.removeAttribute('style');
    c.removeAttribute('data-hl');
    for (const [k, v] of Object.entries(attrs)) c.setAttribute(k, v);
    c.setAttribute('pointer-events', 'none');
    return c;
};

/** La capa de decoración de las marcas (no dibuja nada si no se eligió trama, ícono, hueco ni borde de dos colores). */
export const ChartMarkDecorLayer: React.FC<ChartMarkDecorProps> = (p) => {
    const id = `w3f-hatch-${useId().replace(/:/g, '')}`;
    const ref = useRef<SVGGElement>(null);
    const hatch = p.markHatch && p.markHatch !== 'none' ? p.markHatch : null;
    const icon = p.markIcon && p.markIcon !== 'none' && ICON_PATHS[p.markIcon] ? p.markIcon : null;
    const hollow = p.markFill === 'hollow';
    const gap = p.markGapColor && p.markDash && p.markDash !== 'solid' ? p.markGapColor : null;
    const edgeW = String(p.markEdgeWidth ?? 1);
    const sketch = p.markSketch && p.markSketch > 0 ? p.markSketch : 0;

    useLayoutEffect(() => {
        const layer = ref.current;
        if (!layer) return;
        while (layer.firstChild) layer.removeChild(layer.firstChild);
        const svg = layer.ownerSVGElement;
        if (!svg) return;
        // VX5: el trazo a mano va en la marca misma (filtro de ruido); se saca si ya no se pide
        for (const mark of Array.from(svg.querySelectorAll(MARKS))) {
            const e = mark as SVGElement;
            if (sketch) { e.style.filter = `url(#${id}-sketch)`; e.dataset.w3fSketch = '1'; }
            else if (e.dataset.w3fSketch) { e.style.filter = ''; delete e.dataset.w3fSketch; }
        }
        if (!hatch && !icon && !hollow && !gap) return;
        const defs = el('defs', {});
        layer.appendChild(defs);
        const made = new Map<string, string>();
        const seriesOf = new Map<string, number>();   // TM5: cada color de marca = una serie
        const bg = p.markHatchBg ?? '#ffffff';
        /** El id del patrón para (tipo, color de la marca): se arma una vez. */
        const pattern = (kind: string, color: string): string => {
            const key = `${kind}|${color}`;
            const got = made.get(key);
            if (got) return got;
            const pid = `${id}-${made.size}`;
            if (kind.startsWith('icon:')) {
                const size = Math.max(6, p.markIconSize ?? 14);
                const tile = Math.round(size * 1.3);
                const pat = el('pattern', { id: pid, width: tile, height: tile, patternUnits: 'userSpaceOnUse' });
                const solo = p.markIconMode === 'solo';
                if (solo) pat.appendChild(el('rect', { width: tile, height: tile, fill: bg }));
                const off = (tile - size) / 2;
                pat.appendChild(el('path', {
                    d: ICON_PATHS[kind.slice(5)], 'fill-rule': 'evenodd',
                    fill: solo ? color : (p.markIconColor ?? 'rgba(255,255,255,0.9)'),
                    transform: `translate(${off},${off}) scale(${size / 24})`,
                }));
                defs.appendChild(pat);
            } else {
                const s = Math.max(4, p.markHatchSize ?? 8);
                const pat = el('pattern', { id: pid, width: s, height: s, patternUnits: 'userSpaceOnUse' });
                const solo = p.markHatchMode === 'solo';
                if (solo) pat.appendChild(el('rect', { width: s, height: s, fill: bg }));
                for (const shape of hatchShapes(kind as ChartMarkHatch, solo ? color : (p.markHatchColor ?? 'rgba(255,255,255,0.85)'),
                    p.markHatchWidth ?? 1, s)) pat.appendChild(shape);
                defs.appendChild(pat);
            }
            made.set(key, pid);
            return pid;
        };
        for (const mark of Array.from(svg.querySelectorAll(MARKS))) {
            if (layer.contains(mark)) continue;
            const g = el('g', {});
            // la copia va en el mismo lugar que la marca (las marcas están dentro de grupos con transform)
            const parentCtm = (mark.parentNode as SVGGraphicsElement).getCTM?.();
            const layerCtm = layer.getCTM?.();
            if (parentCtm && layerCtm) {
                const m = layerCtm.inverse().multiply(parentCtm);
                g.setAttribute('transform', `matrix(${m.a},${m.b},${m.c},${m.d},${m.e},${m.f})`);
            }
            const color = mark.getAttribute('fill') || 'currentColor';
            if (!seriesOf.has(color)) seriesOf.set(color, seriesOf.size);
            if (hatch) {
                const kind = hatch === 'series' ? SERIES_HATCHES[seriesOf.get(color)! % SERIES_HATCHES.length] : hatch;
                const solo = p.markHatchMode === 'solo';
                g.appendChild(copy(mark, { fill: `url(#${pattern(kind, solo ? color : '')})`,
                                           stroke: solo ? color : 'none', 'stroke-width': solo ? '1' : '0' }));
            }
            if (icon) {
                const solo = p.markIconMode === 'solo';
                g.appendChild(copy(mark, { fill: `url(#${pattern(`icon:${icon}`, solo ? color : '')})`,
                                           stroke: solo ? color : 'none', 'stroke-width': solo ? '1' : '0' }));
            }
            if (hollow) g.appendChild(copy(mark, { fill: 'none', stroke: color, 'stroke-width': String(Math.max(Number(edgeW), 1.5)) }));
            if (gap) {
                g.appendChild(copy(mark, { fill: 'none', stroke: gap, 'stroke-width': edgeW }));
                g.appendChild(copy(mark, {
                    fill: 'none', stroke: 'var(--w3f-chart-mark-stroke, #fff)', 'stroke-width': edgeW,
                    'stroke-dasharray': DASH[p.markDash as string] ?? '',
                }));
            }
            layer.appendChild(g);
        }
    });

    return (
        <>
            {sketch > 0 && (
                <defs>
                    <filter id={`${id}-sketch`} x="-10%" y="-10%" width="120%" height="120%">
                        <feTurbulence type="fractalNoise" baseFrequency={0.04} numOctaves={2} seed={3} />
                        <feDisplacementMap in="SourceGraphic" scale={sketch * 2.5} />
                    </filter>
                </defs>
            )}
            <g ref={ref} className="w3f-chart-mark-decor" pointerEvents="none" />
        </>
    );
};

ChartMarkDecorLayer.displayName = 'ChartMarkDecorLayer';

export const MARK_DECOR_KEYS = [
    'markHatch', 'markHatchColor', 'markHatchWidth', 'markHatchSize', 'markHatchMode', 'markHatchBg',
    'markIcon', 'markIconSize', 'markIconMode', 'markIconColor',
    'markFill', 'markDash', 'markGapColor', 'markEdgeWidth',
] as const;
