'use client'

import React from 'react';

/**
 * 0022 PB12.4 (w3f-data-analysis): un gráfico chico dentro del tooltip («tooltip de página» de Power BI): el detalle de
 * lo que está bajo el mouse (sus meses, sus productos…). `points` en orden; `kind` 'line' (en el tiempo) o 'bars'.
 */
export type ChartTooltipMiniPoint = { label: string; value: number };

export interface ChartTooltipChartProps {
    /** 0022 PB12.4: por categoría (el rótulo de la barra), los puntos del minigráfico del tooltip. */
    tooltipCharts?: Record<string, readonly ChartTooltipMiniPoint[]>;
    /** 0022 PB12.4: cómo se dibuja: 'bars' (default) o 'line'. */
    tooltipChartKind?: 'bars' | 'line';
    /** 0022 PB12.4: qué muestra (p. ej. «por mes»), debajo del minigráfico. */
    tooltipChartTitle?: string;
}

export interface ChartTooltipMiniProps {
    points: readonly ChartTooltipMiniPoint[];
    kind?: 'bars' | 'line';
    title?: string;
    width?: number;
    height?: number;
    color?: string;
}

const fmt = (v: number) => v.toLocaleString('es-AR', { maximumFractionDigits: 1 });

export const ChartTooltipMini: React.FC<ChartTooltipMiniProps> = ({ points, kind = 'bars', title, width = 180,
                                                                     height = 70, color }) => {
    if (!points || points.length === 0) return null;
    const vals = points.map((p) => Number(p.value) || 0);
    const top = Math.max(0, ...vals);
    const bottom = Math.min(0, ...vals);
    const span = top - bottom || 1;
    const fill = color || 'var(--w3f-chart-tooltip-accent, #38bdf8)';
    const y = (v: number) => height - ((v - bottom) / span) * height;
    const bw = width / points.length;
    const peak = points[vals.indexOf(top)];
    return (
        <div className="w3f-chart-tooltip-mini" style={{ marginTop: 4 }}>
            <svg width={width} height={height} role="img" aria-label={title || 'detalle'}>
                {kind === 'line' ? (
                    <polyline fill="none" stroke={fill} strokeWidth={1.5}
                        points={points.map((p, i) => `${i * bw + bw / 2},${y(vals[i])}`).join(' ')} />
                ) : points.map((p, i) => (
                    <rect key={i} x={i * bw + 1} width={Math.max(1, bw - 2)} y={Math.min(y(vals[i]), y(0))}
                        height={Math.abs(y(vals[i]) - y(0))} fill={fill} opacity={0.85}>
                        <title>{`${p.label}: ${fmt(vals[i])}`}</title>
                    </rect>
                ))}
            </svg>
            <div style={{ fontSize: '0.7em', opacity: 0.8 }}>
                {title ? `${title} · ` : ''}máx. {peak?.label}: {fmt(top)}
            </div>
        </div>
    );
};

export default ChartTooltipMini;
